Object.assign(window.CODELAB_OFFLINE_PACKS,{"lc-1768":{"key":"lc-1768","number":1768,"title":"Merge Strings Alternately","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  string mergeAlternately(string word1, string word2) {\n    const int n = min(word1.length(), word2.length());\n    string prefix;\n\n    for (int i = 0; i < n; ++i) {\n      prefix += word1[i];\n      prefix += word2[i];\n    }\n\n    return prefix + word1.substr(n) + word2.substr(n);\n  }\n};","hash":"0e3152ab8588274b424ec22e42bab07bd47acedad628dd6110100fa53f15778b","origins":[{"source":"solutions","path":"1768-Merge Strings Alternately/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public String mergeAlternately(String word1, String word2) {\n    final int n = Math.min(word1.length(), word2.length());\n    StringBuilder sb = new StringBuilder();\n\n    for (int i = 0; i < n; ++i) {\n      sb.append(word1.charAt(i));\n      sb.append(word2.charAt(i));\n    }\n\n    return sb.append(word1.substring(n)).append(word2.substring(n)).toString();\n  }\n}","hash":"aacf675e4ff0bb157a74ba2b0fb3ebf690cb6ddf24100a8d923587c74d6ba583","origins":[{"source":"solutions","path":"1768-Merge Strings Alternately/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def mergeAlternately(self, word1: str, word2: str) -> str:\n    return ''.join(a + b for a, b in zip_longest(word1, word2, fillvalue=''))","hash":"7d52965082a130c175086dd85fac855c733fc3d893140527596fc95a6d3eac34","origins":[{"source":"solutions","path":"1768-Merge Strings Alternately/solution.py"}]},{"language":"python","name":"Merge Strings Alternately.py","code":"class Solution:\n    def mergeAlternately(self, word1: str, word2: str) -> str:\n        result, i, j, n, m = [], 0, 0, len(word1), len(word2)\n        while i < n and j < m:\n            result.append(word1[i])\n            result.append(word2[j])\n            i, j = i + 1, j + 1\n        while i < n:\n            result.append(word1[i])\n            i += 1\n        while j < m:\n            result.append(word2[j])\n            j += 1\n        return ''.join(result)","hash":"33fcefc074e20dbe69b94c7fc146a3b9b1bb1d915cf760aa2c9c69f90c02710d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Merge Strings Alternately.py"}]}],"sources":["solutions"]},"lc-1770":{"key":"lc-1770","number":1770,"title":"Maximum Score from Performing Multiplication Operations","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"1770-maximum-score-from-performing-multiplication-operations/README.md","text":"<h2><a href=\"https://leetcode.com/problems/maximum-score-from-performing-multiplication-operations/\">1770. Maximum Score from Performing Multiplication Operations</a></h2><h3>Medium</h3><hr><div><p>You are given two integer arrays <code>nums</code> and <code>multipliers</code><strong> </strong>of size <code>n</code> and <code>m</code> respectively, where <code>n &gt;= m</code>. The arrays are <strong>1-indexed</strong>.</p>\n\n<p>You begin with a score of <code>0</code>. You want to perform <strong>exactly</strong> <code>m</code> operations. On the <code>i<sup>th</sup></code> operation <strong>(1-indexed)</strong>, you will:</p>\n\n<ul>\n\t<li>Choose one integer <code>x</code> from <strong>either the start or the end </strong>of the array <code>nums</code>.</li>\n\t<li>Add <code>multipliers[i] * x</code> to your score.</li>\n\t<li>Remove <code>x</code> from the array <code>nums</code>.</li>\n</ul>\n\n<p>Return <em>the <strong>maximum</strong> score after performing </em><code>m</code> <em>operations.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,2,3], multipliers = [3,2,1]\n<strong>Output:</strong> 14\n<strong>Explanation:</strong>&nbsp;An optimal solution is as follows:\n- Choose from the end, [1,2,<strong><u>3</u></strong>], adding 3 * 3 = 9 to the score.\n- Choose from the end, [1,<strong><u>2</u></strong>], adding 2 * 2 = 4 to the score.\n- Choose from the end, [<strong><u>1</u></strong>], adding 1 * 1 = 1 to the score.\nThe total score is 9 + 4 + 1 = 14.</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [-5,-3,-3,-2,7,1], multipliers = [-10,-5,3,4,6]\n<strong>Output:</strong> 102\n<strong>Explanation: </strong>An optimal solution is as follows:\n- Choose from the start, [<u><strong>-5</strong></u>,-3,-3,-2,7,1], adding -5 * -10 = 50 to the score.\n- Choose from the start, [<strong><u>-3</u></strong>,-3,-2,7,1], adding -3 * -5 = 15 to the score.\n- Choose from the start, [<strong><u>-3</u></strong>,-2,7,1], adding -3 * 3 = -9 to the score.\n- Choose from the end, [-2,7,<strong><u>1</u></strong>], adding 1 * 4 = 4 to the score.\n- Choose from the end, [-2,<strong><u>7</u></strong>], adding 7 * 6 = 42 to the score. \nThe total score is 50 + 15 - 9 + 4 + 42 = 102.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == nums.length</code></li>\n\t<li><code>m == multipliers.length</code></li>\n\t<li><code>1 &lt;= m &lt;= 10<sup>3</sup></code></li>\n\t<li><code>m &lt;= n &lt;= 10<sup>5</sup></code><code> </code></li>\n\t<li><code>-1000 &lt;= nums[i], multipliers[i] &lt;= 1000</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"1770-maximum-score-from-performing-multiplication-operations.cpp","code":"class Solution {\n  public int maximumScore(int[] nums, int[] multipliers) {\n    // dp[s][i] := max score of nums[s..e] and multipliers[i],\n    dp = new Integer[multipliers.length][multipliers.length];\n    return maximumScore(nums, 0, multipliers, 0);\n  }\n\n  private Integer[][] dp;\n\n  int maximumScore(int[] nums, int s, int[] multipliers, int i) {\n    if (i == multipliers.length)\n      return 0;\n    if (dp[s][i] != null)\n      return dp[s][i];\n\n    // # of nums picked on the start side = s,\n    // # of nums picked on the end side = i - s,\n    // so e = n - (i - s) - 1\n    final int e = nums.length - (i - s) - 1;\n    final int pickStart = nums[s] * multipliers[i] + maximumScore(nums, s + 1, multipliers, i + 1);\n    final int pickEnd = nums[e] * multipliers[i] + maximumScore(nums, s, multipliers, i + 1);\n    return dp[s][i] = Math.max(pickStart, pickEnd);\n  }\n}","hash":"9171ada1b0f75138392f7e574e032ad7f21e92d49b4662f01b1ead6dce92b196","origins":[{"source":"solutions","path":"1770-maximum-score-from-performing-multiplication-operations/1770-maximum-score-from-performing-multiplication-operations.cpp"}]},{"language":"java","name":"1770-maximum-score-from-performing-multiplication-operations.java","code":"class Solution {\n  public int maximumScore(int[] nums, int[] multipliers) {\n    // dp[s][i] := max score of nums[s..e] and multipliers[i],\n    dp = new Integer[multipliers.length][multipliers.length];\n    return maximumScore(nums, 0, multipliers, 0);\n  }\n\n  private Integer[][] dp;\n\n  int maximumScore(int[] nums, int s, int[] multipliers, int i) {\n    if (i == multipliers.length)\n      return 0;\n    if (dp[s][i] != null)\n      return dp[s][i];\n\n    // # of nums picked on the start side = s,\n    // # of nums picked on the end side = i - s,\n    // so e = n - (i - s) - 1\n    final int e = nums.length - (i - s) - 1;\n    final int pickStart = nums[s] * multipliers[i] + maximumScore(nums, s + 1, multipliers, i + 1);\n    final int pickEnd = nums[e] * multipliers[i] + maximumScore(nums, s, multipliers, i + 1);\n    return dp[s][i] = Math.max(pickStart, pickEnd);\n  }\n}","hash":"9ed20c4f7dbeba76817ebd8f861c699b0204f6c6605d973780f7d19617b81aa7","origins":[{"source":"solutions","path":"1770-maximum-score-from-performing-multiplication-operations/1770-maximum-score-from-performing-multiplication-operations.java"}]},{"language":"python","name":"Maximum Score from Performing Multiplication Operations.py","code":"class Solution:\n    def maximumScore(self, nums: List[int], multipliers: List[int]) -> int:\n        m, n = len(multipliers), len(nums)\n        dp = [0] * (m + 1)\n        for op in range(m - 1, -1, -1):\n            nextRow = dp.copy()\n            for left in range(op, -1, -1):\n                dp[left] = max(multipliers[op] * nums[left] + nextRow[left + 1],\n                              multipliers[op] * nums[n - 1 - (op - left)] + nextRow[left])\n        return dp[0]","hash":"716e1c8ccf8cf4324e2a3706ec0e2c99317eea00ec857cf80c977924c3192079","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-09 Leetcoding Challenge/Maximum Score from Performing Multiplication Operations.py"}]}],"sources":["solutions"]},"lc-1799":{"key":"lc-1799","number":1799,"title":"Maximize Score After N Operations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\npublic:\n    int maxScore(vector<int>& nums) {\n        int n = nums.size();\n        \n        \n        vector<vector<int>> gcdMatrix(n, vector<int>(n));\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                gcdMatrix[i][j] = gcdMatrix[j][i] = gcd(nums[i], nums[j]);\n            }\n        }\n        \n        \n        vector<int> dp(1 << n);\n        \n        \n        for (int state = 1; state < (1 << n); state++) {\n            \n            int cnt = __builtin_popcount(state);\n            \n            \n            if (cnt % 2 == 1) {\n                continue;\n            }\n            \n            \n            for (int i = 0; i < n; i++) {\n                if ((state & (1 << i)) == 0) {\n                    continue;\n                }\n                for (int j = i + 1; j < n; j++) {\n                    if ((state & (1 << j)) == 0) {\n                        continue;\n                    }\n                    int nextState = state ^ (1 << i) ^ (1 << j);\n                    dp[state] = max(dp[state], dp[nextState] + cnt / 2 * gcdMatrix[i][j]);\n                }\n            }\n        }\n        \n        return dp[(1 << n) - 1];\n    }\n    \n    int gcd(int a, int b) {\n        return b == 0 ? a : gcd(b, a % b);\n    }\n};","hash":"bf6042afedde2b8e3901d737082c3f8ab53ef47fcf4d2880d8bc368a0d115cb0","origins":[{"source":"solutions","path":"1799-Maximize-Score-After-N-Operations/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n    public int maxScore(int[] nums) {\n        int n = nums.length;\n        \n        \n        int[][] gcdMatrix = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                gcdMatrix[i][j] = gcdMatrix[j][i] = gcd(nums[i], nums[j]);\n            }\n        }\n        \n       \n        int[] dp = new int[1 << n];\n        \n        \n        for (int state = 1; state < (1 << n); state++) {\n            \n            int cnt = Integer.bitCount(state);\n            \n            \n            if (cnt % 2 == 1) {\n                continue;\n            }\n            \n            \n            for (int i = 0; i < n; i++) {\n                if ((state & (1 << i)) == 0) {\n                    continue;\n                }\n                for (int j = i + 1; j < n; j++) {\n                    if ((state & (1 << j)) == 0) {\n                        continue;\n                    }\n                    int nextState = state ^ (1 << i) ^ (1 << j);\n                    dp[state] = Math.max(dp[state], dp[nextState] + cnt / 2 * gcdMatrix[i][j]);\n                }\n            }\n        }\n        \n        return dp[(1 << n) - 1];\n    }\n    \n    private int gcd(int a, int b) {\n        return b == 0 ? a : gcd(b, a % b);\n    }\n}","hash":"48785eeec1748cdf5cb71325651213306cfcd6b12d13f5d2d9969887cdad8c97","origins":[{"source":"solutions","path":"1799-Maximize-Score-After-N-Operations/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n    def maxScore(self, nums: List[int]) -> int:\n        n = len(nums)\n        \n       \n        gcd_matrix = [[0] * n for _ in range(n)]\n        for i in range(n):\n            for j in range(i+1, n):\n                gcd_matrix[i][j] = gcd_matrix[j][i] = gcd(nums[i], nums[j])\n        \n      \n        dp = [0] * (1 << n)\n        \n        \n        for state in range(1, 1 << n):\n          \n            cnt = bin(state).count('1')\n            \n           \n            if cnt % 2 == 1:\n                continue\n            \n            \n            for i in range(n):\n                if not (state & (1 << i)):\n                    continue\n                for j in range(i+1, n):\n                    if not (state & (1 << j)):\n                        continue\n                    nextState = state ^ (1 << i) ^ (1 << j)\n                    dp[state] = max(dp[state], dp[nextState] + cnt // 2 * gcd_matrix[i][j])\n        \n        return dp[(1 << n) - 1]","hash":"cb4e3dfbde1f34236ff469a63d632b54f221ebde824984a8ff99449419a1b743","origins":[{"source":"solutions","path":"1799-Maximize-Score-After-N-Operations/solution.py"}]}],"sources":["solutions"]},"lc-1802":{"key":"lc-1802","number":1802,"title":"Maximum Value at a Given Index in a Bounded Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int maxValue(int n, int index, int maxSum) {\n    maxSum -= n;\n\n    int l = 0;\n    int r = maxSum;\n\n    // Find the first value x s.t. if A[index] = x\n    // Sum(A) >= maxSum\n    while (l < r) {\n      const int m = (l + r) / 2;\n      if (getSum(n, index, m) >= maxSum)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return getSum(n, index, l) > maxSum ? l : l + 1;\n  }\n\n private:\n  // Minimum sum if nums[index] = x\n  long getSum(int n, int index, int x) {\n    long l = min(index, x - 1);\n    long r = min(n - index, x);\n    long lSum = ((x - 1) + (x - 1 - l + 1)) * l / 2;\n    long rSum = (x + (x - r + 1)) * r / 2;\n    return lSum + rSum;\n  }\n};","hash":"888ce88329802352b1fe07dbcbac5d6df0ea0e6a26ad7fe59dcb18a1b3cc9689","origins":[{"source":"solutions","path":"1802-Maximum-Value-at-a-Given-Index-in-a-Bounded-Array/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int maxValue(int n, int index, int maxSum) {\n    maxSum -= n;\n\n    int l = 0;\n    int r = maxSum;\n\n    // Find the first value x s.t. if A[index] = x\n    // Sum(A) >= maxSum\n    while (l < r) {\n      final int m = (l + r) / 2;\n      if (getSum(n, index, m) >= maxSum)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return getSum(n, index, l) > maxSum ? l : l + 1;\n  }\n\n  // Minimum sum if nums[index] = x\n  private long getSum(int n, int index, int x) {\n    long l = Math.min(index, x - 1);\n    long r = Math.min(n - index, x);\n    long lSum = ((x - 1) + (x - 1 - l + 1)) * l / 2;\n    long rSum = (x + (x - r + 1)) * r / 2;\n    return lSum + rSum;\n  }\n}","hash":"7a66c04b521525e7d6adac34c59a98545e6a44bbe66bd64ad3f828f9c58ece24","origins":[{"source":"solutions","path":"1802-Maximum-Value-at-a-Given-Index-in-a-Bounded-Array/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n    def check(self, a):\n        left_offset = max(a - self.index, 0)\n        result = (a + left_offset) * (a - left_offset + 1) // 2\n        right_offset = max(a - ((self.n - 1) - self.index), 0)\n        result += (a + right_offset) * (a - right_offset + 1) // 2\n        return result - a\n\n    def maxValue(self, n, index, maxSum):\n        self.n = n\n        self.index = index\n\n        maxSum -= n\n        left, right = 0, maxSum\n        while left < right:\n            mid = (left + right + 1) // 2\n            if self.check(mid) <= maxSum:\n                left = mid\n            else:\n                right = mid - 1\n        result = left + 1\n        return result","hash":"a5c49815eeffda688ddbdb99c3f1011b5b59c6b1761f9223afb45cd98a17bbde","origins":[{"source":"solutions","path":"1802-Maximum-Value-at-a-Given-Index-in-a-Bounded-Array/solution.py"}]}],"sources":["solutions"]},"lc-1822":{"key":"lc-1822","number":1822,"title":"Sign of the Product of an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int arraySign(vector<int>& nums) {\n    int sign = 1;\n\n    for (const int num : nums) {\n      if (num == 0)\n        return 0;\n      if (num < 0)\n        sign = -sign;\n    }\n\n    return sign;\n  }\n};","hash":"1dab1acf25be10eba8afb06e74383cb8cf6f3d1fc956f53d7aa705a786d20c71","origins":[{"source":"solutions","path":"1822-Sign of the Product of an Array/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int arraySign(int[] nums) {\n    int sign = 1;\n\n    for (final int num : nums) {\n      if (num == 0)\n        return 0;\n      if (num < 0)\n        sign = -sign;\n    }\n\n    return sign;\n  }\n}","hash":"5f6a5d411d1e7b76fd11ee0f0bf01d91f48d7145f937ef3482bf0537fcabc946","origins":[{"source":"solutions","path":"1822-Sign of the Product of an Array/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def arraySign(self, nums: List[int]) -> int:\n    sign = 1\n\n    for num in nums:\n      if num == 0:\n        return 0\n      if num < 0:\n        sign = -sign\n\n    return sign","hash":"63ef5a93fc195ddc72302a91a5d781f2183f8844b3ba82f378080dcc572daec4","origins":[{"source":"solutions","path":"1822-Sign of the Product of an Array/solution.py"}]},{"language":"python","name":"Sign of the Product of an Array.py","code":"class Solution:\n    def arraySign(self, nums: List[int]) -> int:\n        result = 1\n        for num in nums:\n            if num > 0:\n                result *= 1\n            elif num < 0:\n                result *= -1\n            else:\n                result *= 0\n            if result == 0:\n                return 0\n        return result","hash":"9ca38a304e74157ce4ba6417c5d3c365c01f638978453e2a770f3a22c14dc5ff","origins":[{"source":"solutions","path":"Sign of the Product of an Array.py"}]}],"sources":["solutions"]},"lc-1832":{"key":"lc-1832","number":1832,"title":"Check if the Sentence Is Pangram","difficulty":"Easy","tags":[],"documents":[{"source":"solutions","path":"1832-check-if-the-sentence-is-pangram/README.md","text":"<h2><a href=\"https://leetcode.com/problems/check-if-the-sentence-is-pangram/\">1832. Check if the Sentence Is Pangram</a></h2><h3>Easy</h3><hr><div><p>A <strong>pangram</strong> is a sentence where every letter of the English alphabet appears at least once.</p>\n\n<p>Given a string <code>sentence</code> containing only lowercase English letters, return<em> </em><code>true</code><em> if </em><code>sentence</code><em> is a <strong>pangram</strong>, or </em><code>false</code><em> otherwise.</em></p>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n\n<pre><strong>Input:</strong> sentence = \"thequickbrownfoxjumpsoverthelazydog\"\n<strong>Output:</strong> true\n<strong>Explanation:</strong> sentence contains at least one of every letter of the English alphabet.\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n\n<pre><strong>Input:</strong> sentence = \"leetcode\"\n<strong>Output:</strong> false\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= sentence.length &lt;= 1000</code></li>\n\t<li><code>sentence</code> consists of lowercase English letters.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"1832-check-if-the-sentence-is-pangram.cpp","code":"class Solution {\n public:\n  bool checkIfPangram(string sentence) {\n    return unordered_set(begin(sentence), end(sentence)).size() == 26;\n  }\n};","hash":"1eb474e4efe97b36d800bb002cb5144f1120305a98715c4b321e45ae9b26b015","origins":[{"source":"solutions","path":"1832-check-if-the-sentence-is-pangram/1832-check-if-the-sentence-is-pangram.cpp"}]},{"language":"java","name":"1832-check-if-the-sentence-is-pangram.java","code":"class Solution {\n  public boolean checkIfPangram(String sentence) {\n    Set<Character> seen = new HashSet<>();\n\n    for (final char c : sentence.toCharArray())\n      seen.add(c);\n\n    return seen.size() == 26;\n  }\n}","hash":"1abbfa99052eef10224aed65975146a0b69d3293486ca9ca908cdf202e81b1c3","origins":[{"source":"solutions","path":"1832-check-if-the-sentence-is-pangram/1832-check-if-the-sentence-is-pangram.java"}]},{"language":"python","name":"1832-check-if-the-sentence-is-pangram.py","code":"class Solution:\n  def checkIfPangram(self, sentence: str) -> bool:\n    return len(set(sentence)) == 26","hash":"8c2d60c5e16abdc7c760722a5d54c217a52bfd0104b575f26ace9e002c3adbf6","origins":[{"source":"solutions","path":"1832-check-if-the-sentence-is-pangram/1832-check-if-the-sentence-is-pangram.py"}]},{"language":"python","name":"Check if the Sentence Is Pangram.py","code":"class Solution:\n    def checkIfPangram(self, sentence: str) -> bool:\n        return len(set(sentence)) == 26","hash":"e86db2ca7440201facce8ed7986c201f9c1fb38a606875e801de463613a1e4cb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-10 Leetcoding Challenge/Check if the Sentence Is Pangram.py"}]}],"sources":["solutions"]},"lc-1870":{"key":"lc-1870","number":1870,"title":"minimum speed to arrive on time","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int minSpeedOnTime(vector<int>& dist, double hour) {\n    int ans = -1;\n    int l = 1;\n    int r = 1e7;\n\n    while (l <= r) {\n      const int m = (l + r) / 2;\n      if (time(dist, hour, m) > hour) {\n        l = m + 1;\n      } else {\n        ans = m;\n        r = m - 1;\n      }\n    }\n\n    return ans;\n  }\n\n private:\n  double time(const vector<int>& dist, double hour, int speed) {\n    double sum = 0;\n    for (int i = 0; i < dist.size() - 1; ++i)\n      sum += ceil((double)dist[i] / speed);\n    return sum + (double)dist.back() / speed;\n  }\n};","hash":"b1f7f07022582da0b8c7cc260e848bf96dac2106d33af1b81482194b920248e2","origins":[{"source":"solutions","path":"1870-minimum-speed-to-arrive-on-time/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int minSpeedOnTime(int[] dist, double hour) {\n    int ans = -1;\n    int l = 1;\n    int r = (int) 1e7;\n\n    while (l <= r) {\n      final int m = (l + r) / 2;\n      if (time(dist, hour, m) > hour) {\n        l = m + 1;\n      } else {\n        ans = m;\n        r = m - 1;\n      }\n    }\n\n    return ans;\n  }\n\n  private double time(int[] dist, double hour, int speed) {\n    double sum = 0;\n    for (int i = 0; i < dist.length - 1; ++i)\n      sum += Math.ceil((double) dist[i] / speed);\n    return sum + (double) dist[dist.length - 1] / speed;\n  }\n}","hash":"206ea9fae5927a41bf8a49602686fc61bb1619eba18df1e2d1df2a1afed10f9b","origins":[{"source":"solutions","path":"1870-minimum-speed-to-arrive-on-time/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def minSpeedOnTime(self, dist: List[int], hour: float) -> int:\n    ans = -1\n    l = 1\n    r = int(1e7)\n\n    def time(speed: int) -> float:\n      summ = 0\n      for i in range(len(dist) - 1):\n        summ += math.ceil(dist[i] / speed)\n      return summ + dist[-1] / speed\n\n    while l <= r:\n      m = (l + r) // 2\n      if time(m) > hour:\n        l = m + 1\n      else:\n        ans = m\n        r = m - 1\n\n    return ans","hash":"0a01ed55f7488e288068975756eadcbbc5207782ac60e475b7ccb83d2509c506","origins":[{"source":"solutions","path":"1870-minimum-speed-to-arrive-on-time/solution.py"}]}],"sources":["solutions"]},"lc-1879":{"key":"lc-1879","number":1879,"title":"Minimum XOR Sum of Two Arrays","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"1879-minimum-xor-sum-of-two-arrays/README.md","text":"<h2><a href=\"https://leetcode.com/problems/minimum-xor-sum-of-two-arrays/\">1879. Minimum XOR Sum of Two Arrays</a></h2><h3>Hard</h3><hr><div><p>You are given two integer arrays <code>nums1</code> and <code>nums2</code> of length <code>n</code>.</p>\n\n<p>The <strong>XOR sum</strong> of the two integer arrays is <code>(nums1[0] XOR nums2[0]) + (nums1[1] XOR nums2[1]) + ... + (nums1[n - 1] XOR nums2[n - 1])</code> (<strong>0-indexed</strong>).</p>\n\n<ul>\n\t<li>For example, the <strong>XOR sum</strong> of <code>[1,2,3]</code> and <code>[3,2,1]</code> is equal to <code>(1 XOR 3) + (2 XOR 2) + (3 XOR 1) = 2 + 0 + 2 = 4</code>.</li>\n</ul>\n\n<p>Rearrange the elements of <code>nums2</code> such that the resulting <strong>XOR sum</strong> is <b>minimized</b>.</p>\n\n<p>Return <em>the <strong>XOR sum</strong> after the rearrangement</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums1 = [1,2], nums2 = [2,3]\n<strong>Output:</strong> 2\n<b>Explanation:</b> Rearrange <code>nums2</code> so that it becomes <code>[3,2]</code>.\nThe XOR sum is (1 XOR 3) + (2 XOR 2) = 2 + 0 = 2.</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums1 = [1,0,3], nums2 = [5,3,4]\n<strong>Output:</strong> 8\n<b>Explanation:</b> Rearrange <code>nums2</code> so that it becomes <code>[5,4,3]</code>. \nThe XOR sum is (1 XOR 5) + (0 XOR 4) + (3 XOR 3) = 4 + 4 + 0 = 8.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == nums1.length</code></li>\n\t<li><code>n == nums2.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 14</code></li>\n\t<li><code>0 &lt;= nums1[i], nums2[i] &lt;= 10<sup>7</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"python","name":"1879-minimum-xor-sum-of-two-arrays.py","code":"class Solution:\n  def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:\n    @lru_cache(None)\n    def dp(mask: int) -> int:\n      i = bin(mask).count(\"1\")\n      if i == len(nums1):\n        return 0\n      return min((nums1[i] ^ nums2[j]) + dp(mask | 1 << j)\n                 for j in range(len(nums2)) if not mask >> j & 1)\n    return dp(0)","hash":"ca53b29be5ee32eea1425d69419a2f3ea72833473be76e4a4f6b633edf2a6a33","origins":[{"source":"solutions","path":"1879-minimum-xor-sum-of-two-arrays/1879-minimum-xor-sum-of-two-arrays.py"}]}],"sources":["solutions"]},"lc-1894":{"key":"lc-1894","number":1894,"title":"find the student","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int chalkReplacer(vector<int>& chalk, int k) {\n    k %= accumulate(chalk.begin(), chalk.end(), 0L);\n    if (k == 0)\n      return 0;\n\n    for (int i = 0; i < chalk.size(); ++i) {\n      k -= chalk[i];\n      if (k < 0)\n        return i;\n    }\n\n    throw;\n  }\n};","hash":"9cad29a0aa39a19d4275c5bb84061aa4f730271b85694f7d32f3af065e933aae","origins":[{"source":"solutions","path":"1894-find-the-student/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int chalkReplacer(int[] chalk, int k) {\n    k %= Arrays.stream(chalk).asLongStream().sum();\n    if (k == 0)\n      return 0;\n\n    for (int i = 0; i < chalk.length; ++i) {\n      k -= chalk[i];\n      if (k < 0)\n        return i;\n    }\n\n    throw new IllegalArgumentException();\n  }\n}","hash":"c89891d6a963f6844d0adb204e27925098b144bcce226f97ea496f2511aadcc8","origins":[{"source":"solutions","path":"1894-find-the-student/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def chalkReplacer(self, chalk: list[int], k: int) -> int:\n    k %= sum(chalk)\n    if k == 0:\n      return 0\n\n    for i, c in enumerate(chalk):\n      k -= c\n      if k < 0:\n        return i","hash":"4bc0e83cb4e1b27cc4a493124f92731fc7932aabe3fd16a96da86dc129f307de","origins":[{"source":"solutions","path":"1894-find-the-student/solution.py"}]}],"sources":["solutions"]},"lc-1926":{"key":"lc-1926","number":1926,"title":"Nearest Exit from Entrance in Maze","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"1926-nearest-exit-from-entrance-in-maze/README.md","text":"<h2><a href=\"https://leetcode.com/problems/nearest-exit-from-entrance-in-maze/\">1926. Nearest Exit from Entrance in Maze</a></h2><h3>Medium</h3><hr><div><p>You are given an <code>m x n</code> matrix <code>maze</code> (<strong>0-indexed</strong>) with empty cells (represented as <code>'.'</code>) and walls (represented as <code>'+'</code>). You are also given the <code>entrance</code> of the maze, where <code>entrance = [entrance<sub>row</sub>, entrance<sub>col</sub>]</code> denotes the row and column of the cell you are initially standing at.</p>\n\n<p>In one step, you can move one cell <strong>up</strong>, <strong>down</strong>, <strong>left</strong>, or <strong>right</strong>. You cannot step into a cell with a wall, and you cannot step outside the maze. Your goal is to find the <strong>nearest exit</strong> from the <code>entrance</code>. An <strong>exit</strong> is defined as an <strong>empty cell</strong> that is at the <strong>border</strong> of the <code>maze</code>. The <code>entrance</code> <strong>does not count</strong> as an exit.</p>\n\n<p>Return <em>the <strong>number of steps</strong> in the shortest path from the </em><code>entrance</code><em> to the nearest exit, or </em><code>-1</code><em> if no such path exists</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n<img alt=\"\" src=\"offline/images/66b2ac2eb13b36631d91.jpg\" style=\"width: 333px; height: 253px;\">\n<pre><strong>Input:</strong> maze = [[\"+\",\"+\",\".\",\"+\"],[\".\",\".\",\".\",\"+\"],[\"+\",\"+\",\"+\",\".\"]], entrance = [1,2]\n<strong>Output:</strong> 1\n<strong>Explanation:</strong> There are 3 exits in this maze at [1,0], [0,2], and [2,3].\nInitially, you are at the entrance cell [1,2].\n- You can reach [1,0] by moving 2 steps left.\n- You can reach [0,2] by moving 1 step up.\nIt is impossible to reach [2,3] from the entrance.\nThus, the nearest exit is [0,2], which is 1 step away.\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n<img alt=\"\" src=\"offline/images/0b3fa8e0e3f2d6dd68d6.jpg\" style=\"width: 253px; height: 253px;\">\n<pre><strong>Input:</strong> maze = [[\"+\",\"+\",\"+\"],[\".\",\".\",\".\"],[\"+\",\"+\",\"+\"]], entrance = [1,0]\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> There is 1 exit in this maze at [1,2].\n[1,0] does not count as an exit since it is the entrance cell.\nInitially, you are at the entrance cell [1,0].\n- You can reach [1,2] by moving 2 steps right.\nThus, the nearest exit is [1,2], which is 2 steps away.\n</pre>\n\n<p><strong class=\"example\">Example 3:</strong></p>\n<img alt=\"\" src=\"offline/images/aabbbbc0798661c2c7c1.jpg\" style=\"width: 173px; height: 93px;\">\n<pre><strong>Input:</strong> maze = [[\".\",\"+\"]], entrance = [0,0]\n<strong>Output:</strong> -1\n<strong>Explanation:</strong> There are no exits in this maze.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>maze.length == m</code></li>\n\t<li><code>maze[i].length == n</code></li>\n\t<li><code>1 &lt;= m, n &lt;= 100</code></li>\n\t<li><code>maze[i][j]</code> is either <code>'.'</code> or <code>'+'</code>.</li>\n\t<li><code>entrance.length == 2</code></li>\n\t<li><code>0 &lt;= entrance<sub>row</sub> &lt; m</code></li>\n\t<li><code>0 &lt;= entrance<sub>col</sub> &lt; n</code></li>\n\t<li><code>entrance</code> will always be an empty cell.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"1926-nearest-exit-from-entrance-in-maze.cpp","code":"class Solution {\n public:\n  int nearestExit(vector<vector<char>>& maze, vector<int>& entrance) {\n    const int m = maze.size();\n    const int n = maze[0].size();\n    const vector<int> dirs{0, 1, 0, -1, 0};\n    int ans = 0;\n    queue<pair<int, int>> q{{{entrance[0], entrance[1]}}};\n    vector<vector<bool>> seen(m, vector<bool>(n));\n    seen[entrance[0]][entrance[1]] = true;\n\n    while (!q.empty()) {\n      ++ans;\n      for (int sz = q.size(); sz > 0; --sz) {\n        const auto [i, j] = q.front();\n        q.pop();\n        for (int k = 0; k < 4; ++k) {\n          const int x = i + dirs[k];\n          const int y = j + dirs[k + 1];\n          if (x < 0 || x == m || y < 0 || y == n)\n            continue;\n          if (seen[x][y] || maze[x][y] == '+')\n            continue;\n          if (x == 0 || x == m - 1 || y == 0 || y == n - 1)\n            return ans;\n          q.emplace(x, y);\n          seen[x][y] = true;\n        }\n      }\n    }\n\n    return -1;\n  }\n};","hash":"bfa50b7d8f3e5ff396cd55c9da8c4404db5b979091602d55538625b2c3a0a269","origins":[{"source":"solutions","path":"1926-nearest-exit-from-entrance-in-maze/1926-nearest-exit-from-entrance-in-maze.cpp"}]},{"language":"python","name":"1926-nearest-exit-from-entrance-in-maze.py","code":"class Solution:\n  def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:\n    m = len(maze)\n    n = len(maze[0])\n    dirs = [0, 1, 0, -1, 0]\n    ans = 0\n    q = deque([(entrance[0], entrance[1])])\n    seen = {(entrance[0], entrance[1])}\n\n    while q:\n      ans += 1\n      for _ in range(len(q)):\n        i, j = q.popleft()\n        for k in range(4):\n          x = i + dirs[k]\n          y = j + dirs[k + 1]\n          if x < 0 or x == m or y < 0 or y == n:\n            continue\n          if (x, y) in seen or maze[x][y] == '+':\n            continue\n          if x == 0 or x == m - 1 or y == 0 or y == n - 1:\n            return ans\n          q.append((x, y))\n          seen.add((x, y))\n\n    return -1","hash":"9e29e1c30569354ab8ac677b0f4f7c92e7e7b5670390b660d29dc8ed58652434","origins":[{"source":"solutions","path":"1926-nearest-exit-from-entrance-in-maze/1926-nearest-exit-from-entrance-in-maze.py"}]},{"language":"python","name":"Nearest Exit from Entrance in Maze.py","code":"class Solution:\n    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:\n        visited, queue = set([(entrance[0], entrance[1])]), deque([(entrance[0], entrance[1], 0)])\n        while queue:\n            x, y, steps = queue.popleft()\n            if (x == 0 or y == 0 or x == (len(maze) - 1) or y == (len(maze[0]) - 1)) and steps > 0:\n                return steps\n            for nextX, nextY in [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]:\n                if 0 <= nextX < len(maze) and 0 <= nextY < len(maze[0]) and maze[nextX][nextY] == '.' and (nextX, nextY) not in visited:\n                    visited.add((nextX, nextY))\n                    queue.append((nextX, nextY, steps + 1))\n        return -1","hash":"eb030c616dafb33c6a4f983786c3264e38a9b59591c614d7a6a7e461683020c7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-11 Leetcoding Challenge/Nearest Exit from Entrance in Maze.py"}]}],"sources":["solutions"]},"lc-1964":{"key":"lc-1964","number":1964,"title":"find the longest valid obstacle course","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  vector<int> longestObstacleCourseAtEachPosition(vector<int>& obstacles) {\n    vector<int> ans;\n    // tail[i] := the minimum tail of all increasing subseqs having length i + 1\n    // it's easy to see that tail must be an increasing array\n    vector<int> tail;\n\n    for (const int obstacle : obstacles)\n      if (tail.empty() || obstacle >= tail.back()) {\n        tail.push_back(obstacle);\n        ans.push_back(tail.size());\n      } else {\n        const int index = firstGreater(tail, obstacle);\n        tail[index] = obstacle;\n        ans.push_back(index + 1);\n      }\n\n    return ans;\n  }\n\n private:\n  // Find the first index l s.t A[l] > target\n  // Returns A.size() if can't find\n  int firstGreater(const vector<int>& A, int target) {\n    return upper_bound(begin(A), end(A), target) - begin(A);\n  }\n};","hash":"0ed3f56ac4458fe1b5111b544ca02180af47a5218336a33fc2a3f81efa362f8d","origins":[{"source":"solutions","path":"1964-find the longest valid obstacle course/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {\n    List<Integer> ans = new ArrayList<>();\n    // tail[i] := the minimum tail of all increasing subseqs with length i + 1\n    // it's easy to see that tail must be an increasing array\n    List<Integer> tail = new ArrayList<>();\n\n    for (final int obstacle : obstacles)\n      if (tail.isEmpty() || obstacle >= tail.get(tail.size() - 1)) {\n        tail.add(obstacle);\n        ans.add(tail.size());\n      } else {\n        final int index = firstGreater(tail, obstacle);\n        tail.set(index, obstacle);\n        ans.add(index + 1);\n      }\n\n    return ans.stream().mapToInt(Integer::intValue).toArray();\n  }\n\n  // Find the first index l s.t A.get(l) > target\n  // Returns obstacles.length if can't find\n  private int firstGreater(List<Integer> A, int target) {\n    int l = 0;\n    int r = A.size();\n\n    while (l < r) {\n      final int m = (l + r) / 2;\n      if (A.get(m) > target)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return l;\n  }\n}","hash":"e5eaada1ed25002e04f115f38587a7c65f926aa7b0b6235c0706ab7794e5656c","origins":[{"source":"solutions","path":"1964-find the longest valid obstacle course/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def longestObstacleCourseAtEachPosition(self, obstacles: List[int]) -> List[int]:\n    ans = []\n    # tail[i] := the minimum tail of all increasing subseqs having length i + 1\n    # it's easy to see that tail must be an increasing array\n    tail = []\n\n    for obstacle in obstacles:\n      if not tail or obstacle >= tail[-1]:\n        tail.append(obstacle)\n        ans.append(len(tail))\n      else:\n        index = bisect_right(tail, obstacle)\n        tail[index] = obstacle\n        ans.append(index + 1)\n\n    return ans","hash":"362cdee9ba7488195ee072da0d1d3b0a13da5ceab9da6ede71c658efa7d3af4f","origins":[{"source":"solutions","path":"1964-find the longest valid obstacle course/solution.py"}]}],"sources":["solutions"]},"lc-1970":{"key":"lc-1970","number":1970,"title":"Last Day Where You Can Still Cross","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int latestDayToCross(int row, int col, vector<vector<int>>& cells) {\n    int ans = 0;\n    int l = 1;\n    int r = cells.size() - 1;\n\n    while (l <= r) {\n      const int m = (l + r) / 2;\n      if (canWalk(m, row, col, cells)) {\n        ans = m;\n        l = m + 1;\n      } else {\n        r = m - 1;\n      }\n    }\n\n    return ans;\n  }\n\n private:\n  const vector<int> dirs{0, 1, 0, -1, 0};\n\n  bool canWalk(int day, int row, int col, const vector<vector<int>>& cells) {\n    vector<vector<int>> matrix(row, vector<int>(col));\n    for (int i = 0; i < day; ++i) {\n      const int x = cells[i][0] - 1;\n      const int y = cells[i][1] - 1;\n      matrix[x][y] = 1;\n    }\n\n    queue<pair<int, int>> q;\n\n    for (int j = 0; j < col; ++j)\n      if (matrix[0][j] == 0) {\n        q.emplace(0, j);\n        matrix[0][j] = 1;\n      }\n\n    while (!q.empty()) {\n      const auto [i, j] = q.front();\n      q.pop();\n      for (int k = 0; k < 4; ++k) {\n        const int x = i + dirs[k];\n        const int y = j + dirs[k + 1];\n        if (x < 0 || x == row || y < 0 || y == col)\n          continue;\n        if (matrix[x][y] == 1)\n          continue;\n        if (x == row - 1)\n          return true;\n        q.emplace(x, y);\n        matrix[x][y] = 1;\n      }\n    }\n\n    return false;\n  }\n};","hash":"b281eb25b576128af952b64a53048ea70e1fe39f481be0792f376ce13bf0bd31","origins":[{"source":"solutions","path":"1970-Last Day Where You Can Still Cross/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int latestDayToCross(int row, int col, int[][] cells) {\n    int ans = 0;\n    int l = 1;\n    int r = cells.length - 1;\n\n    while (l <= r) {\n      final int m = (l + r) / 2;\n      if (canWalk(m, row, col, cells)) {\n        ans = m;\n        l = m + 1;\n      } else {\n        r = m - 1;\n      }\n    }\n\n    return ans;\n  }\n\n  private static final int[] dirs = {0, 1, 0, -1, 0};\n\n  private boolean canWalk(int day, int row, int col, int[][] cells) {\n    int[][] matrix = new int[row][col];\n    for (int i = 0; i < day; ++i) {\n      final int x = cells[i][0] - 1;\n      final int y = cells[i][1] - 1;\n      matrix[x][y] = 1;\n    }\n\n    Queue<int[]> q = new ArrayDeque<>();\n\n    for (int j = 0; j < col; ++j)\n      if (matrix[0][j] == 0) {\n        q.offer(new int[] {0, j});\n        matrix[0][j] = 1;\n      }\n\n    while (!q.isEmpty()) {\n      final int i = q.peek()[0];\n      final int j = q.poll()[1];\n      for (int k = 0; k < 4; ++k) {\n        final int x = i + dirs[k];\n        final int y = j + dirs[k + 1];\n        if (x < 0 || x == row || y < 0 || y == col)\n          continue;\n        if (matrix[x][y] == 1)\n          continue;\n        if (x == row - 1)\n          return true;\n        q.offer(new int[] {x, y});\n        matrix[x][y] = 1;\n      }\n    }\n\n    return false;\n  }\n}","hash":"461cfb45f0aedf578b8a6fbcfb3d1ed88b7800a3576c477c528a2c67df090a94","origins":[{"source":"solutions","path":"1970-Last Day Where You Can Still Cross/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def latestDayToCross(self, row: int, col: int, cells: List[List[int]]) -> int:\n    dirs = [0, 1, 0, -1, 0]\n\n    def canWalk(day: int) -> bool:\n      matrix = [[0] * col for _ in range(row)]\n      for i in range(day):\n        x, y = cells[i]\n        matrix[x - 1][y - 1] = 1\n\n      q = collections.deque()\n\n      for j in range(col):\n        if matrix[0][j] == 0:\n          q.append((0, j))\n          matrix[0][j] = 1\n\n      while q:\n        i, j = q.popleft()\n        for k in range(4):\n          x = i + dirs[k]\n          y = j + dirs[k + 1]\n          if x < 0 or x == row or y < 0 or y == col:\n            continue\n          if matrix[x][y] == 1:\n            continue\n          if x == row - 1:\n            return True\n          q.append((x, y))\n          matrix[x][y] = 1\n\n      return False\n\n    ans = 0\n    l = 1\n    r = len(cells) - 1\n\n    while l <= r:\n      m = (l + r) // 2\n      if canWalk(m):\n        ans = m\n        l = m + 1\n      else:\n        r = m - 1\n\n    return ans","hash":"d94b9710956d6738b6f04b189355295197297e2945a7eebcbb1bae192232ff43","origins":[{"source":"solutions","path":"1970-Last Day Where You Can Still Cross/solution.py"}]}],"sources":["solutions"]},"lc-1982":{"key":"lc-1982","number":1982,"title":"Find Array Given Subset Sums","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"1982-find-array-given-subset-sums/README.md","text":"<h2><a href=\"https://leetcode.com/problems/find-array-given-subset-sums/\">1982. Find Array Given Subset Sums</a></h2><h3>Hard</h3><hr><div><p>You are given an integer <code>n</code> representing the length of an unknown array that you are trying to recover. You are also given an array <code>sums</code> containing the values of all <code>2<sup>n</sup></code> <strong>subset sums</strong> of the unknown array (in no particular order).</p>\n\n<p>Return <em>the array </em><code>ans</code><em> of length </em><code>n</code><em> representing the unknown array. If <strong>multiple</strong> answers exist, return <strong>any</strong> of them</em>.</p>\n\n<p>An array <code>sub</code> is a <strong>subset</strong> of an array <code>arr</code> if <code>sub</code> can be obtained from <code>arr</code> by deleting some (possibly zero or all) elements of <code>arr</code>. The sum of the elements in <code>sub</code> is one possible <strong>subset sum</strong> of <code>arr</code>. The sum of an empty array is considered to be <code>0</code>.</p>\n\n<p><strong>Note:</strong> Test cases are generated such that there will <strong>always</strong> be at least one correct answer.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> n = 3, sums = [-3,-2,-1,0,0,1,2,3]\n<strong>Output:</strong> [1,2,-3]\n<strong>Explanation: </strong>[1,2,-3] is able to achieve the given subset sums:\n- []: sum is 0\n- [1]: sum is 1\n- [2]: sum is 2\n- [1,2]: sum is 3\n- [-3]: sum is -3\n- [1,-3]: sum is -2\n- [2,-3]: sum is -1\n- [1,2,-3]: sum is 0\nNote that any permutation of [1,2,-3] and also any permutation of [-1,-2,3] will also be accepted.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> n = 2, sums = [0,0,0,0]\n<strong>Output:</strong> [0,0]\n<strong>Explanation:</strong> The only correct answer is [0,0].\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> n = 4, sums = [0,0,5,5,4,-1,4,9,9,-1,4,3,4,8,3,8]\n<strong>Output:</strong> [0,-1,4,5]\n<strong>Explanation:</strong> [0,-1,4,5] is able to achieve the given subset sums.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= n &lt;= 15</code></li>\n\t<li><code>sums.length == 2<sup>n</sup></code></li>\n\t<li><code>-10<sup>4</sup> &lt;= sums[i] &lt;= 10<sup>4</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"python","name":"1982-find-array-given-subset-sums.py","code":"class Solution:\n    def recoverArray(self, n, sums):\n        def dfs(n, sums):\n            if n == 1 and 0 in sums: return [max(sums, key = abs)]\n            cands = []\n\n            d = sums[1] - sums[0]\n\n            for dr in [1, -1]:\n                cnt, new = Counter(sums), []\n                if cnt[0] == 0: return []\n                for num in sums[::-dr]:\n                    if cnt[num] == 0: continue\n                    if cnt[num - d*dr] == 0: break\n                    cnt[num] -= 1\n                    new += [num]\n                    cnt[num - d*dr] -= 1\n                    \n                if len(new) == 1 << (n-1):\n                    cands += [[-d*dr] + dfs(n - 1, new[::-dr])]\n\n            return max(cands, key = len)\n        \n        sums = sorted(sums)\n        return dfs(n, sums)","hash":"7b6b07d9c986048ec0a018525061ce680ed1f84c25d51b8f7ddf629305e4a14a","origins":[{"source":"solutions","path":"1982-find-array-given-subset-sums/1982-find-array-given-subset-sums.py"}]}],"sources":["solutions"]},"lc-1987":{"key":"lc-1987","number":1987,"title":"Number of Unique Good Subsequences","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"1987-number-of-unique-good-subsequences/README.md","text":"<h2><a href=\"https://leetcode.com/problems/number-of-unique-good-subsequences/\">1987. Number of Unique Good Subsequences</a></h2><h3>Hard</h3><hr><div><p>You are given a binary string <code>binary</code>. A <strong>subsequence</strong> of <code>binary</code> is considered <strong>good</strong> if it is <strong>not empty</strong> and has <strong>no leading zeros</strong> (with the exception of <code>\"0\"</code>).</p>\n\n<p>Find the number of <strong>unique good subsequences</strong> of <code>binary</code>.</p>\n\n<ul>\n\t<li>For example, if <code>binary = \"001\"</code>, then all the <strong>good</strong> subsequences are <code>[\"0\", \"0\", \"1\"]</code>, so the <strong>unique</strong> good subsequences are <code>\"0\"</code> and <code>\"1\"</code>. Note that subsequences <code>\"00\"</code>, <code>\"01\"</code>, and <code>\"001\"</code> are not good because they have leading zeros.</li>\n</ul>\n\n<p>Return <em>the number of <strong>unique good subsequences</strong> of </em><code>binary</code>. Since the answer may be very large, return it <strong>modulo</strong> <code>10<sup>9</sup> + 7</code>.</p>\n\n<p>A <strong>subsequence</strong> is a sequence that can be derived from another sequence by deleting some or no elements without changing the order of the remaining elements.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> binary = \"001\"\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> The good subsequences of binary are [\"0\", \"0\", \"1\"].\nThe unique good subsequences are \"0\" and \"1\".\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> binary = \"11\"\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> The good subsequences of binary are [\"1\", \"1\", \"11\"].\nThe unique good subsequences are \"1\" and \"11\".</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> binary = \"101\"\n<strong>Output:</strong> 5\n<strong>Explanation:</strong> The good subsequences of binary are [\"1\", \"0\", \"1\", \"10\", \"11\", \"101\"]. \nThe unique good subsequences are \"0\", \"1\", \"10\", \"11\", and \"101\".\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= binary.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>binary</code> consists of only <code>'0'</code>s and <code>'1'</code>s.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"1987-number-of-unique-good-subsequences.cpp","code":"class Solution {\npublic:\n    int numberOfUniqueGoodSubsequences(string binary) {\n        static const int MOD = 1e9 + 7;\n\n        int ends0 = 0, ends1 = 0;\n        bool has_zero = false;\n        for (const auto& b : binary) {\n            if (b == '1') {\n                ends1 = (ends0 + ends1 + 1) % MOD;  // curr subsequences end with 1 is all prev distinct subsequences appended by 1 and plus \"1\"\n            } else {\n                ends0 = (ends0 + ends1) % MOD;  // curr subsequences end with 0 is all prev distinct subsequences appended by 0 and don't plus \"0\"\n                has_zero = true;\n            }\n        }\n        return (ends0 + ends1 + int(has_zero)) % MOD;  // add \"0\" if has_zero\n    }\n};","hash":"26b87ea8ceb1163d1cbfcbc42972d48a06a32cde9469021f3ed75a9a8bb6f7f2","origins":[{"source":"solutions","path":"1987-number-of-unique-good-subsequences/1987-number-of-unique-good-subsequences.cpp"}]}],"sources":["solutions"]},"lc-1996":{"key":"lc-1996","number":1996,"title":"The Number of Weak Characters in the Game","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"1996-the-number-of-weak-characters-in-the-game/README.md","text":"<h2><a href=\"https://leetcode.com/problems/the-number-of-weak-characters-in-the-game/\">1996. The Number of Weak Characters in the Game</a></h2><h3>Medium</h3><hr><div><p>You are playing a game that contains multiple characters, and each of the characters has <strong>two</strong> main properties: <strong>attack</strong> and <strong>defense</strong>. You are given a 2D integer array <code>properties</code> where <code>properties[i] = [attack<sub>i</sub>, defense<sub>i</sub>]</code> represents the properties of the <code>i<sup>th</sup></code> character in the game.</p>\n\n<p>A character is said to be <strong>weak</strong> if any other character has <strong>both</strong> attack and defense levels <strong>strictly greater</strong> than this character's attack and defense levels. More formally, a character <code>i</code> is said to be <strong>weak</strong> if there exists another character <code>j</code> where <code>attack<sub>j</sub> &gt; attack<sub>i</sub></code> and <code>defense<sub>j</sub> &gt; defense<sub>i</sub></code>.</p>\n\n<p>Return <em>the number of <strong>weak</strong> characters</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> properties = [[5,5],[6,3],[3,6]]\n<strong>Output:</strong> 0\n<strong>Explanation:</strong> No character has strictly greater attack and defense than the other.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> properties = [[2,2],[3,3]]\n<strong>Output:</strong> 1\n<strong>Explanation:</strong> The first character is weak because the second character has a strictly greater attack and defense.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> properties = [[1,5],[10,4],[4,3]]\n<strong>Output:</strong> 1\n<strong>Explanation:</strong> The third character is weak because the second character has a strictly greater attack and defense.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>2 &lt;= properties.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>properties[i].length == 2</code></li>\n\t<li><code>1 &lt;= attack<sub>i</sub>, defense<sub>i</sub> &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"1996-the-number-of-weak-characters-in-the-game.cpp","code":"class Solution {\npublic:\n    int numberOfWeakCharacters(vector<vector<int>>& properties) {\n        sort(begin(properties), end(properties),\n             [](const auto& a, const auto& b) {\n                 return a[0] == b[0] ? a[1] > b[1] : a[0] < b[0];\n             });\n        int result = 0, max_d = 0;\n        for (int i = size(properties) - 1; i >= 0; --i) {\n            if (properties[i][1] < max_d) {\n                ++result;\n            }\n            max_d = max(max_d, properties[i][1]);\n        }\n        return result;\n    }\n};","hash":"9ab0a68bba9f49157e46e23192f75911733e6ecec149513e09ff720ab900cd50","origins":[{"source":"solutions","path":"1996-the-number-of-weak-characters-in-the-game/1996-the-number-of-weak-characters-in-the-game.cpp"}]},{"language":"python","name":"The Number of Weak Characters in the Game.py","code":"class Solution:\n    def numberOfWeakCharacters(self, properties: List[List[int]]) -> int:\n        properties.sort(key = lambda x : (-x[0], x[1]))\n        maxDefense, result = 0, 0\n        for attack, defense in properties:\n            if defense < maxDefense:\n                result += 1\n            else:\n                maxDefense = defense\n        return result","hash":"b943686acac3d12c7525e29c46fb3f3cfdcd42e07daec6b8e302a9f8c099dd62","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-09 Leetcoding Challenge/The Number of Weak Characters in the Game.py"}]}],"sources":["solutions"]},"lc-2007":{"key":"lc-2007","number":2007,"title":"Find Original Array From Doubled Array","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2007-find-original-array-from-doubled-array/README.md","text":"<h2><a href=\"https://leetcode.com/problems/find-original-array-from-doubled-array/\">2007. Find Original Array From Doubled Array</a></h2><h3>Medium</h3><hr><div><p>An integer array <code>original</code> is transformed into a <strong>doubled</strong> array <code>changed</code> by appending <strong>twice the value</strong> of every element in <code>original</code>, and then randomly <strong>shuffling</strong> the resulting array.</p>\n\n<p>Given an array <code>changed</code>, return <code>original</code><em> if </em><code>changed</code><em> is a <strong>doubled</strong> array. If </em><code>changed</code><em> is not a <strong>doubled</strong> array, return an empty array. The elements in</em> <code>original</code> <em>may be returned in <strong>any</strong> order</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> changed = [1,3,4,2,6,8]\n<strong>Output:</strong> [1,3,4]\n<strong>Explanation:</strong> One possible original array could be [1,3,4]:\n- Twice the value of 1 is 1 * 2 = 2.\n- Twice the value of 3 is 3 * 2 = 6.\n- Twice the value of 4 is 4 * 2 = 8.\nOther original arrays could be [4,3,1] or [3,1,4].\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> changed = [6,3,0,1]\n<strong>Output:</strong> []\n<strong>Explanation:</strong> changed is not a doubled array.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> changed = [1]\n<strong>Output:</strong> []\n<strong>Explanation:</strong> changed is not a doubled array.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= changed.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= changed[i] &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2007-find-original-array-from-doubled-array.cpp","code":"class Solution {\n public:\n  vector<int> findOriginalArray(vector<int>& changed) {\n    vector<int> ans;\n    queue<int> q;\n\n    sort(begin(changed), end(changed));\n\n    for (const int num : changed)\n      if (!q.empty() && num == q.front()) {\n        q.pop();\n      } else {\n        q.push(num * 2);\n        ans.push_back(num);\n      }\n\n    return q.empty() ? ans : vector<int>();\n  }\n};","hash":"eb5d54c526fbd850337da02647d2a9dd3bc0c0d4153a2b1bdb39c2c2b7d3d749","origins":[{"source":"solutions","path":"2007-find-original-array-from-doubled-array/2007-find-original-array-from-doubled-array.cpp"}]},{"language":"java","name":"2007-find-original-array-from-doubled-array.java","code":"class Solution {\n  public int[] findOriginalArray(int[] changed) {\n    List<Integer> ans = new ArrayList<>();\n    Queue<Integer> q = new ArrayDeque<>();\n\n    Arrays.sort(changed);\n\n    for (final int num : changed)\n      if (!q.isEmpty() && num == q.peek()) {\n        q.poll();\n      } else {\n        q.offer(num * 2);\n        ans.add(num);\n      }\n\n    return q.isEmpty() ? ans.stream().mapToInt(i -> i).toArray() : new int[] {};\n  }\n}","hash":"9b8fc77c2745a6eb5f8b85b13cb80d91babd19ae54595b49ce235710fe19d189","origins":[{"source":"solutions","path":"2007-find-original-array-from-doubled-array/2007-find-original-array-from-doubled-array.java"}]},{"language":"python","name":"2007-find-original-array-from-doubled-array.py","code":"class Solution:\n  def findOriginalArray(self, changed: List[int]) -> List[int]:\n    ans = []\n    q = deque()\n\n    for num in sorted(changed):\n      if q and num == q[0]:\n        q.popleft()\n      else:\n        q.append(num * 2)\n        ans.append(num)\n\n    return [] if q else ans","hash":"f2d9a127026fbfe8479fa9d0d4aadcc5a105c00d64e477d4a266d8c72f17eb4c","origins":[{"source":"solutions","path":"2007-find-original-array-from-doubled-array/2007-find-original-array-from-doubled-array.py"}]},{"language":"python","name":"Find Original Array From Doubled Array.py","code":"class Solution:\n    def findOriginalArray(self, changed: List[int]) -> List[int]:\n        changed.sort()\n        freqMap = Counter(changed)\n        if len(changed) % 2 != 0:\n            return []\n        result = []\n        for num in changed:\n            if freqMap[num] > 0:\n                # 0 multiplication edge case\n                if num == 0 and freqMap[num] < 2:\n                    return []\n                # double doesn't exist\n                if (2 * num) not in freqMap or freqMap[2 * num] == 0:\n                    return []\n                freqMap[num] -= 1\n                freqMap[2 * num] -= 1\n                result.append(num)\n        return result","hash":"80f55ba594e768335760174d93f2d9cb015f08fdbe304efdc5dd376fb2414909","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-09 Leetcoding Challenge/Find Original Array From Doubled Array.py"}]}],"sources":["solutions"]},"lc-2022":{"key":"lc-2022","number":2022,"title":"converting 1d to 2d","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  vector<vector<int>> construct2DArray(vector<int>& original, int m, int n) {\n    if (original.size() != m * n)\n      return {};\n\n    vector<vector<int>> ans(m, vector<int>(n));\n\n    for (int i = 0; i < original.size(); ++i)\n      ans[i / n][i % n] = original[i];\n\n    return ans;\n  }\n};","hash":"14c91ca980d637a13c62514f31388f96f41fbd757e8f9ac7022224cc2dd50d7a","origins":[{"source":"solutions","path":"2022-converting-1d-to-2d/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int[][] construct2DArray(int[] original, int m, int n) {\n    if (original.length != m * n)\n      return new int[][] {};\n\n    int[][] ans = new int[m][n];\n\n    for (int i = 0; i < original.length; ++i)\n      ans[i / n][i % n] = original[i];\n\n    return ans;\n  }\n}","hash":"7c7f0ba7d85c5bdae668d7b6b7b2a8d6d5ba6b327f1eea9bb4c4394ebc195f4d","origins":[{"source":"solutions","path":"2022-converting-1d-to-2d/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def construct2DArray(self, original: list[int],\n                       m: int, n: int) -> list[list[int]]:\n    if len(original) != m * n:\n      return []\n\n    ans = [[0] * n for _ in range(m)]\n\n    for i, num in enumerate(original):\n      ans[i // n][i % n] = num\n\n    return ans","hash":"7834778cd8309fdeabb4ced22dd83f7e1736e9557d64c1f4018bceebef511552","origins":[{"source":"solutions","path":"2022-converting-1d-to-2d/solution.py"}]}],"sources":["solutions"]},"lc-2024":{"key":"lc-2024","number":2024,"title":"Maximize the Confusion of an Exam","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int maxConsecutiveAnswers(string answerKey, int k) {\n    int ans = 0;\n    int maxCount = 0;\n    vector<int> count(2);\n\n    for (int l = 0, r = 0; r < answerKey.length(); ++r) {\n      maxCount = max(maxCount, ++count[answerKey[r] == 'T']);\n      while (maxCount + k < r - l + 1)\n        --count[answerKey[l++] == 'T'];\n      ans = max(ans, r - l + 1);\n    }\n\n    return ans;\n  }\n};","hash":"ece77cb382b35dbd2bfddd3eeab0d61ae3767000f9d572ba81a4fc704c0d0990","origins":[{"source":"solutions","path":"2024-Maximize the Confusion of an Exam/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int maxConsecutiveAnswers(String answerKey, int k) {\n    int ans = 0;\n    int maxCount = 0;\n    int[] count = new int[2];\n\n    for (int l = 0, r = 0; r < answerKey.length(); ++r) {\n      maxCount = Math.max(maxCount, ++count[answerKey.charAt(r) == 'T' ? 1 : 0]);\n      while (maxCount + k < r - l + 1)\n        --count[answerKey.charAt(l++) == 'T' ? 1 : 0];\n      ans = Math.max(ans, r - l + 1);\n    }\n\n    return ans;\n  }\n}","hash":"6d168d1ebc6b37704d456830b6788c72aa60967e2bc05338953601be7cca34d1","origins":[{"source":"solutions","path":"2024-Maximize the Confusion of an Exam/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:\n    ans = 0\n    maxCount = 0\n    count = collections.Counter()\n\n    l = 0\n    for r, c in enumerate(answerKey):\n      count[c == 'T'] += 1\n      maxCount = max(maxCount, count[c == 'T'])\n      while maxCount + k < r - l + 1:\n        count[answerKey[l] == 'T'] -= 1\n        l += 1\n      ans = max(ans, r - l + 1)\n\n    return ans","hash":"a9b463f3c958f22bd1d87496dde1b3852c3e421790714d8722dcec378ef6ea53","origins":[{"source":"solutions","path":"2024-Maximize the Confusion of an Exam/solution.py"}]}],"sources":["solutions"]},"lc-2028":{"key":"lc-2028","number":2028,"title":"find missing observation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"solution.py","code":"class Solution:\n  def missingRolls(self, rolls: list[int], mean: int, n: int) -> list[int]:\n    targetSum = (len(rolls) + n) * mean\n    missingSum = targetSum - sum(rolls)\n    if missingSum > n * 6 or missingSum < n:\n      return []\n\n    ans = [missingSum // n] * n\n    for i in range(missingSum % n):\n      ans[i] += 1\n\n    return ans","hash":"219a7b42141facef88ee857828e024a8ae230662b8ba4e96232cd52af3c43627","origins":[{"source":"solutions","path":"2028-find-missing-observation/solution.py"}]}],"sources":["solutions"]},"lc-2059":{"key":"lc-2059","number":2059,"title":"minimum operations to convert number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"java","name":"2059-minimum-operations-to-convert-number.java","code":"class Solution {\n  public int minimumOperations(int[] nums, int start, int goal) {\n    int ans = 0;\n    Queue<Integer> q = new ArrayDeque<>(Arrays.asList(start));\n    boolean[] seen = new boolean[1001];\n    seen[start] = true;\n\n    while (!q.isEmpty()) {\n      ++ans;\n      for (int sz = q.size(); sz > 0; --sz) {\n        final int x = q.poll();\n        for (final int num : nums) {\n          for (final int res : new int[] {x + num, x - num, x ^ num}) {\n            if (res == goal)\n              return ans;\n            if (res < 0 || res > 1000 || seen[res])\n              continue;\n            seen[res] = true;\n            q.offer(res);\n          }\n        }\n      }\n    }\n\n    return -1;\n  }\n}","hash":"bb30e9203d5d58f338603769da5fa8eecac31897706a92b91336c29c0fd57647","origins":[{"source":"solutions","path":"2059-minimum-operations-to-convert-number/2059-minimum-operations-to-convert-number.java"}]}],"sources":["solutions"]},"lc-2077":{"key":"lc-2077","number":2077,"title":"Paths in Maze That Lead to Same Room","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2077-paths-in-maze-that-lead-to-same-room/README.md","text":"<h2><a href=\"https://leetcode.com/problems/paths-in-maze-that-lead-to-same-room/\">2077. Paths in Maze That Lead to Same Room</a></h2><h3>Medium</h3><hr><div><p>A maze consists of <code>n</code> rooms numbered from <code>1</code> to <code>n</code>, and some rooms are connected by corridors. You are given a 2D integer array <code>corridors</code> where <code>corridors[i] = [room1<sub>i</sub>, room2<sub>i</sub>]</code> indicates that there is a corridor connecting <code>room1<sub>i</sub></code> and <code>room2<sub>i</sub></code>, allowing a person in the maze to go from <code>room1<sub>i</sub></code> to <code>room2<sub>i</sub></code> <strong>and vice versa</strong>.</p>\n\n<p>The designer of the maze wants to know how confusing the maze is. The <strong>confusion</strong> <strong>score</strong> of the maze is the number of different cycles of <strong>length 3</strong>.</p>\n\n<ul>\n\t<li>For example, <code>1 → 2 → 3 → 1</code> is a cycle of length 3, but <code>1 → 2 → 3 → 4</code> and <code>1 → 2 → 3 → 2 → 1</code> are not.</li>\n</ul>\n\n<p>Two cycles are considered to be <strong>different</strong> if one or more of the rooms visited in the first cycle is <strong>not</strong> in the second cycle.</p>\n\n<p>Return <em>the</em> <em><strong>confusion</strong><strong> score</strong> of the maze.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n<img src=\"offline/images/00a79fada0e4afb7599c.png\" style=\"width: 440px; height: 350px;\">\n<pre><strong>Input:</strong> n = 5, corridors = [[1,2],[5,2],[4,1],[2,4],[3,1],[3,4]]\n<strong>Output:</strong> 2\n<strong>Explanation:</strong>\nOne cycle of length 3 is 4 → 1 → 3 → 4, denoted in red.\nNote that this is the same cycle as 3 → 4 → 1 → 3 or 1 → 3 → 4 → 1 because the rooms are the same.\nAnother cycle of length 3 is 1 → 2 → 4 → 1, denoted in blue.\nThus, there are two different cycles of length 3.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n<img src=\"offline/images/502b008d25a2936d4d7e.png\" style=\"width: 329px; height: 250px;\">\n<pre><strong>Input:</strong> n = 4, corridors = [[1,2],[3,4]]\n<strong>Output:</strong> 0\n<strong>Explanation:</strong>\nThere are no cycles of length 3.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>2 &lt;= n &lt;= 1000</code></li>\n\t<li><code>1 &lt;= corridors.length &lt;= 5 * 10<sup>4</sup></code></li>\n\t<li><code>corridors[i].length == 2</code></li>\n\t<li><code>1 &lt;= room1<sub>i</sub>, room2<sub>i</sub> &lt;= n</code></li>\n\t<li><code>room1<sub>i</sub> != room2<sub>i</sub></code></li>\n\t<li>There are no duplicate corridors.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2077-paths-in-maze-that-lead-to-same-room.cpp","code":"// solved by Milon\nclass Solution {\npublic:\n    int numberOfPaths(int n, vector<vector<int>>& corridors) {\n        unordered_map<int, unordered_set<int>> container;\n        for (auto &cor : corridors) {\n            if (cor[0] > cor[1]) swap(cor[0], cor[1]);\n            container[cor[0]].insert(cor[1]);\n        }\n        int cnt = 0;\n        for (auto &cor : corridors) {\n            int u = cor[0];\n            int v = cor[1];\n            auto &uSet = container[u];\n            auto &vSet = container[v];\n            for (auto &num : uSet) {\n                if (vSet.find(num) != vSet.end()) {\n                    cnt++;\n                }\n            }\n        }\n        return cnt;\n    }\n};","hash":"e3c0e771000f47b23b1f326d68b3c18ced2cf51052ccb3536411dfd99d7bc5c8","origins":[{"source":"premium","path":"2077-paths-in-maze-that-lead-to-same-room/2077-paths-in-maze-that-lead-to-same-room.cpp"}]}],"sources":["premium"]},"lc-2083":{"key":"lc-2083","number":2083,"title":"Substrings That Begin and End With the Same Letter","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2083-substrings-that-begin-and-end-with-the-same-letter/README.md","text":"<h2><a href=\"https://leetcode.com/problems/substrings-that-begin-and-end-with-the-same-letter/\">2083. Substrings That Begin and End With the Same Letter</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> string <code>s</code> consisting of only lowercase English letters. Return <em>the number of <strong>substrings</strong> in </em><code>s</code> <em>that begin and end with the <strong>same</strong> character.</em></p>\n\n<p>A <strong>substring</strong> is a contiguous non-empty sequence of characters within a string.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> s = \"abcba\"\n<strong>Output:</strong> 7\n<strong>Explanation:</strong>\nThe substrings of length 1 that start and end with the same letter are: \"a\", \"b\", \"c\", \"b\", and \"a\".\nThe substring of length 3 that starts and ends with the same letter is: \"bcb\".\nThe substring of length 5 that starts and ends with the same letter is: \"abcba\".\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> s = \"abacad\"\n<strong>Output:</strong> 9\n<strong>Explanation:</strong>\nThe substrings of length 1 that start and end with the same letter are: \"a\", \"b\", \"a\", \"c\", \"a\", and \"d\".\nThe substrings of length 3 that start and end with the same letter are: \"aba\" and \"aca\".\nThe substring of length 5 that starts and ends with the same letter is: \"abaca\".\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> s = \"a\"\n<strong>Output:</strong> 1\n<strong>Explanation:</strong>\nThe substring of length 1 that starts and ends with the same letter is: \"a\".\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= s.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>s</code> consists only of lowercase English letters.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2083-substrings-that-begin-and-end-with-the-same-letter.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    long long numberOfSubstrings(string s) {\n        unordered_map<char, int> degree;\n        for (auto ch : s) {\n            degree[ch]++;\n        }\n        long long ans = 0;\n        for (auto it : degree) {\n            ans += ((long long)it.second*(it.second + 1ll))/2ll;\n        }\n        return ans;\n    }\n};","hash":"5dd9f679934d5fe459237dd071ace05d0273bcfb2e3876f7f15e00f2cde4c884","origins":[{"source":"premium","path":"2083-substrings-that-begin-and-end-with-the-same-letter/2083-substrings-that-begin-and-end-with-the-same-letter.cpp"}]}],"sources":["premium"]},"lc-2090":{"key":"lc-2090","number":2090,"title":"k radius subarray averages","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  vector<int> getAverages(vector<int>& nums, int k) {\n    const int n = nums.size();\n    const int size = 2 * k + 1;\n    vector<int> ans(n, -1);\n    if (size > n)\n      return ans;\n\n    long sum = accumulate(nums.begin(), nums.begin() + size, 0L);\n\n    for (int i = k; i + k < n; ++i) {\n      ans[i] = sum / size;\n      if (i + k + 1 < n)\n        sum += nums[i + k + 1] - nums[i - k];\n    }\n\n    return ans;\n  }\n};","hash":"d7c7b35060eb1c3412912869031fdbae80784e2c6641d8bb65f67c574db6b7eb","origins":[{"source":"solutions","path":"2090-k-radius-subarray-averages/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int[] getAverages(int[] nums, int k) {\n    final int n = nums.length;\n    final int size = 2 * k + 1;\n    int[] ans = new int[n];\n    Arrays.fill(ans, -1);\n    if (size > n)\n      return ans;\n\n    long sum = 0;\n\n    for (int i = 0; i < size; ++i)\n      sum += nums[i];\n\n    for (int i = k; i + k < n; ++i) {\n      ans[i] = (int) (sum / size);\n      if (i + k + 1 < n)\n        sum += nums[i + k + 1] - nums[i - k];\n    }\n\n    return ans;\n  }\n}","hash":"30fe1e70a6cfd8eb36bd403ae10e5a141d6f8cd9852259704af7a22f92e2251c","origins":[{"source":"solutions","path":"2090-k-radius-subarray-averages/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def getAverages(self, nums: List[int], k: int) -> List[int]:\n    n = len(nums)\n    size = 2 * k + 1\n    ans = [-1] * n\n    if size > n:\n      return ans\n\n    summ = sum(nums[:size])\n\n    for i in range(k, n - k):\n      ans[i] = summ // size\n      if i + k + 1 < n:\n        summ += nums[i + k + 1] - nums[i - k]\n\n    return ans","hash":"962ba076a533ed7f0b6e3dacaebd327b1a9fa869ffcfd73d767b4bf3ef281cd0","origins":[{"source":"solutions","path":"2090-k-radius-subarray-averages/solution.py"}]}],"sources":["solutions"]},"lc-2093":{"key":"lc-2093","number":2093,"title":"Minimum Cost to Reach City With Discounts","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2093-minimum-cost-to-reach-city-with-discounts/README.md","text":"<h2><a href=\"https://leetcode.com/problems/minimum-cost-to-reach-city-with-discounts/\">2093. Minimum Cost to Reach City With Discounts</a></h2><h3>Medium</h3><hr><div><p>A series of highways connect <code>n</code> cities numbered from <code>0</code> to <code>n - 1</code>. You are given a 2D integer array <code>highways</code> where <code>highways[i] = [city1<sub>i</sub>, city2<sub>i</sub>, toll<sub>i</sub>]</code> indicates that there is a highway that connects <code>city1<sub>i</sub></code> and <code>city2<sub>i</sub></code>, allowing a car to go from <code>city1<sub>i</sub></code> to <code>city2<sub>i</sub></code> <strong>and vice versa</strong> for a cost of <code>toll<sub>i</sub></code>.</p>\n\n<p>You are also given an integer <code>discounts</code> which represents the number of discounts you have. You can use a discount to travel across the <code>i<sup>th</sup></code> highway for a cost of <code>toll<sub>i</sub> / 2</code> (<strong>integer</strong> <strong>division</strong>). Each discount may only be used <strong>once</strong>, and you can only use at most <strong>one</strong> discount per highway.</p>\n\n<p>Return <em>the <strong>minimum total cost</strong> to go from city </em><code>0</code><em> to city </em><code>n - 1</code><em>, or </em><code>-1</code><em> if it is not possible to go from city </em><code>0</code><em> to city </em><code>n - 1</code><em>.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong><br>\n<img src=\"offline/images/9b7e2b3a5790722fcbc7.png\" style=\"height: 250px; width: 404px;\"></p>\n\n<pre><strong>Input:</strong> n = 5, highways = [[0,1,4],[2,1,3],[1,4,11],[3,2,3],[3,4,2]], discounts = 1\n<strong>Output:</strong> 9\n<strong>Explanation:</strong>\nGo from 0 to 1 for a cost of 4.\nGo from 1 to 4 and use a discount for a cost of 11 / 2 = 5.\nThe minimum cost to go from 0 to 4 is 4 + 5 = 9.\n</pre>\n\n<p><strong>Example 2:</strong><br>\n<img src=\"offline/images/c2a01f964a943e520f6d.png\" style=\"width: 284px; height: 250px;\"></p>\n\n<pre><strong>Input:</strong> n = 4, highways = [[1,3,17],[1,2,7],[3,2,5],[0,1,6],[3,0,20]], discounts = 20\n<strong>Output:</strong> 8\n<strong>Explanation:</strong>\nGo from 0 to 1 and use a discount for a cost of 6 / 2 = 3.\nGo from 1 to 2 and use a discount for a cost of 7 / 2 = 3.\nGo from 2 to 3 and use a discount for a cost of 5 / 2 = 2.\nThe minimum cost to go from 0 to 3 is 3 + 3 + 2 = 8.\n</pre>\n\n<p><strong>Example 3:</strong><br>\n<img src=\"offline/images/ce9548c6dd8e4064ed37.png\" style=\"width: 275px; height: 250px;\"></p>\n\n<pre><strong>Input:</strong> n = 4, highways = [[0,1,3],[2,3,2]], discounts = 0\n<strong>Output:</strong> -1\n<strong>Explanation:</strong>\nIt is impossible to go from 0 to 3 so return -1.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>2 &lt;= n &lt;= 1000</code></li>\n\t<li><code>1 &lt;= highways.length &lt;= 1000</code></li>\n\t<li><code>highways[i].length == 3</code></li>\n\t<li><code>0 &lt;= city1<sub>i</sub>, city2<sub>i</sub> &lt;= n - 1</code></li>\n\t<li><code>city1<sub>i</sub> != city2<sub>i</sub></code></li>\n\t<li><code>0 &lt;= toll<sub>i</sub> &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= discounts &lt;= 500</code></li>\n\t<li>There are no duplicate highways.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2093-minimum-cost-to-reach-city-with-discounts.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    \n    struct Node {\n        int node, rem, cst;\n        Node(int node, int rem, int cst) {\n            this->node = node;\n            this->rem = rem;\n            this->cst = cst;\n        }\n    };\n    \n    struct Comparator {\n        bool operator()(const Node &a, const Node &b) {\n            return -a.cst < -b.cst;\n        }\n    };\n    \n    int minimumCost(int n, vector<vector<int>>& highways, int discounts) {\n        vector<vector<pair<int, int>>> adj;\n        adj.resize(n);\n        for (auto highway : highways) {\n            adj[highway[0]].push_back({highway[1], highway[2]});\n            adj[highway[1]].push_back({highway[0], highway[2]});\n        }\n        priority_queue<Node, vector<Node>, Comparator> pq;\n        pq.push(Node(0, discounts, 0));\n        vector<vector<int>> cost(n, vector<int>(discounts + 1, INT_MAX));\n        cost[0][discounts] = 0;\n        \n        while (!pq.empty()) {\n            Node cur = pq.top();\n            pq.pop();\n            int node = cur.node;\n            int rem = cur.rem;\n            int cst = cur.cst;\n            \n            if (node == (n-1)) {\n                return cst;\n            }\n            for (auto v : adj[node]) {\n                int adjn = v.first;\n                int adjc = v.second;\n                if ((cst + adjc) < cost[adjn][rem]) {\n                    cost[adjn][rem] = cst + adjc;\n                    pq.push(Node(adjn, rem, cst + adjc));\n                }\n                if (rem > 0 && (cst + adjc/2) < cost[adjn][rem-1]) {\n                    cost[adjn][rem-1] = cst + adjc/2;\n                    pq.push(Node(adjn, rem - 1, cst + adjc/2));\n                }\n            }\n        }\n        return -1;\n    }\n};","hash":"9f8f14729c040f219736b1aa7a5644f46034f744e0af721829d748a550cccc8f","origins":[{"source":"premium","path":"2093-minimum-cost-to-reach-city-with-discounts/2093-minimum-cost-to-reach-city-with-discounts.cpp"}]}],"sources":["premium"]},"lc-2095":{"key":"lc-2095","number":2095,"title":"Delete the Middle Node of a Linked List","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2095-delete-the-middle-node-of-a-linked-list/README.md","text":"<h2><a href=\"https://leetcode.com/problems/delete-the-middle-node-of-a-linked-list/\">2095. Delete the Middle Node of a Linked List</a></h2><h3>Medium</h3><hr><div><p>You are given the <code>head</code> of a linked list. <strong>Delete</strong> the <strong>middle node</strong>, and return <em>the</em> <code>head</code> <em>of the modified linked list</em>.</p>\n\n<p>The <strong>middle node</strong> of a linked list of size <code>n</code> is the <code>⌊n / 2⌋<sup>th</sup></code> node from the <b>start</b> using <strong>0-based indexing</strong>, where <code>⌊x⌋</code> denotes the largest integer less than or equal to <code>x</code>.</p>\n\n<ul>\n\t<li>For <code>n</code> = <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>, and <code>5</code>, the middle nodes are <code>0</code>, <code>1</code>, <code>1</code>, <code>2</code>, and <code>2</code>, respectively.</li>\n</ul>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n<img alt=\"\" src=\"offline/images/c19466b31c625375dbef.png\" style=\"width: 500px; height: 77px;\">\n<pre><strong>Input:</strong> head = [1,3,4,7,1,2,6]\n<strong>Output:</strong> [1,3,4,1,2,6]\n<strong>Explanation:</strong>\nThe above figure represents the given linked list. The indices of the nodes are written below.\nSince n = 7, node 3 with value 7 is the middle node, which is marked in red.\nWe return the new list after removing this node. \n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n<img alt=\"\" src=\"offline/images/0844236e808ec63d5cca.png\" style=\"width: 250px; height: 43px;\">\n<pre><strong>Input:</strong> head = [1,2,3,4]\n<strong>Output:</strong> [1,2,4]\n<strong>Explanation:</strong>\nThe above figure represents the given linked list.\nFor n = 4, node 2 with value 3 is the middle node, which is marked in red.\n</pre>\n\n<p><strong class=\"example\">Example 3:</strong></p>\n<img alt=\"\" src=\"offline/images/39c2f8783121793cbb77.png\" style=\"width: 150px; height: 58px;\">\n<pre><strong>Input:</strong> head = [2,1]\n<strong>Output:</strong> [2]\n<strong>Explanation:</strong>\nThe above figure represents the given linked list.\nFor n = 2, node 1 with value 1 is the middle node, which is marked in red.\nNode 0 with value 2 is the only node remaining after removing node 1.</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li>The number of nodes in the list is in the range <code>[1, 10<sup>5</sup>]</code>.</li>\n\t<li><code>1 &lt;= Node.val &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2095-delete-the-middle-node-of-a-linked-list.cpp","code":"class Solution {\n public:\n  ListNode* deleteMiddle(ListNode* head) {\n    ListNode dummy(0, head);\n    ListNode* slow = &dummy;\n    ListNode* fast = &dummy;\n\n    while (fast->next && fast->next->next) {\n      slow = slow->next;\n      fast = fast->next->next;\n    }\n\n    // Delete the middle node\n    slow->next = slow->next->next;\n    return dummy.next;\n  }\n};","hash":"99dac239d7c019a0428acea95d55b05e5a5abffbc0bb1ef8d07bcbf761b1d28d","origins":[{"source":"solutions","path":"2095-delete-the-middle-node-of-a-linked-list/2095-delete-the-middle-node-of-a-linked-list.cpp"}]},{"language":"python","name":"2095-delete-the-middle-node-of-a-linked-list.py","code":"class Solution:\n  def deleteMiddle(self, head: Optional[ListNode]) -> Optional[ListNode]:\n    dummy = ListNode(0, head)\n    slow = dummy\n    fast = dummy\n\n    while fast.next and fast.next.next:\n      slow = slow.next\n      fast = fast.next.next\n\n    # Delete the middle node\n    slow.next = slow.next.next\n    return dummy.next","hash":"43ea2b712a36176b6496f4edf30ef29d4ee2066018028502252da66265a790a1","origins":[{"source":"solutions","path":"2095-delete-the-middle-node-of-a-linked-list/2095-delete-the-middle-node-of-a-linked-list.py"}]},{"language":"python","name":"Delete the Middle Node of a Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def deleteMiddle(self, head: Optional[ListNode]) -> Optional[ListNode]:\n        if head is None:\n            return None\n        if head.next is None:\n            return None\n        slow, fast = head, head.next.next\n        while fast and fast.next:\n            slow = slow.next\n            fast = fast.next.next\n        slow.next = slow.next.next\n        return head","hash":"ca20023f03462399b0254c2774707c54a8058b0da1d5edc0f69a42724b37953c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-10 Leetcoding Challenge/Delete the Middle Node of a Linked List.py"}]}],"sources":["solutions"]},"lc-2098":{"key":"lc-2098","number":2098,"title":"Subsequence of Size K With the Largest Even Sum","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2098-subsequence-of-size-k-with-the-largest-even-sum/README.md","text":"<h2><a href=\"https://leetcode.com/problems/subsequence-of-size-k-with-the-largest-even-sum/\">2098. Subsequence of Size K With the Largest Even Sum</a></h2><h3>Medium</h3><hr><div><p>You are given an integer array <code>nums</code> and an integer <code>k</code>. Find the <strong>largest even sum</strong> of any subsequence of <code>nums</code> that has a length of <code>k</code>.</p>\n\n<p>Return <em>this sum, or </em><code>-1</code><em> if such a sum does not exist</em>.</p>\n\n<p>A <strong>subsequence</strong> is an array that can be derived from another array by deleting some or no elements without changing the order of the remaining elements.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [4,1,5,3,1], k = 3\n<strong>Output:</strong> 12\n<strong>Explanation:</strong>\nThe subsequence with the largest possible even sum is [4,5,3]. It has a sum of 4 + 5 + 3 = 12.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [4,6,2], k = 3\n<strong>Output:</strong> 12\n<strong>Explanation:</strong>\nThe subsequence with the largest possible even sum is [4,6,2]. It has a sum of 4 + 6 + 2 = 12.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,3,5], k = 1\n<strong>Output:</strong> -1\n<strong>Explanation:</strong>\nNo subsequence of nums with length 1 has an even sum.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= nums[i] &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= k &lt;= nums.length</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2098-subsequence-of-size-k-with-the-largest-even-sum.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    long long largestEvenSum(vector<int>& nums, int k) {\n        sort(nums.begin(), nums.end());\n        int n = nums.size();\n        int lastEven = -1, lastOdd = -1;\n        long long sum = 0;\n        for (int i = n - 1; i >= (n - k); i--) {\n            sum += nums[i];\n            if (nums[i]&1) {\n                lastOdd = nums[i];\n            } else {\n                lastEven = nums[i];\n            }\n        }\n        if (sum %2 == 0) return sum;\n        long long ans = -1;\n        for (int i = 0; i < n-k; i++) {\n            if (nums[i]%2 == 1 && (lastEven != -1)) {\n                ans = max(ans, sum - lastEven + nums[i]);\n            } else if (nums[i] % 2 == 0 && lastOdd != -1) {\n                ans = max(ans, sum - lastOdd + nums[i]);\n            }\n        }\n        return ans;\n    }\n};","hash":"fa037366131a4c78f12614e78a4fee5f90dd35beb6123b42427120bdd392ed81","origins":[{"source":"premium","path":"2098-subsequence-of-size-k-with-the-largest-even-sum/2098-subsequence-of-size-k-with-the-largest-even-sum.cpp"}]}],"sources":["premium"]},"lc-2101":{"key":"lc-2101","number":2101,"title":"detonate maximum bombs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\npublic:\n    int maximumDetonation(vector<vector<int>>& bombs) {\n        int n = bombs.size();\n        int maxBombs = 0;\n        unordered_map<int, vector<int>> graph;\n\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                if (i == j) {\n                    continue;\n                }\n                if (pow(bombs[i][2], 2) >= pow(bombs[i][0] - bombs[j][0], 2) + pow(bombs[i][1] - bombs[j][1], 2)) {\n                    graph[i].push_back(j);\n                }\n            }\n        }\n\n        for (int i = 0; i < n; i++) {\n            unordered_set<int> visited;\n            visited.insert(i);\n            dfs(i, visited, graph);\n            maxBombs = max(maxBombs, static_cast<int>(visited.size()));\n        }\n\n        return maxBombs;\n    }\n\nprivate:\n    void dfs(int node, unordered_set<int>& visited, unordered_map<int, vector<int>>& graph) {\n        vector<int>& neighbors = graph[node];\n        for (int child : neighbors) {\n            if (visited.find(child) == visited.end()) {\n                visited.insert(child);\n                dfs(child, visited, graph);\n            }\n        }\n    }\n};","hash":"a6d07d0c51c73ea0add7ba3e80948f3f7020af063400a3f1ccd6678d4c7a6ada","origins":[{"source":"solutions","path":"2101-detonate-maximum-bombs/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int maximumDetonation(int[][] bombs) {\n    final int n = bombs.length;\n    int ans = 0;\n    List<Integer>[] graph = new List[n];\n\n    for (int i = 0; i < n; ++i)\n      graph[i] = new ArrayList<>();\n\n    for (int i = 0; i < n; ++i) {\n      for (int j = 0; j < n; ++j) {\n        if (i == j)\n          continue;\n        final long ri = bombs[i][2];\n        if (ri * ri >= squaredDist(bombs, i, j))\n          graph[i].add(j);\n      }\n    }\n\n    for (int i = 0; i < n; ++i) {\n      Set<Integer> seen = new HashSet<>(Arrays.asList(i));\n      dfs(graph, i, seen);\n      ans = Math.max(ans, seen.size());\n    }\n\n    return ans;\n  }\n\n  private void dfs(List<Integer>[] graph, int u, Set<Integer> seen) {\n    for (final int v : graph[u]) {\n      if (seen.contains(v))\n        continue;\n      seen.add(v);\n      dfs(graph, v, seen);\n    }\n  }\n  private long squaredDist(int[][] bombs, int i, int j) {\n    return (long) (bombs[i][0] - bombs[j][0]) * (bombs[i][0] - bombs[j][0]) +\n        (long) (bombs[i][1] - bombs[j][1]) * (bombs[i][1] - bombs[j][1]);\n  };\n}","hash":"177d13b5f10da3ee5f9e9bd7aca5d2dc801d093e8d4e5b8329002bb2121457ac","origins":[{"source":"solutions","path":"2101-detonate-maximum-bombs/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n    def maximumDetonation(self, bombs):\n        n, max_bombs, graph = len(bombs), 0, defaultdict(list)\n\n        for i in range(n):\n            for j in range(n):\n                if i == j:\n                    continue\n                if bombs[i][2] ** 2 >= (bombs[i][0] - bombs[j][0]) ** 2 + (bombs[i][1] - bombs[j][1]) ** 2:\n                    graph[i] += [j]\n\n        def dfs(node, visited):\n            for child in graph[node]:\n                if child not in visited:\n                    visited.add(child)\n                    dfs(child, visited)\n\n        for i in range(n):\n            visited = set([i])\n            dfs(i, visited)\n            max_bombs = max(max_bombs, len(visited))\n\n        return max_bombs","hash":"da922536a5997ec3a2050169a661d8813d244b91125521eaa586e00c87cfff24","origins":[{"source":"solutions","path":"2101-detonate-maximum-bombs/solution.py"}]}],"sources":["solutions"]},"lc-2107":{"key":"lc-2107","number":2107,"title":"Number of Unique Flavors After Sharing K Candies","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2107-number-of-unique-flavors-after-sharing-k-candies/README.md","text":"<h2><a href=\"https://leetcode.com/problems/number-of-unique-flavors-after-sharing-k-candies/\">2107. Number of Unique Flavors After Sharing K Candies</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> integer array <code>candies</code>, where <code>candies[i]</code> represents the flavor of the <code>i<sup>th</sup></code> candy. Your mom wants you to share these candies with your little sister by giving her <code>k</code> <strong>consecutive</strong> candies, but you want to keep as many flavors of candies as possible.</p>\n\n<p>Return <em>the <strong>maximum</strong> number of <strong>unique</strong> flavors of candy you can keep after sharing </em><em> with your sister.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> candies = [1,<u>2,2,3</u>,4,3], k = 3\n<strong>Output:</strong> 3\n<strong>Explanation:</strong> \nGive the candies in the range [1, 3] (inclusive) with flavors [2,2,3].\nYou can eat candies with flavors [1,4,3].\nThere are 3 unique flavors, so return 3.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> candies = [2,2,2,<u>2,3</u>,3], k = 2\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> \nGive the candies in the range [3, 4] (inclusive) with flavors [2,3].\nYou can eat candies with flavors [2,2,2,3].\nThere are 2 unique flavors, so return 2.\nNote that you can also share the candies with flavors [2,2] and eat the candies with flavors [2,2,3,3].\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> candies = [2,4,5], k = 0\n<strong>Output:</strong> 3\n<strong>Explanation:</strong> \nYou do not have to give any candies.\nYou can eat the candies with flavors [2,4,5].\nThere are 3 unique flavors, so return 3.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= candies.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= candies[i] &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= k &lt;= candies.length</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2107-number-of-unique-flavors-after-sharing-k-candies.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    int shareCandies(vector<int>& candies, int k) {\n        int n = candies.size();\n        unordered_map<int, int> counter;\n        for (auto candy : candies) {\n            counter[candy]++;\n        }\n        int answer = 0;\n        for (int i = 0; i < n; i++) {\n            counter[candies[i]]--;\n            if (counter[candies[i]] == 0) {\n                counter.erase(candies[i]);\n            }\n            if (i >= k) {\n                int last = candies[i - k];\n                counter[last]++;\n            }\n            if ((i+1) >= k) {\n                answer = max(answer, (int)counter.size());\n            }\n        }\n        return answer;\n    }\n};","hash":"9e28e8e8bc64af3faa610669ab64f86332257adc2b981c056e7edad74ba9ab80","origins":[{"source":"premium","path":"2107-number-of-unique-flavors-after-sharing-k-candies/2107-number-of-unique-flavors-after-sharing-k-candies.cpp"}]}],"sources":["premium"]},"lc-2113":{"key":"lc-2113","number":2113,"title":"Elements in Array After Removing and Replacing Elements","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2113-elements-in-array-after-removing-and-replacing-elements/README.md","text":"<h2><a href=\"https://leetcode.com/problems/elements-in-array-after-removing-and-replacing-elements/\">2113. Elements in Array After Removing and Replacing Elements</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> integer array <code>nums</code>. Initially on minute <code>0</code>, the array is unchanged. Every minute, the <strong>leftmost</strong> element in <code>nums</code> is removed until no elements remain. Then, every minute, one element is appended to the <strong>end</strong> of <code>nums</code>, in the order they were removed in, until the original array is restored. This process repeats indefinitely.</p>\n\n<ul>\n\t<li>For example, the array <code>[0,1,2]</code> would change as follows: <code>[0,1,2] → [1,2] → [2] → [] → [0] → [0,1] → [0,1,2] → [1,2] → [2] → [] → [0] → [0,1] → [0,1,2] → ...</code></li>\n</ul>\n\n<p>You are also given a 2D integer array <code>queries</code> of size <code>n</code> where <code>queries[j] = [time<sub>j</sub>, index<sub>j</sub>]</code>. The answer to the <code>j<sup>th</sup></code> query is:</p>\n\n<ul>\n\t<li><code>nums[index<sub>j</sub>]</code> if <code>index<sub>j</sub> &lt; nums.length</code> at minute <code>time<sub>j</sub></code></li>\n\t<li><code>-1</code> if <code>index<sub>j</sub> &gt;= nums.length</code> at minute <code>time<sub>j</sub></code></li>\n</ul>\n\n<p>Return <em>an integer array <code>ans</code> of size </em><code>n</code> <em>where </em><code>ans[j]</code><em> is the answer to the </em><code>j<sup>th</sup></code><em> query</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [0,1,2], queries = [[0,2],[2,0],[3,2],[5,0]]\n<strong>Output:</strong> [2,2,-1,0]\n<strong>Explanation:</strong>\nMinute 0: [0,1,2] - All elements are in the nums.\nMinute 1: [1,2]   - The leftmost element, 0, is removed.\nMinute 2: [2]     - The leftmost element, 1, is removed.\nMinute 3: []      - The leftmost element, 2, is removed.\nMinute 4: [0]     - 0 is added to the end of nums.\nMinute 5: [0,1]   - 1 is added to the end of nums.\n\nAt minute 0, nums[2] is 2.\nAt minute 2, nums[0] is 2.\nAt minute 3, nums[2] does not exist.\nAt minute 5, nums[0] is 0.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [2], queries = [[0,0],[1,0],[2,0],[3,0]]\n<strong>Output:</strong> [2,-1,2,-1]\nMinute 0: [2] - All elements are in the nums.\nMinute 1: []  - The leftmost element, 2, is removed.\nMinute 2: [2] - 2 is added to the end of nums.\nMinute 3: []  - The leftmost element, 2, is removed.\n\nAt minute 0, nums[0] is 2.\nAt minute 1, nums[0] does not exist.\nAt minute 2, nums[0] is 2.\nAt minute 3, nums[0] does not exist.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 100</code></li>\n\t<li><code>0 &lt;= nums[i] &lt;= 100</code></li>\n\t<li><code>n == queries.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 10<sup>5</sup></code></li>\n\t<li><code>queries[j].length == 2</code></li>\n\t<li><code>0 &lt;= time<sub>j</sub> &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= index<sub>j</sub> &lt; nums.length</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2113-elements-in-array-after-removing-and-replacing-elements.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    vector<int> elementInNums(vector<int>& nums, vector<vector<int>>& queries) {\n        int n = nums.size();\n        int tot = n * 2;\n        vector<int> res;\n        for (auto query : queries) {\n            int time = query[0] % tot;\n            int ind = query[1];\n            int ans = -1;\n            if (time < n) {\n                ans = (time + ind) < n? nums[time + ind] : -1;\n            } else if (time > n) {\n                ans = (time - n) > ind? nums[ind] : -1;\n            }\n            res.push_back(ans);\n        }\n        return res;\n    }\n};","hash":"fe8d88bb83beaf80451a3900f69e99d0c66d18ffb74c20005b757b8010a4a350","origins":[{"source":"premium","path":"2113-elements-in-array-after-removing-and-replacing-elements/2113-elements-in-array-after-removing-and-replacing-elements.cpp"}]}],"sources":["premium"]},"lc-2116":{"key":"lc-2116","number":2116,"title":"check if a parantheses string can be valid","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"solution.py","code":"class Solution:\n  def canBeValid(self, s: str, locked: str) -> bool:\n    if len(s) % 2 == 1:\n      return False\n\n    def check(s: str, locked: str, isForward: bool) -> bool:\n      changeable = 0\n      l = 0\n      r = 0\n\n      for c, lock in zip(s, locked):\n        if lock == '0':\n          changeable += 1\n        elif c == '(':\n          l += 1\n        else:  # c == ')'\n          r += 1\n        if isForward and changeable + l - r < 0:\n          return False\n        if not isForward and changeable + r - l < 0:\n          return False\n\n      return True\n\n    return check(s, locked, True) and check(s[::-1], locked[::-1], False)","hash":"f02cc3632d01beb9c6fa52af2283ffc36c18f2a2d0fce1dd6c1e7339595f4364","origins":[{"source":"solutions","path":"2116-check-if-a-parantheses-string-can-be-valid/solution.py"}]}],"sources":["solutions"]},"lc-2122":{"key":"lc-2122","number":2122,"title":"Recover the Original Array","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2122-recover-the-original-array/README.md","text":"<h2><a href=\"https://leetcode.com/problems/recover-the-original-array/\">2122. Recover the Original Array</a></h2><h3>Hard</h3><hr><div><p>Alice had a <strong>0-indexed</strong> array <code>arr</code> consisting of <code>n</code> <strong>positive</strong> integers. She chose an arbitrary <strong>positive integer</strong> <code>k</code> and created two new <strong>0-indexed</strong> integer arrays <code>lower</code> and <code>higher</code> in the following manner:</p>\n\n<ol>\n\t<li><code>lower[i] = arr[i] - k</code>, for every index <code>i</code> where <code>0 &lt;= i &lt; n</code></li>\n\t<li><code>higher[i] = arr[i] + k</code>, for every index <code>i</code> where <code>0 &lt;= i &lt; n</code></li>\n</ol>\n\n<p>Unfortunately, Alice lost all three arrays. However, she remembers the integers that were present in the arrays <code>lower</code> and <code>higher</code>, but not the array each integer belonged to. Help Alice and recover the original array.</p>\n\n<p>Given an array <code>nums</code> consisting of <code>2n</code> integers, where <strong>exactly</strong> <code>n</code> of the integers were present in <code>lower</code> and the remaining in <code>higher</code>, return <em>the <strong>original</strong> array</em> <code>arr</code>. In case the answer is not unique, return <em><strong>any</strong> valid array</em>.</p>\n\n<p><strong>Note:</strong> The test cases are generated such that there exists <strong>at least one</strong> valid array <code>arr</code>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [2,10,6,4,8,12]\n<strong>Output:</strong> [3,7,11]\n<strong>Explanation:</strong>\nIf arr = [3,7,11] and k = 1, we get lower = [2,6,10] and higher = [4,8,12].\nCombining lower and higher gives us [2,6,10,4,8,12], which is a permutation of nums.\nAnother valid possibility is that arr = [5,7,9] and k = 3. In that case, lower = [2,4,6] and higher = [8,10,12]. \n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,1,3,3]\n<strong>Output:</strong> [2,2]\n<strong>Explanation:</strong>\nIf arr = [2,2] and k = 1, we get lower = [1,1] and higher = [3,3].\nCombining lower and higher gives us [1,1,3,3], which is equal to nums.\nNote that arr cannot be [1,3] because in that case, the only possible way to obtain [1,1,3,3] is with k = 0.\nThis is invalid since k must be positive.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> nums = [5,435]\n<strong>Output:</strong> [220]\n<strong>Explanation:</strong>\nThe only possible combination is arr = [220] and k = 215. Using them, we get lower = [5] and higher = [435].\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>2 * n == nums.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 1000</code></li>\n\t<li><code>1 &lt;= nums[i] &lt;= 10<sup>9</sup></code></li>\n\t<li>The test cases are generated such that there exists <strong>at least one</strong> valid array <code>arr</code>.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2122-recover-the-original-array.cpp","code":"class Solution {\n public:\n  vector<int> recoverArray(vector<int>& nums) {\n    const int n = nums.size();\n    unordered_map<int, int> count;\n\n    for (const int num : nums)\n      ++count[num];\n\n    sort(begin(nums), end(nums));\n\n    for (int i = 1; i < n; ++i) {\n      const int x = nums[i] - nums[0];  // 2 * k\n      if (x <= 0 || x & 1)\n        continue;\n      vector<int> A = getArray(nums, x, count);\n      if (!A.empty())\n        return A;\n    }\n\n    throw;\n  }\n\n private:\n  vector<int> getArray(const vector<int>& nums, int x,\n                       unordered_map<int, int> count) {\n    vector<int> A;\n    for (const int num : nums) {\n      if (!count.count(num) || count[num] == 0)\n        continue;\n      if (!count.count(num + x) || count[num + x] == 0)\n        return {};\n      --count[num];\n      --count[num + x];\n      A.push_back(num + x / 2);\n    }\n    return A;\n  }\n};","hash":"06e5553316e1cb648e3525b3adb2a6a5f2eef07584d013708807f9dcc5cc1674","origins":[{"source":"solutions","path":"2122-recover-the-original-array/2122-recover-the-original-array.cpp"}]},{"language":"java","name":"2122-recover-the-original-array.java","code":"class Solution {\n  public int[] recoverArray(int[] nums) {\n    final int n = nums.length;\n    Map<Integer, Integer> count = new HashMap<>();\n\n    for (final int num : nums)\n      count.merge(num, 1, Integer::sum);\n\n    Arrays.sort(nums);\n\n    for (int i = 1; i < n; ++i) {\n      final int x = nums[i] - nums[0]; // 2 * k\n      if (x <= 0 || x % 2 == 1)\n        continue;\n      Map<Integer, Integer> countCopy = new HashMap<>();\n      countCopy.putAll(count);\n      int[] A = getArray(nums, x, countCopy);\n      if (A.length == n / 2)\n        return A;\n    }\n\n    throw new IllegalArgumentException();\n  }\n\n  private int[] getArray(int[] nums, int x, Map<Integer, Integer> count) {\n    List<Integer> A = new ArrayList<>();\n    for (final int num : nums) {\n      if (count.getOrDefault(num, 0) == 0)\n        continue;\n      if (count.getOrDefault(num + x, 0) == 0)\n        return new int[] {};\n      count.merge(num, -1, Integer::sum);\n      count.merge(num + x, -1, Integer::sum);\n      A.add(num + x / 2);\n    }\n    return A.stream().mapToInt(i -> i).toArray();\n  }\n}","hash":"675fb056e60abd441265871c3596f21ec555f4133da8dbfd67fe32458f56fb43","origins":[{"source":"solutions","path":"2122-recover-the-original-array/2122-recover-the-original-array.java"}]},{"language":"python","name":"2122-recover-the-original-array.py","code":"class Solution:\n  def recoverArray(self, nums: List[int]) -> List[int]:\n    nums = sorted(nums)\n\n    def getArray(x: int, count: collections.Counter) -> List[int]:\n      A = []\n      for num in nums:\n        if count[num] == 0:\n          continue\n        if count[num + x] == 0:\n          return []\n        count[num] -= 1\n        count[num + x] -= 1\n        A.append(num + x // 2)\n      return A\n\n    count = Counter(nums)\n\n    for i in range(1, len(nums)):\n      x = nums[i] - nums[0]  # 2 * k\n      if x <= 0 or x & 1:\n        continue\n      A = getArray(x, count.copy())\n      if A:\n        return A","hash":"91badf8004bf1605aced9bcc6d08caa75f05ba51b19d8283903d747b7f1faae3","origins":[{"source":"solutions","path":"2122-recover-the-original-array/2122-recover-the-original-array.py"}]}],"sources":["solutions"]},"lc-2128":{"key":"lc-2128","number":2128,"title":"Remove All Ones With Row and Column Flips","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2128-remove-all-ones-with-row-and-column-flips/README.md","text":"<h2><a href=\"https://leetcode.com/problems/remove-all-ones-with-row-and-column-flips/\">2128. Remove All Ones With Row and Column Flips</a></h2><h3>Medium</h3><hr><div><p>You are given an <code>m x n</code> binary matrix <code>grid</code>.</p>\n\n<p>In one operation, you can choose <strong>any</strong> row or column and flip each value in that row or column (i.e., changing all <code>0</code>'s to <code>1</code>'s, and all <code>1</code>'s to <code>0</code>'s).</p>\n\n<p>Return <code>true</code><em> if it is possible to remove all </em><code>1</code><em>'s from </em><code>grid</code> using <strong>any</strong> number of operations or <code>false</code> otherwise.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n<img src=\"offline/images/5b719ca984d6cc599096.png\" style=\"width: 756px; height: 225px;\">\n<pre><strong>Input:</strong> grid = [[0,1,0],[1,0,1],[0,1,0]]\n<strong>Output:</strong> true\n<strong>Explanation:</strong> One possible way to remove all 1's from grid is to:\n- Flip the middle row\n- Flip the middle column\n</pre>\n\n<p><strong>Example 2:</strong></p>\n<img src=\"offline/images/b1e4d4e1a833292b8b8d.png\" style=\"width: 237px; height: 225px;\">\n<pre><strong>Input:</strong> grid = [[1,1,0],[0,0,0],[0,0,0]]\n<strong>Output:</strong> false\n<strong>Explanation:</strong> It is impossible to remove all 1's from grid.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n<img src=\"offline/images/efb67c7309ef27ec3f99.png\" style=\"width: 114px; height: 100px;\">\n<pre><strong>Input:</strong> grid = [[0]]\n<strong>Output:</strong> true\n<strong>Explanation:</strong> There are no 1's in grid.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>m == grid.length</code></li>\n\t<li><code>n == grid[i].length</code></li>\n\t<li><code>1 &lt;= m, n &lt;= 300</code></li>\n\t<li><code>grid[i][j]</code> is either <code>0</code> or <code>1</code>.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2128-remove-all-ones-with-row-and-column-flips.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    bool removeOnes(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int m = grid[0].size();\n        for (int i = 0; i < m; i++) {\n            if (grid[0][i]) {\n                for (int j = n-1; j > 0; j--) {\n                    grid[j][i] = 1 - grid[j][i];\n                }\n            }\n        }\n        for (int i = 1; i < n; i++) {\n            int cnt = 0;\n            for (int j = 0; j < m; j++) {\n                cnt += grid[i][j];\n            }\n            if (cnt == 0 || cnt == m) continue;\n            return false;\n        }\n        return true;\n    }\n};","hash":"ca3201b063c24eada1674d3f23a5118beb31542dd7401bd0f07555cf1c1ab14b","origins":[{"source":"premium","path":"2128-remove-all-ones-with-row-and-column-flips/2128-remove-all-ones-with-row-and-column-flips.cpp"}]}],"sources":["premium"]},"lc-2130":{"key":"lc-2130","number":2130,"title":"maximum twin sum of a linked list","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int pairSum(ListNode* head) {\n    int ans = 0;\n    ListNode* slow = head;\n    ListNode* fast = head;\n\n    // Let slow point to the start of the second half\n    while (fast && fast->next) {\n      slow = slow->next;\n      fast = fast->next->next;\n    }\n\n    // Tail points to the end with reversed second half\n    ListNode* tail = reverseList(slow);\n\n    while (tail) {\n      ans = max(ans, head->val + tail->val);\n      head = head->next;\n      tail = tail->next;\n    }\n\n    return ans;\n  }\n\n private:\n  ListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    while (head) {\n      auto next = head->next;\n      head->next = prev;\n      prev = head;\n      head = next;\n    }\n    return prev;\n  }\n};","hash":"ca17e8b05af9349991755c261429e2283d213153313c068a7cd7b38cb81272eb","origins":[{"source":"solutions","path":"2130-maximum-twin-sum-of-a-linked-list/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int pairSum(ListNode head) {\n    int ans = 0;\n    ListNode slow = head;\n    ListNode fast = head;\n\n    // Let slow point to the start of the second half\n    while (fast != null && fast.next != null) {\n      slow = slow.next;\n      fast = fast.next.next;\n    }\n\n    // Tail points to the end with reversed second half\n    ListNode tail = reverseList(slow);\n\n    while (tail != null) {\n      ans = Math.max(ans, head.val + tail.val);\n      head = head.next;\n      tail = tail.next;\n    }\n\n    return ans;\n  }\n\n  private ListNode reverseList(ListNode head) {\n    ListNode prev = null;\n    while (head != null) {\n      ListNode next = head.next;\n      head.next = prev;\n      prev = head;\n      head = next;\n    }\n    return prev;\n  }\n}","hash":"f7b3ecf8ab50e5737154ecf24a3aa7ee295cbb5c588069457293acca2ee7446c","origins":[{"source":"solutions","path":"2130-maximum-twin-sum-of-a-linked-list/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def pairSum(self, head: Optional[ListNode]) -> int:\n    def reverseList(head: ListNode) -> ListNode:\n      prev = None\n      while head:\n        next = head.next\n        head.next = prev\n        prev = head\n        head = next\n      return prev\n\n    ans = 0\n    slow = head\n    fast = head\n\n    # Let slow point to the start of the second half\n    while fast and fast.next:\n      slow = slow.next\n      fast = fast.next.next\n\n    # Tail points to the end with reversed second half\n    tail = reverseList(slow)\n\n    while tail:\n      ans = max(ans, head.val + tail.val)\n      head = head.next\n      tail = tail.next\n\n    return ans","hash":"310bd38c95575f2f17d0c9986d9755b6c37596f40361024ca49877a5f4e44e84","origins":[{"source":"solutions","path":"2130-maximum-twin-sum-of-a-linked-list/solution.py"}]}],"sources":["solutions"]},"lc-2131":{"key":"lc-2131","number":2131,"title":"Longest Palindrome by Concatenating Two Letter Words","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2131-longest-palindrome-by-concatenating-two-letter-words/README.md","text":"<h2><a href=\"https://leetcode.com/problems/longest-palindrome-by-concatenating-two-letter-words/\">2131. Longest Palindrome by Concatenating Two Letter Words</a></h2><h3>Medium</h3><hr><div><p>You are given an array of strings <code>words</code>. Each element of <code>words</code> consists of <strong>two</strong> lowercase English letters.</p>\n\n<p>Create the <strong>longest possible palindrome</strong> by selecting some elements from <code>words</code> and concatenating them in <strong>any order</strong>. Each element can be selected <strong>at most once</strong>.</p>\n\n<p>Return <em>the <strong>length</strong> of the longest palindrome that you can create</em>. If it is impossible to create any palindrome, return <code>0</code>.</p>\n\n<p>A <strong>palindrome</strong> is a string that reads the same forward and backward.</p>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n\n<pre><strong>Input:</strong> words = [\"lc\",\"cl\",\"gg\"]\n<strong>Output:</strong> 6\n<strong>Explanation:</strong> One longest palindrome is \"lc\" + \"gg\" + \"cl\" = \"lcggcl\", of length 6.\nNote that \"clgglc\" is another longest palindrome that can be created.\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n\n<pre><strong>Input:</strong> words = [\"ab\",\"ty\",\"yt\",\"lc\",\"cl\",\"ab\"]\n<strong>Output:</strong> 8\n<strong>Explanation:</strong> One longest palindrome is \"ty\" + \"lc\" + \"cl\" + \"yt\" = \"tylcclyt\", of length 8.\nNote that \"lcyttycl\" is another longest palindrome that can be created.\n</pre>\n\n<p><strong class=\"example\">Example 3:</strong></p>\n\n<pre><strong>Input:</strong> words = [\"cc\",\"ll\",\"xx\"]\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> One longest palindrome is \"cc\", of length 2.\nNote that \"ll\" is another longest palindrome that can be created, and so is \"xx\".\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= words.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>words[i].length == 2</code></li>\n\t<li><code>words[i]</code> consists of lowercase English letters.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2131-longest-palindrome-by-concatenating-two-letter-words.cpp","code":"class Solution {\n public:\n  int longestPalindrome(vector<string>& words) {\n    int ans = 0;\n    vector<vector<int>> count(26, vector<int>(26));\n\n    for (const string& word : words) {\n      const int i = word[0] - 'a';\n      const int j = word[1] - 'a';\n      if (count[j][i]) {\n        ans += 4;\n        --count[j][i];\n      } else {\n        ++count[i][j];\n      }\n    }\n\n    for (int i = 0; i < 26; ++i)\n      if (count[i][i])\n        return ans + 2;\n\n    return ans;\n  }\n};","hash":"19032e68c50e1e29a2040e6d8297525f9619a98f402e6c638be0ce6e38ef8169","origins":[{"source":"solutions","path":"2131-longest-palindrome-by-concatenating-two-letter-words/2131-longest-palindrome-by-concatenating-two-letter-words.cpp"}]},{"language":"java","name":"2131-longest-palindrome-by-concatenating-two-letter-words.java","code":"class Solution {\n  public int longestPalindrome(String[] words) {\n    int ans = 0;\n    int[][] count = new int[26][26];\n\n    for (final String word : words) {\n      final int i = word.charAt(0) - 'a';\n      final int j = word.charAt(1) - 'a';\n      if (count[j][i] > 0) {\n        ans += 4;\n        --count[j][i];\n      } else {\n        ++count[i][j];\n      }\n    }\n\n    for (int i = 0; i < 26; ++i)\n      if (count[i][i] > 0)\n        return ans + 2;\n\n    return ans;\n  }\n}","hash":"3533790a298b34eae0abd629df55723fc0f38dd5f9e246b0f9e79be600f9c58d","origins":[{"source":"solutions","path":"2131-longest-palindrome-by-concatenating-two-letter-words/2131-longest-palindrome-by-concatenating-two-letter-words.java"}]},{"language":"python","name":"2131-longest-palindrome-by-concatenating-two-letter-words.py","code":"class Solution:\n  def longestPalindrome(self, words: List[str]) -> int:\n    ans = 0\n    count = [[0] * 26 for _ in range(26)]\n\n    for a, b in words:\n      i = ord(a) - ord('a')\n      j = ord(b) - ord('a')\n      if count[j][i]:\n        ans += 4\n        count[j][i] -= 1\n      else:\n        count[i][j] += 1\n\n    for i in range(26):\n      if count[i][i]:\n        return ans + 2\n\n    return ans","hash":"a48a1ef97fb551d737970d8281e66bf93187ed2909ab7f6e92ea416af10ecafb","origins":[{"source":"solutions","path":"2131-longest-palindrome-by-concatenating-two-letter-words/2131-longest-palindrome-by-concatenating-two-letter-words.py"}]},{"language":"python","name":"Longest Palindrome by Concatenating Two Letter Words.py","code":"class Solution:\n    def longestPalindrome(self, words: List[str]) -> int:\n        freqMap = Counter(words)\n        result, central = 0, False\n        for word, freq in freqMap.items():\n            if word[0] == word[1]:\n                if freq % 2 == 0:\n                    result += freq\n                else:\n                    result += freq - 1\n                    central = True\n            elif word[0] < word[1]:\n                result += 2 * min(freq, freqMap[word[1] + word[0]])\n        if central:\n            result += 1\n        return 2 * result","hash":"3f7f99dbc41cea3078d1d350ed860651ce39a30e8465c8e7799c4b9e7db8908d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-11 Leetcoding Challenge/Longest Palindrome by Concatenating Two Letter Words.py"}]}],"sources":["solutions"]},"lc-2136":{"key":"lc-2136","number":2136,"title":"Earliest Possible Day of Full Bloom","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2136-earliest-possible-day-of-full-bloom/README.md","text":"<h2><a href=\"https://leetcode.com/problems/earliest-possible-day-of-full-bloom/\">2136. Earliest Possible Day of Full Bloom</a></h2><h3>Hard</h3><hr><div><p>You have <code>n</code> flower seeds. Every seed must be planted first before it can begin to grow, then bloom. Planting a seed takes time and so does the growth of a seed. You are given two <strong>0-indexed</strong> integer arrays <code>plantTime</code> and <code>growTime</code>, of length <code>n</code> each:</p>\n\n<ul>\n\t<li><code>plantTime[i]</code> is the number of <strong>full days</strong> it takes you to <strong>plant</strong> the <code>i<sup>th</sup></code> seed. Every day, you can work on planting exactly one seed. You <strong>do not</strong> have to work on planting the same seed on consecutive days, but the planting of a seed is not complete <strong>until</strong> you have worked <code>plantTime[i]</code> days on planting it in total.</li>\n\t<li><code>growTime[i]</code> is the number of <strong>full days</strong> it takes the <code>i<sup>th</sup></code> seed to grow after being completely planted. <strong>After</strong> the last day of its growth, the flower <strong>blooms</strong> and stays bloomed forever.</li>\n</ul>\n\n<p>From the beginning of day <code>0</code>, you can plant the seeds in <strong>any</strong> order.</p>\n\n<p>Return <em>the <strong>earliest</strong> possible day where <strong>all</strong> seeds are blooming</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n<img alt=\"\" src=\"offline/images/115d14641cce7a56cb57.png\" style=\"width: 453px; height: 149px;\">\n<pre><strong>Input:</strong> plantTime = [1,4,3], growTime = [2,3,1]\n<strong>Output:</strong> 9\n<strong>Explanation:</strong> The grayed out pots represent planting days, colored pots represent growing days, and the flower represents the day it blooms.\nOne optimal way is:\nOn day 0, plant the 0<sup>th</sup> seed. The seed grows for 2 full days and blooms on day 3.\nOn days 1, 2, 3, and 4, plant the 1<sup>st</sup> seed. The seed grows for 3 full days and blooms on day 8.\nOn days 5, 6, and 7, plant the 2<sup>nd</sup> seed. The seed grows for 1 full day and blooms on day 9.\nThus, on day 9, all the seeds are blooming.\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n<img alt=\"\" src=\"offline/images/8a27a767328bfbf4f2c3.png\" style=\"width: 454px; height: 184px;\">\n<pre><strong>Input:</strong> plantTime = [1,2,3,2], growTime = [2,1,2,1]\n<strong>Output:</strong> 9\n<strong>Explanation:</strong> The grayed out pots represent planting days, colored pots represent growing days, and the flower represents the day it blooms.\nOne optimal way is:\nOn day 1, plant the 0<sup>th</sup> seed. The seed grows for 2 full days and blooms on day 4.\nOn days 0 and 3, plant the 1<sup>st</sup> seed. The seed grows for 1 full day and blooms on day 5.\nOn days 2, 4, and 5, plant the 2<sup>nd</sup> seed. The seed grows for 2 full days and blooms on day 8.\nOn days 6 and 7, plant the 3<sup>rd</sup> seed. The seed grows for 1 full day and blooms on day 9.\nThus, on day 9, all the seeds are blooming.\n</pre>\n\n<p><strong class=\"example\">Example 3:</strong></p>\n\n<pre><strong>Input:</strong> plantTime = [1], growTime = [1]\n<strong>Output:</strong> 2\n<strong>Explanation:</strong> On day 0, plant the 0<sup>th</sup> seed. The seed grows for 1 full day and blooms on day 2.\nThus, on day 2, all the seeds are blooming.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == plantTime.length == growTime.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= plantTime[i], growTime[i] &lt;= 10<sup>4</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2136-earliest-possible-day-of-full-bloom.cpp","code":"struct Seed {\n  int p;\n  int g;\n  Seed(int p, int g) : p(p), g(g) {}\n};\n\nclass Solution {\n public:\n  int earliestFullBloom(vector<int>& plantTime, vector<int>& growTime) {\n    int ans = 0;\n    int time = 0;\n    vector<Seed> seeds;\n\n    for (int i = 0; i < plantTime.size(); ++i)\n      seeds.emplace_back(plantTime[i], growTime[i]);\n\n    sort(begin(seeds), end(seeds),\n         [](const auto& a, const auto& b) { return a.g > b.g; });\n\n    for (const auto& [p, g] : seeds) {\n      time += p;\n      ans = max(ans, time + g);\n    }\n\n    return ans;\n  }\n};","hash":"f2ed6fcf9bc531e34788a5eea1537fc2052a77a954890827c41ff357c0dd92f9","origins":[{"source":"solutions","path":"2136-earliest-possible-day-of-full-bloom/2136-earliest-possible-day-of-full-bloom.cpp"}]},{"language":"python","name":"2136-earliest-possible-day-of-full-bloom.py","code":"class Solution:\n  def earliestFullBloom(self, plantTime: List[int], growTime: List[int]) -> int:\n    ans = 0\n    time = 0\n\n    for p, g in sorted([(p, g) for (p, g) in zip(plantTime, growTime)], key=lambda x: -x[1]):\n      time += p\n      ans = max(ans, time + g)\n\n    return ans","hash":"d03ec0d713d63ffaa12842ca7d59a8ce01e46397e73f558094c64617351cdaf9","origins":[{"source":"solutions","path":"2136-earliest-possible-day-of-full-bloom/2136-earliest-possible-day-of-full-bloom.py"}]},{"language":"python","name":"Earliest Possible Day of Full Bloom.py","code":"class Solution:\n    def earliestFullBloom(self, plantTime: List[int], growTime: List[int]) -> int:\n        currentPlantTime, result = 0, 0\n        data = sorted([(plant, grow) for plant, grow in zip(plantTime, growTime)], key=lambda x: -x[1])\n        for plant, grow in data:\n            currentPlantTime += plant\n            result = max(result, currentPlantTime + grow)\n        return result","hash":"6aed3af00019b621f9f2bec8bffa19106c484991a48b83d82cdbc7c8172b860a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-10 Leetcoding Challenge/Earliest Possible Day of Full Bloom.py"}]}],"sources":["solutions"]},"lc-2140":{"key":"lc-2140","number":2140,"title":"solving questions with brainpower","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long mostPoints(vector<vector<int>>& questions) {\n    const int n = questions.size();\n    // dp[i] := max points starting from questions[i]\n    vector<long long> dp(n + 1);\n\n    for (int i = n - 1; i >= 0; --i) {\n      const int points = questions[i][0];\n      const int brainpower = questions[i][1];\n      const int nextIndex = i + brainpower + 1;\n      const long long nextPoints = nextIndex < n ? dp[nextIndex] : 0;\n      dp[i] = max(points + nextPoints, dp[i + 1]);\n    }\n\n    return dp[0];\n  }\n};","hash":"a2a6c6dbb92bc5f2fe50b4b8363737259133c9e3e7eedd667cec69bc3d002150","origins":[{"source":"solutions","path":"2140-solving questions with brainpower/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long mostPoints(int[][] questions) {\n    final int n = questions.length;\n    // dp[i] := max points starting from questions[i]\n    long[] dp = new long[n + 1];\n\n    for (int i = n - 1; i >= 0; --i) {\n      final int points = questions[i][0];\n      final int brainpower = questions[i][1];\n      final int nextIndex = i + brainpower + 1;\n      final long nextPoints = nextIndex < n ? dp[nextIndex] : 0;\n      dp[i] = Math.max(points + nextPoints, dp[i + 1]);\n    }\n\n    return dp[0];\n  }\n}","hash":"662927c9c70b405ab4e000ae7605461cd28835747765e0b7f37d5a6f8e0b2f58","origins":[{"source":"solutions","path":"2140-solving questions with brainpower/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def mostPoints(self, questions: List[List[int]]) -> int:\n    n = len(questions)\n    # dp[i] := max points starting from questions[i]\n    dp = [0] * (n + 1)\n\n    for i in reversed(range(n)):\n      points, brainpower = questions[i]\n      nextIndex = i + brainpower + 1\n      nextPoints = dp[nextIndex] if nextIndex < n else 0\n      dp[i] = max(points + nextPoints, dp[i + 1])\n\n    return dp[0]","hash":"4be2af4870d3a368ed1e42c7a3c025bbfd3caf69bde2835280a2fa6262ee072c","origins":[{"source":"solutions","path":"2140-solving questions with brainpower/solution.py"}]}],"sources":["solutions"]},"lc-2141":{"key":"lc-2141","number":2141,"title":"maximum running time for N computers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long maxRunTime(int n, vector<int>& batteries) {\n    long long sum = accumulate(batteries.begin(), batteries.end(), 0LL);\n\n    sort(batteries.begin(), batteries.end());\n\n    // Max battery is greater than the average, so it can last forever\n    // Reduce the problem from size n to size n - 1\n    while (batteries.back() > sum / n) {\n      sum -= batteries.back(), batteries.pop_back();\n      --n;\n    }\n\n    // If the max battery <= average running time,\n    // It won't be waste, and so do smaller batteries\n    return sum / n;\n  }\n};","hash":"401888f4cc0b247dc151e7c4cb79efcb0bacdfb0ea4318eddcaf116b2b1e8665","origins":[{"source":"solutions","path":"2141-maximum-running-time-for-N-computers/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long maxRunTime(int n, int[] batteries) {\n    long sum = Arrays.stream(batteries).asLongStream().sum();\n\n    Arrays.sort(batteries);\n\n    // Max battery is greater than the average, so it can last forever\n    // Reduce the problem from size n to size n - 1\n    int i = batteries.length - 1;\n    while (batteries[i] > sum / n) {\n      sum -= batteries[i--];\n      --n;\n    }\n\n    // If the max battery <= average running time,\n    // It won't be waste, and so do smaller batteries\n    return sum / n;\n  }\n}","hash":"fe3c90e78f1a9c505b43ebd5c80a69e1767bae2b787a4845636a41c087750e33","origins":[{"source":"solutions","path":"2141-maximum-running-time-for-N-computers/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n    def maxRunTime(self, n: int, batteries: List[int]) -> int:\n        batteries.sort()\n        extra = sum(batteries[:-n])\n        batteries = batteries[-n:]\n        \n        ans = prefix = 0 \n        for i, x in enumerate(batteries): \n            prefix += x \n            if i+1 < len(batteries) and batteries[i+1]*(i+1) - prefix > extra: return (prefix + extra) // (i+1)\n        return (prefix + extra) // n","hash":"477c543ee9d226c2abac782eff3ec95bfe54743abf96af082e17414aec1959ef","origins":[{"source":"solutions","path":"2141-maximum-running-time-for-N-computers/solution.py"}]}],"sources":["solutions"]},"lc-2143":{"key":"lc-2143","number":2143,"title":"Choose Numbers From Two Arrays in Range","difficulty":"Hard","tags":[],"documents":[{"source":"premium","path":"2143-choose-numbers-from-two-arrays-in-range/README.md","text":"<h2><a href=\"https://leetcode.com/problems/choose-numbers-from-two-arrays-in-range/\">2143. Choose Numbers From Two Arrays in Range</a></h2><h3>Hard</h3><hr><div><p>You are given two <strong>0-indexed</strong> integer arrays <code>nums1</code> and <code>nums2</code> of length <code>n</code>.</p>\n\n<p>A range <code>[l, r]</code> (<strong>inclusive</strong>) where <code>0 &lt;= l &lt;= r &lt; n</code> is <strong>balanced</strong> if:</p>\n\n<ul>\n\t<li>For every <code>i</code> in the range <code>[l, r]</code>, you pick either <code>nums1[i]</code> or <code>nums2[i]</code>.</li>\n\t<li>The sum of the numbers you pick from <code>nums1</code> equals to the sum of the numbers you pick from <code>nums2</code> (the sum is considered to be <code>0</code> if you pick no numbers from an array).</li>\n</ul>\n\n<p>Two <strong>balanced</strong> ranges from <code>[l<sub>1</sub>, r<sub>1</sub>]</code> and <code>[l<sub>2</sub>, r<sub>2</sub>]</code> are considered to be <strong>different</strong> if at least one of the following is true:</p>\n\n<ul>\n\t<li><code>l<sub>1</sub> != l<sub>2</sub></code></li>\n\t<li><code>r<sub>1</sub> != r<sub>2</sub></code></li>\n\t<li><code>nums1[i]</code> is picked in the first range, and <code>nums2[i]</code> is picked in the second range or <strong>vice versa</strong> for at least one <code>i</code>.</li>\n</ul>\n\n<p>Return <em>the number of <strong>different</strong> ranges that are balanced. </em>Since the answer may be very large, return it <strong>modulo</strong> <code>10<sup>9</sup> + 7</code><em>.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums1 = [1,2,5], nums2 = [2,6,3]\n<strong>Output:</strong> 3\n<strong>Explanation:</strong> The balanced ranges are:\n- [0, 1] where we choose nums2[0], and nums1[1].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 2 = 2.\n- [0, 2] where we choose nums1[0], nums2[1], and nums1[2].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 1 + 5 = 6.\n- [0, 2] where we choose nums1[0], nums1[1], and nums2[2].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 1 + 2 = 3.\nNote that the second and third balanced ranges are different.\nIn the second balanced range, we choose nums2[1] and in the third balanced range, we choose nums1[1].\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums1 = [0,1], nums2 = [1,0]\n<strong>Output:</strong> 4\n<strong>Explanation:</strong> The balanced ranges are:\n- [0, 0] where we choose nums1[0].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 0 = 0.\n- [1, 1] where we choose nums2[1].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 0 = 0.\n- [0, 1] where we choose nums1[0] and nums2[1].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 0 = 0.\n- [0, 1] where we choose nums2[0] and nums1[1].\n  The sum of the numbers chosen from nums1 equals the sum of the numbers chosen from nums2: 1 = 1.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == nums1.length == nums2.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 100</code></li>\n\t<li><code>0 &lt;= nums1[i], nums2[i] &lt;= 100</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2143-choose-numbers-from-two-arrays-in-range.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    const int MOD = 1e9 + 7;\n    \n    int solve(int ind, int sum, vector<int> &nums1, vector<int> &nums2) {\n        if (ind == nums1.size()) {\n            return sum == 0;\n        }\n        int &ret = dp[ind][sum + 10000];\n        if (ret != -1) return ret;\n        ret = 0;\n        if (sum == 0) {\n            ret = 1;\n        }\n        ret = (ret + solve(ind + 1, sum + nums1[ind], nums1, nums2)) % MOD;\n        ret = (ret + solve(ind + 1, sum - nums2[ind], nums1, nums2)) % MOD;\n        return ret;\n    }\n    \n    int countSubranges(vector<int>& nums1, vector<int>& nums2) {\n        int ret = 0;\n        int n = nums1.size();\n        dp.resize(n + 1, vector<int>(20009, -1));\n        for (int i = n - 1; i >= 0; i--) {\n            ret = (ret + solve(i + 1, nums1[i], nums1, nums2)) % MOD;\n            ret = (ret + solve(i + 1, -nums2[i], nums1, nums2)) % MOD;\n        }\n        return ret;\n    }\nprivate:\n    vector<vector<int>> dp;\n};\n\n/*\n\n[1,2,5,3,4,5,7,5,3,2,1,1,3]\n[2,6,3,3,5,6,7,4,2,2,1,1,4]\n\n*/","hash":"8811809ec2b8ecd9ba8cfd945349b62e41963cd5ca956171ee72cb0de664c6eb","origins":[{"source":"premium","path":"2143-choose-numbers-from-two-arrays-in-range/2143-choose-numbers-from-two-arrays-in-range.cpp"}]}],"sources":["premium"]},"lc-2156":{"key":"lc-2156","number":2156,"title":"Find Substring With Given Hash Value","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2156-find-substring-with-given-hash-value/README.md","text":"<h2><a href=\"https://leetcode.com/problems/find-substring-with-given-hash-value/\">2156. Find Substring With Given Hash Value</a></h2><h3>Hard</h3><hr><div><p>The hash of a <strong>0-indexed</strong> string <code>s</code> of length <code>k</code>, given integers <code>p</code> and <code>m</code>, is computed using the following function:</p>\n\n<ul>\n\t<li><code>hash(s, p, m) = (val(s[0]) * p<sup>0</sup> + val(s[1]) * p<sup>1</sup> + ... + val(s[k-1]) * p<sup>k-1</sup>) mod m</code>.</li>\n</ul>\n\n<p>Where <code>val(s[i])</code> represents the index of <code>s[i]</code> in the alphabet from <code>val('a') = 1</code> to <code>val('z') = 26</code>.</p>\n\n<p>You are given a string <code>s</code> and the integers <code>power</code>, <code>modulo</code>, <code>k</code>, and <code>hashValue.</code> Return <code>sub</code>,<em> the <strong>first</strong> <strong>substring</strong> of </em><code>s</code><em> of length </em><code>k</code><em> such that </em><code>hash(sub, power, modulo) == hashValue</code>.</p>\n\n<p>The test cases will be generated such that an answer always <strong>exists</strong>.</p>\n\n<p>A <b>substring</b> is a contiguous non-empty sequence of characters within a string.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> s = \"leetcode\", power = 7, modulo = 20, k = 2, hashValue = 0\n<strong>Output:</strong> \"ee\"\n<strong>Explanation:</strong> The hash of \"ee\" can be computed to be hash(\"ee\", 7, 20) = (5 * 1 + 5 * 7) mod 20 = 40 mod 20 = 0. \n\"ee\" is the first substring of length 2 with hashValue 0. Hence, we return \"ee\".\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> s = \"fbxzaad\", power = 31, modulo = 100, k = 3, hashValue = 32\n<strong>Output:</strong> \"fbx\"\n<strong>Explanation:</strong> The hash of \"fbx\" can be computed to be hash(\"fbx\", 31, 100) = (6 * 1 + 2 * 31 + 24 * 31<sup>2</sup>) mod 100 = 23132 mod 100 = 32. \nThe hash of \"bxz\" can be computed to be hash(\"bxz\", 31, 100) = (2 * 1 + 24 * 31 + 26 * 31<sup>2</sup>) mod 100 = 25732 mod 100 = 32. \n\"fbx\" is the first substring of length 3 with hashValue 32. Hence, we return \"fbx\".\nNote that \"bxz\" also has a hash of 32 but it appears later than \"fbx\".\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= k &lt;= s.length &lt;= 2 * 10<sup>4</sup></code></li>\n\t<li><code>1 &lt;= power, modulo &lt;= 10<sup>9</sup></code></li>\n\t<li><code>0 &lt;= hashValue &lt; modulo</code></li>\n\t<li><code>s</code> consists of lowercase English letters only.</li>\n\t<li>The test cases are generated such that an answer always <strong>exists</strong>.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2156-find-substring-with-given-hash-value.cpp","code":"class Solution {\n public:\n  string subStrHash(string s, int power, int modulo, int k, int hashValue) {\n    long maxPower = 1;\n    long hashed = 0;\n    int bestLeft = -1;\n\n    auto val = [](char c) -> int { return c - 'a' + 1; };\n\n    for (int i = s.length() - 1; i >= 0; --i) {\n      hashed = (hashed * power + val(s[i])) % modulo;\n      if (i + k < s.length())\n        hashed = (hashed - val(s[i + k]) * maxPower % modulo + modulo) % modulo;\n      else\n        maxPower = maxPower * power % modulo;\n      if (hashed == hashValue)\n        bestLeft = i;\n    }\n\n    return s.substr(bestLeft, k);\n  }\n};","hash":"996a08a42d459458b0126d3aad1ada61743b6f0823e709ba53f81e4f225cc7a9","origins":[{"source":"solutions","path":"2156-find-substring-with-given-hash-value/2156-find-substring-with-given-hash-value.cpp"}]},{"language":"java","name":"2156-find-substring-with-given-hash-value.java","code":"class Solution {\n  public String subStrHash(String s, int power, int modulo, int k, int hashValue) {\n    long maxPower = 1;\n    long hashed = 0;\n    int bestLeft = -1;\n\n    for (int i = s.length() - 1; i >= 0; --i) {\n      hashed = (hashed * power + val(s.charAt(i))) % modulo;\n      if (i + k < s.length())\n        hashed = (hashed - val(s.charAt(i + k)) * maxPower % modulo + modulo) % modulo;\n      else\n        maxPower = maxPower * power % modulo;\n      if (hashed == hashValue)\n        bestLeft = i;\n    }\n\n    return s.substring(bestLeft, bestLeft + k);\n  }\n\n  private int val(char c) {\n    return c - 'a' + 1;\n  }\n}","hash":"aa48445343c2d0d82389c0febee688fb5ae3b29c5b96c813cc89ba44f0280526","origins":[{"source":"solutions","path":"2156-find-substring-with-given-hash-value/2156-find-substring-with-given-hash-value.java"}]},{"language":"python","name":"2156-find-substring-with-given-hash-value.py","code":"class Solution:\n  def subStrHash(self, s: str, power: int, modulo: int, k: int, hashValue: int) -> str:\n    maxPower = pow(power, k, modulo)\n    hashed = 0\n\n    def val(c: chr) -> int:\n      return ord(c) - ord('a') + 1\n\n    for i, c in reversed(list(enumerate(s))):\n      hashed = (hashed * power + val(c)) % modulo\n      if i + k < len(s):\n        hashed = (hashed - val(s[i + k]) * maxPower) % modulo\n      if hashed == hashValue:\n        bestLeft = i\n\n    return s[bestLeft:bestLeft + k]","hash":"7552971e86d4ea6b0f435413c83c134192270c956a1f0972538a1103c85529c3","origins":[{"source":"solutions","path":"2156-find-substring-with-given-hash-value/2156-find-substring-with-given-hash-value.py"}]}],"sources":["solutions"]},"lc-2172":{"key":"lc-2172","number":2172,"title":"Maximum AND Sum of Array","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2172-maximum-and-sum-of-array/README.md","text":"<h2><a href=\"https://leetcode.com/problems/maximum-and-sum-of-array/\">2172. Maximum AND Sum of Array</a></h2><h3>Hard</h3><hr><div><p>You are given an integer array <code>nums</code> of length <code>n</code> and an integer <code>numSlots</code> such that <code>2 * numSlots &gt;= n</code>. There are <code>numSlots</code> slots numbered from <code>1</code> to <code>numSlots</code>.</p>\n\n<p>You have to place all <code>n</code> integers into the slots such that each slot contains at <strong>most</strong> two numbers. The <strong>AND sum</strong> of a given placement is the sum of the <strong>bitwise</strong> <code>AND</code> of every number with its respective slot number.</p>\n\n<ul>\n\t<li>For example, the <strong>AND sum</strong> of placing the numbers <code>[1, 3]</code> into slot <u><code>1</code></u> and <code>[4, 6]</code> into slot <u><code>2</code></u> is equal to <code>(1 AND <u>1</u>) + (3 AND <u>1</u>) + (4 AND <u>2</u>) + (6 AND <u>2</u>) = 1 + 1 + 0 + 2 = 4</code>.</li>\n</ul>\n\n<p>Return <em>the maximum possible <strong>AND sum</strong> of </em><code>nums</code><em> given </em><code>numSlots</code><em> slots.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,2,3,4,5,6], numSlots = 3\n<strong>Output:</strong> 9\n<strong>Explanation:</strong> One possible placement is [1, 4] into slot <u>1</u>, [2, 6] into slot <u>2</u>, and [3, 5] into slot <u>3</u>. \nThis gives the maximum AND sum of (1 AND <u>1</u>) + (4 AND <u>1</u>) + (2 AND <u>2</u>) + (6 AND <u>2</u>) + (3 AND <u>3</u>) + (5 AND <u>3</u>) = 1 + 0 + 2 + 2 + 3 + 1 = 9.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,3,10,4,7,1], numSlots = 9\n<strong>Output:</strong> 24\n<strong>Explanation:</strong> One possible placement is [1, 1] into slot <u>1</u>, [3] into slot <u>3</u>, [4] into slot <u>4</u>, [7] into slot <u>7</u>, and [10] into slot <u>9</u>.\nThis gives the maximum AND sum of (1 AND <u>1</u>) + (1 AND <u>1</u>) + (3 AND <u>3</u>) + (4 AND <u>4</u>) + (7 AND <u>7</u>) + (10 AND <u>9</u>) = 1 + 1 + 3 + 4 + 7 + 8 = 24.\nNote that slots 2, 5, 6, and 8 are empty which is permitted.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == nums.length</code></li>\n\t<li><code>1 &lt;= numSlots &lt;= 9</code></li>\n\t<li><code>1 &lt;= n &lt;= 2 * numSlots</code></li>\n\t<li><code>1 &lt;= nums[i] &lt;= 15</code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2172-maximum-and-sum-of-array.cpp","code":"class Solution {\n public:\n  int maximumANDSum(vector<int>& nums, int numSlots) {\n    const int n = 2 * numSlots;\n    const int nSelected = 1 << n;\n    // dp[i] := max value given mask representing the nums selected\n    vector<int> dp(nSelected);\n\n    nums.resize(n);\n\n    for (int mask = 1; mask < nSelected; ++mask) {\n      const int selected = __builtin_popcount(mask);\n      const int slot = (selected + 1) / 2;  // (1, 2) -> 1, (3, 4) -> 2\n      for (int i = 0; i < n; ++i)\n        if (mask >> i & 1)  // assign nums[i] to `slot`-th slot\n          dp[mask] = max(dp[mask], dp[mask ^ 1 << i] + (slot & nums[i]));\n    }\n\n    return dp.back();\n  }\n};","hash":"735a6a79f8cdbd27e014840378d70b48a33879ce72c2634777f0edcece9e7b92","origins":[{"source":"solutions","path":"2172-maximum-and-sum-of-array/2172-maximum-and-sum-of-array.cpp"}]},{"language":"java","name":"2172-maximum-and-sum-of-array.java","code":"class Solution {\n  public int maximumANDSum(int[] nums, int numSlots) {\n    final int n = 2 * numSlots;\n    final int nSelected = 1 << n;\n    // dp[i] := max value given mask representing the nums selected\n    int[] dp = new int[nSelected];\n    int[] A = Arrays.copyOf(nums, n);\n\n    for (int mask = 1; mask < nSelected; ++mask) {\n      final int selected = Integer.bitCount(mask);\n      final int slot = (selected + 1) / 2; // (1, 2) -> 1, (3, 4) -> 2\n      for (int i = 0; i < n; ++i)\n        if ((mask >> i & 1) == 1) // assign A[i] to `slot`-th slot\n          dp[mask] = Math.max(dp[mask], dp[mask ^ 1 << i] + (slot & A[i]));\n    }\n\n    return dp[nSelected - 1];\n  }\n}","hash":"357a0ccf0edb2ee475faab2e3cdfbf6e8ede37d21d3efb95a53122fd6b44faf0","origins":[{"source":"solutions","path":"2172-maximum-and-sum-of-array/2172-maximum-and-sum-of-array.java"}]}],"sources":["solutions"]},"lc-2187":{"key":"lc-2187","number":2187,"title":"minimum time to complete trip","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long minimumTime(vector<int>& time, int totalTrips) {\n    long long l = 1;\n    long long r =\n        *min_element(begin(time), end(time)) * static_cast<long>(totalTrips);\n\n    while (l < r) {\n      const long long m = (l + r) / 2;\n      if (numTrips(time, m) >= totalTrips)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return l;\n  }\n\n  long numTrips(const vector<int>& times, long m) {\n    return accumulate(begin(times), end(times), 0L,\n                      [&](long subtotal, int t) { return subtotal + m / t; });\n  }\n};","hash":"543e7219dbeb6e55bbcb76087b161fbbabd0f61073ab0aedb07d9ca83232e416","origins":[{"source":"solutions","path":"2187-minimum-time-to-complete-trip/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long minimumTime(int[] time, int totalTrips) {\n    long l = 1;\n    long r = Arrays.stream(time).min().getAsInt() * (long) totalTrips;\n\n    while (l < r) {\n      final long m = (l + r) / 2;\n      if (numTrips(time, m) >= totalTrips)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return l;\n  }\n\n  private long numTrips(int[] time, long m) {\n    return Arrays.stream(time).asLongStream().reduce(0L, (subtotal, t) -> subtotal + m / t);\n  }\n}","hash":"197478a68297350f5168909d35432fc25ebfc07b636f90d214465d92238a6b5a","origins":[{"source":"solutions","path":"2187-minimum-time-to-complete-trip/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def minimumTime(self, time: List[int], totalTrips: int) -> int:\n    l = 1\n    r = min(time) * totalTrips\n\n    while l < r:\n      m = (l + r) // 2\n      if sum(m // t for t in time) >= totalTrips:\n        r = m\n      else:\n        l = m + 1\n\n    return l","hash":"71920a2d980290c2354921e55f04a726ca3261649791fb2a402680649b3a5186","origins":[{"source":"solutions","path":"2187-minimum-time-to-complete-trip/solution.py"}]}],"sources":["solutions"]},"lc-2214":{"key":"lc-2214","number":2214,"title":"Minimum Health to Beat Game","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2214-minimum-health-to-beat-game/README.md","text":"<h2><a href=\"https://leetcode.com/problems/minimum-health-to-beat-game/\">2214. Minimum Health to Beat Game</a></h2><h3>Medium</h3><hr><div><p>You are playing a game that has <code>n</code> levels numbered from <code>0</code> to <code>n - 1</code>. You are given a <strong>0-indexed</strong> integer array <code>damage</code> where <code>damage[i]</code> is the amount of health you will lose to complete the <code>i<sup>th</sup></code> level.</p>\n\n<p>You are also given an integer <code>armor</code>. You may use your armor ability <strong>at most once</strong> during the game on <strong>any</strong> level which will protect you from <strong>at most</strong> <code>armor</code> damage.</p>\n\n<p>You must complete the levels in order and your health must be <strong>greater than</strong> <code>0</code> at all times to beat the game.</p>\n\n<p>Return <em>the <strong>minimum</strong> health you need to start with to beat the game.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> damage = [2,7,4,3], armor = 4\n<strong>Output:</strong> 13\n<strong>Explanation:</strong> One optimal way to beat the game starting at 13 health is:\nOn round 1, take 2 damage. You have 13 - 2 = 11 health.\nOn round 2, take 7 damage. You have 11 - 7 = 4 health.\nOn round 3, use your armor to protect you from 4 damage. You have 4 - 0 = 4 health.\nOn round 4, take 3 damage. You have 4 - 3 = 1 health.\nNote that 13 is the minimum health you need to start with to beat the game.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> damage = [2,5,3,4], armor = 7\n<strong>Output:</strong> 10\n<strong>Explanation:</strong> One optimal way to beat the game starting at 10 health is:\nOn round 1, take 2 damage. You have 10 - 2 = 8 health.\nOn round 2, use your armor to protect you from 5 damage. You have 8 - 0 = 8 health.\nOn round 3, take 3 damage. You have 8 - 3 = 5 health.\nOn round 4, take 4 damage. You have 5 - 4 = 1 health.\nNote that 10 is the minimum health you need to start with to beat the game.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> damage = [3,3,3], armor = 0\n<strong>Output:</strong> 10\n<strong>Explanation:</strong> One optimal way to beat the game starting at 10 health is:\nOn round 1, take 3 damage. You have 10 - 3 = 7 health.\nOn round 2, take 3 damage. You have 7 - 3 = 4 health.\nOn round 3, take 3 damage. You have 4 - 3 = 1 health.\nNote that you did not use your armor ability.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == damage.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= damage[i] &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= armor &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2214-minimum-health-to-beat-game.cpp","code":"// solved by Milon\n\nclass Solution {\npublic:\n    \n    bool isPossible(long long &tar, int armor, vector<int> &damage) {\n        int n = damage.size();\n        int mx = 0;\n        long long val = tar;\n        for (auto &v : damage) {\n            mx = max(mx, v);\n            if (v > val && armor > 0) {\n                val += min(armor, mx);\n                armor = 0;\n            }\n            val -= v;\n        }\n        if (armor) val += armor;\n        return val > 0;\n    }\n    \n    long long minimumHealth(vector<int>& damage, int armor) {\n        long long st = 1, ed = 1e10 + 20, ans = -1;\n        while (st <= ed) {\n            auto mid = (st + ed) / 2;\n            if (isPossible(mid, armor, damage)) {\n                ans = mid;\n                ed = mid - 1;\n            } else {\n                st = mid + 1;\n            }\n        }\n        return ans;\n    }\n};","hash":"6e3e8f6b9f8f45c31c7c9cf1b27945ccfa2dc71f628afc5ae2d3e8364ffc923e","origins":[{"source":"premium","path":"2214-minimum-health-to-beat-game/2214-minimum-health-to-beat-game.cpp"}]}],"sources":["premium"]},"lc-2215":{"key":"lc-2215","number":2215,"title":"Find the Difference of Two Arrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  vector<vector<int>> findDifference(vector<int>& nums1, vector<int>& nums2) {\n    vector<vector<int>> ans(2);\n    unordered_set<int> set1{begin(nums1), end(nums1)};\n    unordered_set<int> set2{begin(nums2), end(nums2)};\n\n    for (const int num : set1)\n      if (!set2.count(num))\n        ans[0].push_back(num);\n\n    for (const int num : set2)\n      if (!set1.count(num))\n        ans[1].push_back(num);\n\n    return ans;\n  }\n};","hash":"00c32a0d14a4db399102765dd5b95b111dcc5c19420fcb14e513d80e2d467941","origins":[{"source":"solutions","path":"2215-Find the Difference of Two Arrays/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public List<List<Integer>> findDifference(int[] nums1, int[] nums2) {\n    Set<Integer> set1 = Arrays.stream(nums1).boxed().collect(Collectors.toSet());\n    Set<Integer> set2 = Arrays.stream(nums2).boxed().collect(Collectors.toSet());\n    Arrays.stream(nums1).forEach(set2::remove);\n    Arrays.stream(nums2).forEach(set1::remove);\n    return Arrays.asList(new ArrayList<>(set1), new ArrayList<>(set2));\n  }\n}","hash":"77f94f9677f79e3641cada9347f93e44952b285ff0c75c73b6616cbf8c939116","origins":[{"source":"solutions","path":"2215-Find the Difference of Two Arrays/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def findDifference(self, nums1: List[int], nums2: List[int]) -> List[List[int]]:\n    set1 = set(nums1)\n    set2 = set(nums2)\n    return [set1 - set2, set2 - set1]","hash":"14c3b6135caaa1718deabb2405a05810718cfe4faaefe740a964a80f6cedf271","origins":[{"source":"solutions","path":"2215-Find the Difference of Two Arrays/solution.py"}]},{"language":"python","name":"Find the Difference of Two Arrays.py","code":"class Solution:\n    def findDifference(self, nums1: List[int], nums2: List[int]) -> List[List[int]]:\n        return [set(nums1) - set(nums2), set(nums2) - set(nums1)]","hash":"18eca6d0c01d24862ed3a3f0210ac06b9fda16e8f6d62891724b445f7f5e23d9","origins":[{"source":"solutions","path":"Find the Difference of Two Arrays.py"}]}],"sources":["solutions"]},"lc-2218":{"key":"lc-2218","number":2218,"title":"Maximum Value of K Coins From Piles","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int maxValueOfCoins(vector<vector<int>>& piles, int k) {\n    // dp[i][k] := max value of picking k coins from piles[i:]\n    dp.resize(piles.size(), vector<int>(k + 1));\n    return maxValueOfCoins(piles, 0, k);\n  }\n\n private:\n  vector<vector<int>> dp;\n\n  int maxValueOfCoins(const vector<vector<int>>& piles, int i, size_t k) {\n    if (i == piles.size() || k == 0)\n      return 0;\n    if (dp[i][k])\n      return dp[i][k];\n\n    int ans =\n        maxValueOfCoins(piles, i + 1, k);  // Pick 0 coins from current pile\n    int val = 0;                           // Coins picked from current pile\n\n    // Try to pick 1, 2, ..., k coins from current pile\n    for (int j = 0; j < min(piles[i].size(), k); ++j) {\n      val += piles[i][j];\n      ans = max(ans, val + maxValueOfCoins(piles, i + 1, k - j - 1));\n    }\n\n    return dp[i][k] = ans;\n  }\n};","hash":"c744b69dbc86ebb33c374155fe042f40810280a51b05b1b470013f81b4b5c82d","origins":[{"source":"solutions","path":"2218-Maximum Value of K Coins From Piles/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int maxValueOfCoins(List<List<Integer>> piles, int k) {\n    // dp[i][k] := max value of picking k coins from piles[i:]\n    dp = new Integer[piles.size()][k + 1];\n    return maxValueOfCoins(piles, 0, k);\n  }\n\n  private Integer[][] dp;\n\n  private int maxValueOfCoins(List<List<Integer>> piles, int i, int k) {\n    if (i == piles.size() || k == 0)\n      return 0;\n    if (dp[i][k] != null)\n      return dp[i][k];\n\n    int ans = maxValueOfCoins(piles, i + 1, k); // Pick 0 coins from current pile\n    int val = 0;                                // Coins picked from current pile\n\n    // Try to pick 1, 2, ..., k coins from current pile\n    for (int j = 0; j < Math.min(piles.get(i).size(), k); ++j) {\n      val += piles.get(i).get(j);\n      ans = Math.max(ans, val + maxValueOfCoins(piles, i + 1, k - j - 1));\n    }\n\n    return dp[i][k] = ans;\n  }\n}","hash":"0369d71f50c9896011c623afe53a2bf8892abd8b43cf1653b546208eaa5d4102","origins":[{"source":"solutions","path":"2218-Maximum Value of K Coins From Piles/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def maxValueOfCoins(self, piles: List[List[int]], k: int) -> int:\n    # dp(i, k) := max value of picking k coins from piles[i:]\n    @functools.lru_cache(None)\n    def dp(i: int, k: int) -> int:\n      if i == len(piles) or k == 0:\n        return 0\n\n      ans = dp(i + 1, k)  # Pick 0 coins from current pile\n      val = 0  # Coins picked from current pile\n\n      # Try to pick 1, 2, ..., k coins from current pile\n      for j in range(min(len(piles[i]), k)):\n        val += piles[i][j]\n        ans = max(ans, val + dp(i + 1, k - j - 1))\n\n      return ans\n\n    return dp(0, k)","hash":"0ae83655f7fa6b2c88ce37c46ef9e76d3da9f3c15200e571e236fb24cf1810a1","origins":[{"source":"solutions","path":"2218-Maximum Value of K Coins From Piles/solution.py"}]},{"language":"python","name":"Maximum Value of K Coins From Piles.py","code":"class Solution:\n    def maxValueOfCoins(self, piles: List[List[int]], k: int) -> int:\n        n = len(piles)\n\n        @lru_cache(None)\n        def helper(i, coins):\n            if i == 0:\n                return 0\n            currentSum, result = 0, 0\n            for currentCoins in range(0, min(len(piles[i - 1]), coins) + 1):\n                if currentCoins > 0:\n                    currentSum += piles[i - 1][currentCoins - 1]\n                result = max(result, helper(i - 1, coins - currentCoins) + currentSum)\n            return result\n        \n        return helper(n, k)","hash":"e0d907b21c959498fd6c560d571601b26bd1a50bbea662b5dbfd3edae30e9590","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Maximum Value of K Coins From Piles.py"}]}],"sources":["solutions"]},"lc-2219":{"key":"lc-2219","number":2219,"title":"Maximum Sum Score of Array","difficulty":"Medium","tags":[],"documents":[{"source":"premium","path":"2219-maximum-sum-score-of-array/README.md","text":"<h2><a href=\"https://leetcode.com/problems/maximum-sum-score-of-array/\">2219. Maximum Sum Score of Array</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> integer array <code>nums</code> of length <code>n</code>.</p>\n\n<p>The <strong>sum </strong><strong>score</strong> of <code>nums</code> at an index <code>i</code> where <code>0 &lt;= i &lt; n</code> is the <strong>maximum</strong> of:</p>\n\n<ul>\n\t<li>The sum of the <strong>first</strong> <code>i + 1</code> elements of <code>nums</code>.</li>\n\t<li>The sum of the <strong>last</strong> <code>n - i</code> elements of <code>nums</code>.</li>\n</ul>\n\n<p>Return <em>the <strong>maximum</strong> <strong>sum </strong><strong>score</strong> of </em><code>nums</code><em> at any index.</em></p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [4,3,-2,5]\n<strong>Output:</strong> 10\n<strong>Explanation:</strong>\nThe sum score at index 0 is max(4, 4 + 3 + -2 + 5) = max(4, 10) = 10.\nThe sum score at index 1 is max(4 + 3, 3 + -2 + 5) = max(7, 6) = 7.\nThe sum score at index 2 is max(4 + 3 + -2, -2 + 5) = max(5, 3) = 5.\nThe sum score at index 3 is max(4 + 3 + -2 + 5, 5) = max(10, 5) = 10.\nThe maximum sum score of nums is 10.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [-3,-5]\n<strong>Output:</strong> -3\n<strong>Explanation:</strong>\nThe sum score at index 0 is max(-3, -3 + -5) = max(-3, -8) = -3.\nThe sum score at index 1 is max(-3 + -5, -5) = max(-8, -5) = -5.\nThe maximum sum score of nums is -3.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>n == nums.length</code></li>\n\t<li><code>1 &lt;= n &lt;= 10<sup>5</sup></code></li>\n\t<li><code>-10<sup>5</sup> &lt;= nums[i] &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2219-maximum-sum-score-of-array.cpp","code":"class Solution {\npublic:\n    long long maximumSumScore(vector<int>& nums) {\n        long long rightSum = 0;\n        for (auto &v : nums) rightSum += v;\n        long long leftSum = 0, ans = nums[0];\n        for (auto &v : nums) {\n            leftSum += v;\n            ans = max(ans, max(leftSum, rightSum));\n            rightSum -= v;\n        }\n        return ans;\n    }\n};","hash":"a293f381deec894d1891f926c4273d6034a69d912e5b8e4a9e84bc643601cb1d","origins":[{"source":"premium","path":"2219-maximum-sum-score-of-array/2219-maximum-sum-score-of-array.cpp"}]}],"sources":["premium"]},"lc-2225":{"key":"lc-2225","number":2225,"title":"Find Players With Zero or One Losses","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2225-find-players-with-zero-or-one-losses/README.md","text":"<h2><a href=\"https://leetcode.com/problems/find-players-with-zero-or-one-losses/\">2225. Find Players With Zero or One Losses</a></h2><h3>Medium</h3><hr><div><p>You are given an integer array <code>matches</code> where <code>matches[i] = [winner<sub>i</sub>, loser<sub>i</sub>]</code> indicates that the player <code>winner<sub>i</sub></code> defeated player <code>loser<sub>i</sub></code> in a match.</p>\n\n<p>Return <em>a list </em><code>answer</code><em> of size </em><code>2</code><em> where:</em></p>\n\n<ul>\n\t<li><code>answer[0]</code> is a list of all players that have <strong>not</strong> lost any matches.</li>\n\t<li><code>answer[1]</code> is a list of all players that have lost exactly <strong>one</strong> match.</li>\n</ul>\n\n<p>The values in the two lists should be returned in <strong>increasing</strong> order.</p>\n\n<p><strong>Note:</strong></p>\n\n<ul>\n\t<li>You should only consider the players that have played <strong>at least one</strong> match.</li>\n\t<li>The testcases will be generated such that <strong>no</strong> two matches will have the <strong>same</strong> outcome.</li>\n</ul>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n\n<pre><strong>Input:</strong> matches = [[1,3],[2,3],[3,6],[5,6],[5,7],[4,5],[4,8],[4,9],[10,4],[10,9]]\n<strong>Output:</strong> [[1,2,10],[4,5,7,8]]\n<strong>Explanation:</strong>\nPlayers 1, 2, and 10 have not lost any matches.\nPlayers 4, 5, 7, and 8 each have lost one match.\nPlayers 3, 6, and 9 each have lost two matches.\nThus, answer[0] = [1,2,10] and answer[1] = [4,5,7,8].\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n\n<pre><strong>Input:</strong> matches = [[2,3],[1,3],[5,4],[6,4]]\n<strong>Output:</strong> [[1,2,5,6],[]]\n<strong>Explanation:</strong>\nPlayers 1, 2, 5, and 6 have not lost any matches.\nPlayers 3 and 4 each have lost two matches.\nThus, answer[0] = [1,2,5,6] and answer[1] = [].\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= matches.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>matches[i].length == 2</code></li>\n\t<li><code>1 &lt;= winner<sub>i</sub>, loser<sub>i</sub> &lt;= 10<sup>5</sup></code></li>\n\t<li><code>winner<sub>i</sub> != loser<sub>i</sub></code></li>\n\t<li>All <code>matches[i]</code> are <strong>unique</strong>.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2225-find-players-with-zero-or-one-losses.cpp","code":"class Solution {\n public:\n  vector<vector<int>> findWinners(vector<vector<int>>& matches) {\n    vector<vector<int>> ans(2);\n    map<int, int> lossesCount;\n\n    for (const vector<int>& m : matches) {\n      const int winner = m[0];\n      const int loser = m[1];\n      if (!lossesCount.count(winner))\n        lossesCount[winner] = 0;\n      ++lossesCount[loser];\n    }\n\n    for (const auto& [player, nLosses] : lossesCount)\n      if (nLosses < 2)\n        ans[nLosses].push_back(player);\n\n    return ans;\n  }\n};","hash":"320bfa3ea9f65ee5b38de727bc906be767373dd17d46964017915c009591fbdb","origins":[{"source":"solutions","path":"2225-find-players-with-zero-or-one-losses/2225-find-players-with-zero-or-one-losses.cpp"}]},{"language":"java","name":"2225-find-players-with-zero-or-one-losses.java","code":"class Solution {\n  public List<List<Integer>> findWinners(int[][] matches) {\n    List<List<Integer>> ans = Arrays.asList(new ArrayList<>(), new ArrayList<>());\n    Map<Integer, Integer> lossesCount = new TreeMap<>();\n\n    for (int[] m : matches) {\n      final int winner = m[0];\n      final int loser = m[1];\n      if (!lossesCount.containsKey(winner))\n        lossesCount.put(winner, 0);\n      lossesCount.merge(loser, 1, Integer::sum);\n    }\n\n    for (final int player : lossesCount.keySet()) {\n      final int nLosses = lossesCount.get(player);\n      if (nLosses < 2)\n        ans.get(nLosses).add(player);\n    }\n\n    return ans;\n  }\n}","hash":"8e371f7473d053a1c3a3a5be399c705214d7bd74273ee58f57c22782db96e8ba","origins":[{"source":"solutions","path":"2225-find-players-with-zero-or-one-losses/2225-find-players-with-zero-or-one-losses.java"}]},{"language":"python","name":"2225-find-players-with-zero-or-one-losses.py","code":"class Solution:\n  def findWinners(self, matches: List[List[int]]) -> List[List[int]]:\n    ans = [[] for _ in range(2)]\n    lossesCount = Counter()\n\n    for winner, loser in matches:\n      if winner not in lossesCount:\n        lossesCount[winner] = 0\n      lossesCount[loser] += 1\n\n    for player, nLosses in lossesCount.items():\n      if nLosses < 2:\n        ans[nLosses].append(player)\n\n    return [sorted(ans[0]), sorted(ans[1])]","hash":"240a27f9a3d851cefa9e4ddcefa34eff96ea1b974ae4a464a6f698b1a541b993","origins":[{"source":"solutions","path":"2225-find-players-with-zero-or-one-losses/2225-find-players-with-zero-or-one-losses.py"}]},{"language":"python","name":"Find Players With Zero or One Losses.py","code":"class Solution:\n    def findWinners(self, matches: List[List[int]]) -> List[List[int]]:\n        freqMap = defaultdict(int)\n        for match in matches:\n            freqMap[match[0]] += 0\n            freqMap[match[1]] += 1\n        noMatchesLost, oneMatchLost = set(), set()\n        for player, lostCount in freqMap.items():\n            if lostCount == 0:\n                noMatchesLost.add(player)\n            elif lostCount == 1:\n                oneMatchLost.add(player)\n        return [sorted(noMatchesLost), sorted(oneMatchLost)]","hash":"a9c58b2984a16c12840ecc7b8184f1c0a1f1f129d398748eda78049f9555b975","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-11 Leetcoding Challenge/Find Players With Zero or One Losses.py"}]}],"sources":["solutions"]},"lc-2229":{"key":"lc-2229","number":2229,"title":"Check if an Array Is Consecutive","difficulty":"Easy","tags":[],"documents":[{"source":"premium","path":"2229-check-if-an-array-is-consecutive/README.md","text":"<h2><a href=\"https://leetcode.com/problems/check-if-an-array-is-consecutive/\">2229. Check if an Array Is Consecutive</a></h2><h3>Easy</h3><hr><div><p>Given an integer array <code>nums</code>, return <code>true</code> <em>if </em><code>nums</code><em> is <strong>consecutive</strong>, otherwise return </em><code>false</code><em>.</em></p>\n\n<p>An array is <strong>consecutive </strong>if it contains every number in the range <code>[x, x + n - 1]</code> (<strong>inclusive</strong>), where <code>x</code> is the minimum number in the array and <code>n</code> is the length of the array.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,3,4,2]\n<strong>Output:</strong> true\n<strong>Explanation:</strong>\nThe minimum value is 1 and the length of nums is 4.\nAll of the values in the range [x, x + n - 1] = [1, 1 + 4 - 1] = [1, 4] = (1, 2, 3, 4) occur in nums.\nTherefore, nums is consecutive.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,3]\n<strong>Output:</strong> false\n<strong>Explanation:</strong>\nThe minimum value is 1 and the length of nums is 2.\nThe value 2 in the range [x, x + n - 1] = [1, 1 + 2 - 1], = [1, 2] = (1, 2) does not occur in nums.\nTherefore, nums is not consecutive.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> nums = [3,5,4]\n<strong>Output:</strong> true\n<strong>Explanation:</strong>\nThe minimum value is 3 and the length of nums is 3.\nAll of the values in the range [x, x + n - 1] = [3, 3 + 3 - 1] = [3, 5] = (3, 4, 5) occur in nums.\nTherefore, nums is consecutive.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= nums[i] &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2229-check-if-an-array-is-consecutive.cpp","code":"class Solution {\npublic:\n    bool isConsecutive(vector<int>& nums) {\n        int mn = *min_element(nums.begin(), nums.end());\n        int n = nums.size();\n        int mx = mn + n - 1;\n        for (auto &v : nums) {\n            int num = abs(v);\n            if (num > mx) return false;\n            nums[num - mn] *= -1;\n        }\n        int cnt = 0;\n        for (auto &v : nums) {\n            if (v == 0) {\n                cnt++;\n                continue;\n            }\n            if (v > 0) return false;\n        }\n        if (cnt > 1) return false; \n        return true;\n    }\n};","hash":"07ed32ed62aa5baf3074c19c26a8bcb4c256e0a4a492f9c59c9412bfedb0f223","origins":[{"source":"premium","path":"2229-check-if-an-array-is-consecutive/2229-check-if-an-array-is-consecutive.cpp"}]}],"sources":["premium"]},"lc-2256":{"key":"lc-2256","number":2256,"title":"Minimum Average Difference","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2256-minimum-average-difference/README.md","text":"<h2><a href=\"https://leetcode.com/problems/minimum-average-difference/\">2256. Minimum Average Difference</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> integer array <code>nums</code> of length <code>n</code>.</p>\n\n<p>The <strong>average difference</strong> of the index <code>i</code> is the <strong>absolute</strong> <strong>difference</strong> between the average of the <strong>first</strong> <code>i + 1</code> elements of <code>nums</code> and the average of the <strong>last</strong> <code>n - i - 1</code> elements. Both averages should be <strong>rounded down</strong> to the nearest integer.</p>\n\n<p>Return<em> the index with the <strong>minimum average difference</strong></em>. If there are multiple such indices, return the <strong>smallest</strong> one.</p>\n\n<p><strong>Note:</strong></p>\n\n<ul>\n\t<li>The <strong>absolute difference</strong> of two numbers is the absolute value of their difference.</li>\n\t<li>The <strong>average</strong> of <code>n</code> elements is the <strong>sum</strong> of the <code>n</code> elements divided (<strong>integer division</strong>) by <code>n</code>.</li>\n\t<li>The average of <code>0</code> elements is considered to be <code>0</code>.</li>\n</ul>\n\n<p>&nbsp;</p>\n<p><strong class=\"example\">Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [2,5,3,9,5,3]\n<strong>Output:</strong> 3\n<strong>Explanation:</strong>\n- The average difference of index 0 is: |2 / 1 - (5 + 3 + 9 + 5 + 3) / 5| = |2 / 1 - 25 / 5| = |2 - 5| = 3.\n- The average difference of index 1 is: |(2 + 5) / 2 - (3 + 9 + 5 + 3) / 4| = |7 / 2 - 20 / 4| = |3 - 5| = 2.\n- The average difference of index 2 is: |(2 + 5 + 3) / 3 - (9 + 5 + 3) / 3| = |10 / 3 - 17 / 3| = |3 - 5| = 2.\n- The average difference of index 3 is: |(2 + 5 + 3 + 9) / 4 - (5 + 3) / 2| = |19 / 4 - 8 / 2| = |4 - 4| = 0.\n- The average difference of index 4 is: |(2 + 5 + 3 + 9 + 5) / 5 - 3 / 1| = |24 / 5 - 3 / 1| = |4 - 3| = 1.\n- The average difference of index 5 is: |(2 + 5 + 3 + 9 + 5 + 3) / 6 - 0| = |27 / 6 - 0| = |4 - 0| = 4.\nThe average difference of index 3 is the minimum average difference so return 3.\n</pre>\n\n<p><strong class=\"example\">Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [0]\n<strong>Output:</strong> 0\n<strong>Explanation:</strong>\nThe only index is 0 so return 0.\nThe average difference of index 0 is: |0 / 1 - 0| = |0 - 0| = 0.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>0 &lt;= nums[i] &lt;= 10<sup>5</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2256-minimum-average-difference.cpp","code":"class Solution {\n public:\n  int minimumAverageDifference(vector<int>& nums) {\n    const int n = nums.size();\n    int ans = 0;\n    int minDiff = INT_MAX;\n    long prefix = 0;\n    long suffix = accumulate(begin(nums), end(nums), 0L);\n\n    for (int i = 0; i < nums.size(); ++i) {\n      prefix += nums[i];\n      suffix -= nums[i];\n      const int prefixAvg = prefix / (i + 1);\n      const int suffixAvg = (i == n - 1) ? 0 : suffix / (n - i - 1);\n      const int diff = abs(prefixAvg - suffixAvg);\n      if (diff < minDiff) {\n        ans = i;\n        minDiff = diff;\n      }\n    }\n\n    return ans;\n  }\n};","hash":"b7f183fa64de9cfd297992bd5c1b44bd953353557e831246f1c256e4f550ce80","origins":[{"source":"solutions","path":"2256-minimum-average-difference/2256-minimum-average-difference.cpp"}]},{"language":"java","name":"2256-minimum-average-difference.java","code":"class Solution {\n  public int minimumAverageDifference(int[] nums) {\n    final int n = nums.length;\n    int ans = 0;\n    int minDiff = Integer.MAX_VALUE;\n    long prefix = 0;\n    long suffix = Arrays.stream(nums).asLongStream().sum();\n\n    for (int i = 0; i < nums.length; ++i) {\n      prefix += nums[i];\n      suffix -= nums[i];\n      final int prefixAvg = (int) (prefix / (i + 1));\n      final int suffixAvg = (i == n - 1) ? 0 : (int) (suffix / (n - i - 1));\n      final int diff = Math.abs(prefixAvg - suffixAvg);\n      if (diff < minDiff) {\n        ans = i;\n        minDiff = diff;\n      }\n    }\n\n    return ans;\n  }\n}","hash":"b24ef87a22e9d1e6cbb87351d98cb30a2905a226bbc36ec8d11ff4fa17190485","origins":[{"source":"solutions","path":"2256-minimum-average-difference/2256-minimum-average-difference.java"}]},{"language":"python","name":"2256-minimum-average-difference.py","code":"class Solution:\n  def minimumAverageDifference(self, nums: List[int]) -> int:\n    n = len(nums)\n    ans = 0\n    minDiff = inf\n    prefix = 0\n    suffix = sum(nums)\n\n    for i, num in enumerate(nums):\n      prefix += num\n      suffix -= num\n      prefixAvg = prefix // (i + 1)\n      suffixAvg = 0 if i == n - 1 else suffix // (n - i - 1)\n      diff = abs(prefixAvg - suffixAvg)\n      if diff < minDiff:\n        ans = i\n        minDiff = diff\n\n    return ans","hash":"6647837064e80ab3e00db6ee127a2941cdeef5e21095d1d4ab8fb8a32c0715ae","origins":[{"source":"solutions","path":"2256-minimum-average-difference/2256-minimum-average-difference.py"}]},{"language":"python","name":"Minimum Average Difference.py","code":"class Solution:\n    def minimumAverageDifference(self, nums: List[int]) -> int:\n        left, right, minDiff, requiredIndex, n = 0, sum(nums), float('inf'), len(nums), len(nums)\n        for index, num in enumerate(nums):\n            left += num\n            right -= num\n            leftAvg = math.floor(left / (index + 1)) if (index + 1) > 0 else 0\n            rightAvg = math.floor(right / (n - index - 1)) if (n - index - 1) > 0 else 0\n            diff = abs(rightAvg - leftAvg)\n            if minDiff > diff:\n                minDiff, requiredIndex = diff, index\n        return requiredIndex","hash":"d8f15047e8a81c684186782061cbbe54b5569753dbf18751b75c86d460d307f1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Minimum Average Difference.py"}]}],"sources":["solutions"]},"lc-2272":{"key":"lc-2272","number":2272,"title":"Substring With Largest Variance","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int largestVariance(string s) {\n    int ans = 0;\n\n    for (char c1 = 'a'; c1 <= 'z'; ++c1)\n      for (char c2 = 'a'; c2 <= 'z'; ++c2)\n        if (c1 != c2)\n          ans = max(ans, kadane(s, c1, c2));\n\n    return ans;\n  }\n\n private:\n  // A := the char w/ higher freq\n  // B := the char w/ lower freq\n  int kadane(const string& s, char a, char b) {\n    int ans = 0;\n    int countA = 0;\n    int countB = 0;\n    bool canExtendPrevB = false;\n\n    for (const char c : s) {\n      if (c != a && c != b)\n        continue;\n      if (c == a)\n        ++countA;\n      else\n        ++countB;\n      if (countB > 0) {\n        // An interval should contain at least one b\n        ans = max(ans, countA - countB);\n      } else if (countB == 0 && canExtendPrevB) {\n        // Edge case: consider previous b\n        ans = max(ans, countA - 1);\n      }\n      // Reset if # of b > # of a\n      if (countB > countA) {\n        countA = 0;\n        countB = 0;\n        canExtendPrevB = true;\n      }\n    }\n\n    return ans;\n  }\n};","hash":"984e6d98b764da0341961964ef57a9666c8e94653563ea51287e190d07149805","origins":[{"source":"solutions","path":"2272-Substring With Largest Variance/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int largestVariance(String s) {\n    int ans = 0;\n\n    for (char c1 = 'a'; c1 <= 'z'; ++c1)\n      for (char c2 = 'a'; c2 <= 'z'; ++c2)\n        if (c1 != c2)\n          ans = Math.max(ans, kadane(s, c1, c2));\n\n    return ans;\n  }\n\n  // A := the char w/ higher freq\n  // B := the char w/ lower freq\n  private int kadane(final String s, char a, char b) {\n    int ans = 0;\n    int countA = 0;\n    int countB = 0;\n    boolean canExtendPrevB = false;\n\n    for (final char c : s.toCharArray()) {\n      if (c != a && c != b)\n        continue;\n      if (c == a)\n        ++countA;\n      else\n        ++countB;\n      if (countB > 0) {\n        // An interval should contain at least one b\n        ans = Math.max(ans, countA - countB);\n      } else if (countB == 0 && canExtendPrevB) {\n        // Edge case: consider previous b\n        ans = Math.max(ans, countA - 1);\n      }\n      // Reset if # of b > # of a\n      if (countB > countA) {\n        countA = 0;\n        countB = 0;\n        canExtendPrevB = true;\n      }\n    }\n\n    return ans;\n  }\n}","hash":"26ae890256904101607267b2a72bf3f51c1886f6bd4fdaa9eb557f5ad4eddf14","origins":[{"source":"solutions","path":"2272-Substring With Largest Variance/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def largestVariance(self, s: str) -> int:\n    # A := the w// higher freq\n    # B := the w// lower freq\n    def kadane(a: str, b: str) -> int:\n      ans = 0\n      countA = 0\n      countB = 0\n      canExtendPrevB = False\n\n      for c in s:\n        if c != a and c != b:\n          continue\n        if c == a:\n          countA += 1\n        else:\n          countB += 1\n        if countB > 0:\n          # An interval should contain at least one b\n          ans = max(ans, countA - countB)\n        elif countB == 0 and canExtendPrevB:\n          # Edge case: consider previous b\n          ans = max(ans, countA - 1)\n\n        # Reset if # Of b > # Of a\n        if countB > countA:\n          countA = 0\n          countB = 0\n          canExtendPrevB = True\n\n      return ans\n\n    return max(kadane(c1, c2)\n               for c1 in string.ascii_lowercase\n               for c2 in string.ascii_lowercase\n               if c1 != c2)","hash":"fbf17e9357f2ca155507708e62d9e01292d97ec756a8493edded1c10d0a0a39a","origins":[{"source":"solutions","path":"2272-Substring With Largest Variance/solution.py"}]}],"sources":["solutions"]},"lc-2289":{"key":"lc-2289","number":2289,"title":"Steps to Make Array Non-decreasing","difficulty":"Medium","tags":[],"documents":[{"source":"solutions","path":"2289-steps-to-make-array-non-decreasing/README.md","text":"<h2><a href=\"https://leetcode.com/problems/steps-to-make-array-non-decreasing/\">2289. Steps to Make Array Non-decreasing</a></h2><h3>Medium</h3><hr><div><p>You are given a <strong>0-indexed</strong> integer array <code>nums</code>. In one step, <strong>remove</strong> all elements <code>nums[i]</code> where <code>nums[i - 1] &gt; nums[i]</code> for all <code>0 &lt; i &lt; nums.length</code>.</p>\n\n<p>Return <em>the number of steps performed until </em><code>nums</code><em> becomes a <strong>non-decreasing</strong> array</em>.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [5,3,4,4,7,3,6,11,8,5,11]\n<strong>Output:</strong> 3\n<strong>Explanation:</strong> The following are the steps performed:\n- Step 1: [5,<strong><u>3</u></strong>,4,4,7,<u><strong>3</strong></u>,6,11,<u><strong>8</strong></u>,<u><strong>5</strong></u>,11] becomes [5,4,4,7,6,11,11]\n- Step 2: [5,<u><strong>4</strong></u>,4,7,<u><strong>6</strong></u>,11,11] becomes [5,4,7,11,11]\n- Step 3: [5,<u><strong>4</strong></u>,7,11,11] becomes [5,7,11,11]\n[5,7,11,11] is a non-decreasing array. Therefore, we return 3.\n</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [4,5,7,7,13]\n<strong>Output:</strong> 0\n<strong>Explanation:</strong> nums is already a non-decreasing array. Therefore, we return 0.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= nums[i] &lt;= 10<sup>9</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2289-steps-to-make-array-non-decreasing.cpp","code":"class Solution {\npublic:\n    int totalSteps(vector<int>& nums) {\n        vector<int> dp(size(nums));  // dp[i]: number of rounds for nums[i] to be removed\n         vector<int> stk;\n        for (int i = 0; i < size(nums); ++i) {\n            int curr = 0;\n            while (!empty(stk) && nums[stk.back()] <= nums[i]) {\n                curr = max(curr, dp[stk.back()]); stk.pop_back();\n            }\n            if (!empty(stk)) {\n                dp[i] = curr + 1;\n            }\n            stk.emplace_back(i);\n        }\n        return *max_element(cbegin(dp), cend(dp));\n    }\n};","hash":"99eea86179ceaaa48db1b2ce689ed21029e36bf5a69a97beabb77380ce92521d","origins":[{"source":"solutions","path":"2289-steps-to-make-array-non-decreasing/2289-steps-to-make-array-non-decreasing.cpp"}]},{"language":"python","name":"2289-steps-to-make-array-non-decreasing.py","code":"class Solution(object):\n    def totalSteps(self, nums):\n        \"\"\"\n        :type nums: List[int]\n        :rtype: int\n        \"\"\"\n        dp = [0]*len(nums)  # dp[i]: number of rounds for nums[i] to remove all the covered elements\n        stk = []\n        for i in reversed(range(len(nums))):\n            while stk and nums[stk[-1]] < nums[i]:\n                dp[i] = max(dp[i]+1, dp[stk.pop()])\n            stk.append(i)\n        return max(dp)\n\n\n# Time:  O(n)\n# Space: O(n)\n# mono stack, dp\nclass Solution2(object):\n    def totalSteps(self, nums):\n        \"\"\"\n        :type nums: List[int]\n        :rtype: int\n        \"\"\"\n        dp = [0]*len(nums)  # dp[i]: number of rounds for nums[i] to be removed\n        stk = []\n        for i in range(len(nums)):\n            curr = 0\n            while stk and nums[stk[-1]] <= nums[i]:\n                curr = max(curr, dp[stk.pop()])\n            if stk:\n                dp[i] = curr+1\n            stk.append(i)\n        return max(dp)","hash":"5f79eeff7dfd7475381ca5b6bdf13712075e4f9a9c4283cd09ddbb2b3092f7f0","origins":[{"source":"solutions","path":"2289-steps-to-make-array-non-decreasing/2289-steps-to-make-array-non-decreasing.py"}]}],"sources":["solutions"]},"lc-2301":{"key":"lc-2301","number":2301,"title":"Match Substring After Replacement","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2301-match-substring-after-replacement/README.md","text":"<h2><a href=\"https://leetcode.com/problems/match-substring-after-replacement/\">2301. Match Substring After Replacement</a></h2><h3>Hard</h3><hr><div><p>You are given two strings <code>s</code> and <code>sub</code>. You are also given a 2D character array <code>mappings</code> where <code>mappings[i] = [old<sub>i</sub>, new<sub>i</sub>]</code> indicates that you may perform the following operation <strong>any</strong> number of times:</p>\n\n<ul>\n\t<li><strong>Replace</strong> a character <code>old<sub>i</sub></code> of <code>sub</code> with <code>new<sub>i</sub></code>.</li>\n</ul>\n\n<p>Each character in <code>sub</code> <strong>cannot</strong> be replaced more than once.</p>\n\n<p>Return <code>true</code><em> if it is possible to make </em><code>sub</code><em> a substring of </em><code>s</code><em> by replacing zero or more characters according to </em><code>mappings</code>. Otherwise, return <code>false</code>.</p>\n\n<p>A <strong>substring</strong> is a contiguous non-empty sequence of characters within a string.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> s = \"fool3e7bar\", sub = \"leet\", mappings = [[\"e\",\"3\"],[\"t\",\"7\"],[\"t\",\"8\"]]\n<strong>Output:</strong> true\n<strong>Explanation:</strong> Replace the first 'e' in sub with '3' and 't' in sub with '7'.\nNow sub = \"l3e7\" is a substring of s, so we return true.</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> s = \"fooleetbar\", sub = \"f00l\", mappings = [[\"o\",\"0\"]]\n<strong>Output:</strong> false\n<strong>Explanation:</strong> The string \"f00l\" is not a substring of s and no replacements can be made.\nNote that we cannot replace '0' with 'o'.\n</pre>\n\n<p><strong>Example 3:</strong></p>\n\n<pre><strong>Input:</strong> s = \"Fool33tbaR\", sub = \"leetd\", mappings = [[\"e\",\"3\"],[\"t\",\"7\"],[\"t\",\"8\"],[\"d\",\"b\"],[\"p\",\"b\"]]\n<strong>Output:</strong> true\n<strong>Explanation:</strong> Replace the first and second 'e' in sub with '3' and 'd' in sub with 'b'.\nNow sub = \"l33tb\" is a substring of s, so we return true.\n\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= sub.length &lt;= s.length &lt;= 5000</code></li>\n\t<li><code>0 &lt;= mappings.length &lt;= 1000</code></li>\n\t<li><code>mappings[i].length == 2</code></li>\n\t<li><code>old<sub>i</sub> != new<sub>i</sub></code></li>\n\t<li><code>s</code> and <code>sub</code> consist of uppercase and lowercase English letters and digits.</li>\n\t<li><code>old<sub>i</sub></code> and <code>new<sub>i</sub></code> are either uppercase or lowercase English letters or digits.</li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2301-match-substring-after-replacement.cpp","code":"class Solution {\n public:\n  bool matchReplacement(string s, string sub, vector<vector<char>>& mappings) {\n    vector<vector<bool>> isMapped(128, vector<bool>(128));\n\n    for (const auto& m : mappings)\n      isMapped[m[0]][m[1]] = true;\n\n    for (int i = 0; i < s.length(); ++i)\n      if (canTransform(s, i, sub, isMapped))\n        return true;\n\n    return false;\n  }\n\n private:\n  bool canTransform(const string& s, int start, const string& sub,\n                    const vector<vector<bool>>& isMapped) {\n    if (start + sub.length() > s.length())\n      return false;\n\n    for (int i = 0; i < sub.length(); ++i) {\n      const char a = sub[i];        // sub's char\n      const char b = s[start + i];  // s' char\n      if (a != b && !isMapped[a][b])\n        return false;\n    }\n\n    return true;\n  }\n};","hash":"f7d3b8a7dda8f3e1a3934f5336a0692e7aa9c73bd76e5e5e115c2f01a038d206","origins":[{"source":"solutions","path":"2301-match-substring-after-replacement/2301-match-substring-after-replacement.cpp"}]},{"language":"java","name":"2301-match-substring-after-replacement.java","code":"class Solution {\n  public boolean matchReplacement(String s, String sub, char[][] mappings) {\n    boolean[][] isMapped = new boolean[128][128];\n\n    for (char[] m : mappings)\n      isMapped[m[0]][m[1]] = true;\n\n    for (int i = 0; i < s.length(); ++i)\n      if (canTransform(s, i, sub, isMapped))\n        return true;\n\n    return false;\n  }\n\n  private boolean canTransform(final String s, int start, final String sub, boolean[][] isMapped) {\n    if (start + sub.length() > s.length())\n      return false;\n\n    for (int i = 0; i < sub.length(); ++i) {\n      final char a = sub.charAt(i);       // sub's char\n      final char b = s.charAt(start + i); // s' char\n      if (a != b && !isMapped[a][b])\n        return false;\n    }\n\n    return true;\n  }\n}","hash":"5b31e85e4c45bdb5b18dab48815f12e2f790537b89d6d7f553091754bc707a05","origins":[{"source":"solutions","path":"2301-match-substring-after-replacement/2301-match-substring-after-replacement.java"}]},{"language":"python","name":"2301-match-substring-after-replacement.py","code":"class Solution:\n  def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:\n    isMapped = [[False] * 128 for _ in range(128)]\n\n    for old, new in mappings:\n      isMapped[ord(old)][ord(new)] = True\n\n    for i in range(len(s)):\n      if self._canTransform(s, i, sub, isMapped):\n        return True\n\n    return False\n\n  def _canTransform(self, s: str, start: int, sub: str, isMapped: List[List[bool]]) -> bool:\n    if start + len(sub) > len(s):\n      return False\n\n    for i in range(len(sub)):\n      a = sub[i]        # sub's char\n      b = s[start + i]  # s' char\n      if a != b and not isMapped[ord(a)][ord(b)]:\n        return False\n\n    return True","hash":"99e6e9e6301172d6c051f531fd9ab9eaf19edcff59c8c8947da9c952cce9fb12","origins":[{"source":"solutions","path":"2301-match-substring-after-replacement/2301-match-substring-after-replacement.py"}]}],"sources":["solutions"]},"lc-2302":{"key":"lc-2302","number":2302,"title":"Count Subarrays With Score Less Than K","difficulty":"Hard","tags":[],"documents":[{"source":"solutions","path":"2302-count-subarrays-with-score-less-than-k/README.md","text":"<h2><a href=\"https://leetcode.com/problems/count-subarrays-with-score-less-than-k/\">2302. Count Subarrays With Score Less Than K</a></h2><h3>Hard</h3><hr><div><p>The <strong>score</strong> of an array is defined as the <strong>product</strong> of its sum and its length.</p>\n\n<ul>\n\t<li>For example, the score of <code>[1, 2, 3, 4, 5]</code> is <code>(1 + 2 + 3 + 4 + 5) * 5 = 75</code>.</li>\n</ul>\n\n<p>Given a positive integer array <code>nums</code> and an integer <code>k</code>, return <em>the <strong>number of non-empty subarrays</strong> of</em> <code>nums</code> <em>whose score is <strong>strictly less</strong> than</em> <code>k</code>.</p>\n\n<p>A <strong>subarray</strong> is a contiguous sequence of elements within an array.</p>\n\n<p>&nbsp;</p>\n<p><strong>Example 1:</strong></p>\n\n<pre><strong>Input:</strong> nums = [2,1,4,3,5], k = 10\n<strong>Output:</strong> 6\n<strong>Explanation:</strong>\nThe 6 subarrays having scores less than 10 are:\n- [2] with score 2 * 1 = 2.\n- [1] with score 1 * 1 = 1.\n- [4] with score 4 * 1 = 4.\n- [3] with score 3 * 1 = 3. \n- [5] with score 5 * 1 = 5.\n- [2,1] with score (2 + 1) * 2 = 6.\nNote that subarrays such as [1,4] and [4,3,5] are not considered because their scores are 10 and 36 respectively, while we need scores strictly less than 10.</pre>\n\n<p><strong>Example 2:</strong></p>\n\n<pre><strong>Input:</strong> nums = [1,1,1], k = 5\n<strong>Output:</strong> 5\n<strong>Explanation:</strong>\nEvery subarray except [1,1,1] has a score less than 5.\n[1,1,1] has a score (1 + 1 + 1) * 3 = 9, which is greater than 5.\nThus, there are 5 subarrays having scores less than 5.\n</pre>\n\n<p>&nbsp;</p>\n<p><strong>Constraints:</strong></p>\n\n<ul>\n\t<li><code>1 &lt;= nums.length &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= nums[i] &lt;= 10<sup>5</sup></code></li>\n\t<li><code>1 &lt;= k &lt;= 10<sup>15</sup></code></li>\n</ul>\n</div>"}],"solutions":[{"language":"cpp","name":"2302-count-subarrays-with-score-less-than-k.cpp","code":"class Solution {\n public:\n  long long countSubarrays(vector<int>& nums, long long k) {\n    long long ans = 0;\n    long long sum = 0;\n\n    for (int l = 0, r = 0; r < nums.size(); ++r) {\n      sum += nums[r];\n      while (sum * (r - l + 1) >= k)\n        sum -= nums[l++];\n      ans += r - l + 1;\n    }\n\n    return ans;\n  }\n};","hash":"91a20eaecc1d3ba9a7e38242c6e25294778067c36bf0b6c6da347a1b0001bb01","origins":[{"source":"solutions","path":"2302-count-subarrays-with-score-less-than-k/2302-count-subarrays-with-score-less-than-k.cpp"}]},{"language":"java","name":"2302-count-subarrays-with-score-less-than-k.java","code":"class Solution {\n  public long countSubarrays(int[] nums, long k) {\n    long ans = 0;\n    long sum = 0;\n\n    for (int l = 0, r = 0; r < nums.length; ++r) {\n      sum += nums[r];\n      while (sum * (r - l + 1) >= k)\n        sum -= nums[l++];\n      ans += r - l + 1;\n    }\n\n    return ans;\n  }\n}","hash":"3300bdd2af6b3f29948efb45246f83725a3938bfbca29ec1d33e04c684897b16","origins":[{"source":"solutions","path":"2302-count-subarrays-with-score-less-than-k/2302-count-subarrays-with-score-less-than-k.java"}]}],"sources":["solutions"]},"lc-2305":{"key":"lc-2305","number":2305,"title":"Fair Distribution of Cookies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int distributeCookies(vector<int>& cookies, int k) {\n    int ans = INT_MAX;\n    dfs(cookies, 0, k, vector<int>(k), ans);\n    return ans;\n  }\n\n private:\n  void dfs(const vector<int>& cookies, int s, int k, vector<int>&& children,\n           int& ans) {\n    if (s == cookies.size()) {\n      ans = min(ans, *max_element(children.begin(), children.end()));\n      return;\n    }\n\n    for (int i = 0; i < k; ++i) {\n      children[i] += cookies[s];\n      dfs(cookies, s + 1, k, move(children), ans);\n      children[i] -= cookies[s];\n    }\n  }\n};","hash":"b3a66f15261a732255baaf404e4ebc20e697b7ded6dc85fd1aecbe70bbcbd73c","origins":[{"source":"solutions","path":"2305-Fair Distribution of Cookies/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n    int ans;\n    public int distributeCookies(int[] cookies, int k) {\n        ans= Integer.MAX_VALUE;\n        int count[]= new int[k];\n        \n        fun(0,cookies, k, count);\n        return ans;\n    }\n    public void fun(int start, int[] cookies, int k, int[] count)\n    {\n        if(start==cookies.length)\n        {\n            int max= 0;\n            for(int i=0; i<k; i++)\n            {\n                max=Math.max(max, count[i]);\n                \n            }\n            ans = Math.min(ans, max);\n            return;\n        }\n        for(int i=0;i<k; i++)\n        {\n            count[i]+=cookies[start];\n            fun(start+1, cookies, k, count);\n            count[i]-=cookies[start];\n            if(count[i]==0) break;\n        }\n    }\n}","hash":"0300228a9059804100d7bb92880dfd8cd1c714897fba0062e72b88ffcc695a1e","origins":[{"source":"solutions","path":"2305-Fair Distribution of Cookies/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n    def distributeCookies(self, cookies: List[int], k: int) -> int:\n        def dfs(p):\n            nonlocal best\n            if p==len(cookies):\n                best = min(best, max(split))\n                return\n            # give to a new kid\n            if len(split)<k:\n                split.append(cookies[p])\n                dfs(p+1)\n                split.pop()\n            # give to a kid that already has cookies\n            for i in range(len(split)):\n                if split[i]+cookies[p] < best:\n                    split[i] += cookies[p]\n                    dfs(p+1)\n                    split[i] -= cookies[p]\n\n        split = []\n        best = float(\"inf\")\n        dfs(0)\n        return best","hash":"382f4728a2be133645fc2fd854949ef7e695b2f63b9584c0ba5081c05f13f635","origins":[{"source":"solutions","path":"2305-Fair Distribution of Cookies/solution.py"}]}],"sources":["solutions"]},"lc-2328":{"key":"lc-2328","number":2328,"title":"Number of Increasing Paths in a Grid","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int countPaths(vector<vector<int>>& grid) {\n    m = grid.size();\n    n = grid[0].size();\n    int ans = 0;\n    // dp[i][j] := # of increasing paths starting from (i, j)\n    dp.resize(m, vector<int>(n, -1));\n\n    for (int i = 0; i < m; ++i)\n      for (int j = 0; j < n; ++j) {\n        ans += dfs(grid, i, j);\n        ans %= kMod;\n      }\n\n    return ans;\n  }\n\n private:\n  static constexpr int kMod = 1'000'000'007;\n  const vector<int> dirs{0, 1, 0, -1, 0};\n  int m;\n  int n;\n  vector<vector<int>> dp;\n\n  int dfs(const vector<vector<int>>& grid, int i, int j) {\n    if (dp[i][j] != -1)\n      return dp[i][j];\n\n    dp[i][j] = 1;  // Current cell contributes 1 length\n\n    for (int k = 0; k < 4; ++k) {\n      const int x = i + dirs[k];\n      const int y = j + dirs[k + 1];\n      if (x < 0 || x == m || y < 0 || y == n)\n        continue;\n      if (grid[x][y] <= grid[i][j])\n        continue;\n      dp[i][j] += dfs(grid, x, y);\n      dp[i][j] %= kMod;\n    }\n\n    return dp[i][j];\n  }\n};","hash":"aab0d7aad5eb120776175e1fd02efdb9576378ceabc3207a320c7d377bd16164","origins":[{"source":"solutions","path":"2328-Number-of-Increasing-Paths-in-a-Grid/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int countPaths(int[][] grid) {\n    m = grid.length;\n    n = grid[0].length;\n    int ans = 0;\n    // dp[i][j] := # of increasing paths starting from (i, j)\n    dp = new int[m][n];\n    Arrays.stream(dp).forEach(A -> Arrays.fill(A, -1));\n\n    for (int i = 0; i < m; ++i)\n      for (int j = 0; j < n; ++j) {\n        ans += dfs(grid, i, j);\n        ans %= kMod;\n      }\n\n    return ans;\n  }\n\n  private static final int kMod = 1_000_000_007;\n  private final int[] dirs = {0, 1, 0, -1, 0};\n  private int m;\n  private int n;\n  private int[][] dp;\n\n  private int dfs(int[][] grid, int i, int j) {\n    if (dp[i][j] != -1)\n      return dp[i][j];\n\n    dp[i][j] = 1; // Current cell contributes 1 length\n\n    for (int k = 0; k < 4; ++k) {\n      final int x = i + dirs[k];\n      final int y = j + dirs[k + 1];\n      if (x < 0 || x == m || y < 0 || y == n)\n        continue;\n      if (grid[x][y] <= grid[i][j])\n        continue;\n      dp[i][j] += dfs(grid, x, y);\n      dp[i][j] %= kMod;\n    }\n\n    return dp[i][j];\n  }\n}","hash":"c2d0a8ae7cb201c8183623672df90dc8a17497c1f2c445c5c37e51561fc4bf0f","origins":[{"source":"solutions","path":"2328-Number-of-Increasing-Paths-in-a-Grid/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def countPaths(self, grid: List[List[int]]) -> int:\n    kMod = 1_000_000_007\n    m = len(grid)\n    n = len(grid[0])\n    dirs = [0, 1, 0, -1, 0]\n\n    # dp(i, j) := # of increasing paths starting from (i, j)\n    @functools.lru_cache(None)\n    def dp(i: int, j: int) -> int:\n      ans = 1  # Current cell contributes 1 length\n      for k in range(4):\n        x = i + dirs[k]\n        y = j + dirs[k + 1]\n        if x < 0 or x == m or y < 0 or y == n:\n          continue\n        if grid[x][y] <= grid[i][j]:\n          continue\n        ans += dp(x, y)\n        ans %= kMod\n      return ans\n\n    return sum(dp(i, j)\n               for i in range(m)\n               for j in range(n)) % kMod","hash":"6bf49156ec5b6af8b2b4bd9130114b3100b238cecab8931286b9ecee7b134bd3","origins":[{"source":"solutions","path":"2328-Number-of-Increasing-Paths-in-a-Grid/solution.py"}]}],"sources":["solutions"]},"lc-2336":{"key":"lc-2336","number":2336,"title":"smallest positive number infinite set","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class SmallestInfiniteSet {\n public:\n  int popSmallest() {\n    if (added.empty())\n      return curr++;\n    const int min = *begin(added);\n    added.erase(begin(added));\n    return min;\n  }\n\n  void addBack(int num) {\n    if (num < curr)\n      added.insert(num);\n  }\n\n private:\n  int curr = 1;\n  set<int> added;\n};","hash":"bae70445a33a84b4c86ee4a48404ece454d5c0f5cacb70f64f0f81789fdcbc74","origins":[{"source":"solutions","path":"2336-smallest-positive-number-infinite-set/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class SmallestInfiniteSet {\n  public int popSmallest() {\n    if (added.isEmpty())\n      return curr++;\n    final int min = added.first();\n    added.remove(min);\n    return min;\n  }\n\n  public void addBack(int num) {\n    if (num < curr)\n      added.add(num);\n  }\n\n  private int curr = 1;\n  private TreeSet<Integer> added = new TreeSet<>();\n}","hash":"7ace08c67d18027abbaf9d945f53927753973ef032c9f612f26686e5dd607ac6","origins":[{"source":"solutions","path":"2336-smallest-positive-number-infinite-set/solution.java"}]},{"language":"python","name":"solution.py","code":"class SmallestInfiniteSet:\n\n    def __init__(self):\n        self.st = deque([1])\n        self.set = set([1])\n    def popSmallest(self) -> int:\n        m = self.st.pop()\n        self.set.remove(m)\n        if not self.st:\n            self.st.append(m+1)\n            self.set.add(m+1)\n        return m\n\n    def addBack(self, num: int) -> None:\n        if num < self.st[-1]:\n            self.st.append(num)\n            self.set.add(num)\n            return\n        \n        \n        # TODO: use bin search\n        if num in self.set or num > self.st[0]:\n            return\n        \n        for i,x in enumerate(self.st):\n            if x < num:\n                break\n        self.st.insert(i, num)\n        self.set.add(num)","hash":"9931d4d388ece48b01711c451f3b393f5015e0dfd7e6b2933e95c043e927c3c9","origins":[{"source":"solutions","path":"2336-smallest-positive-number-infinite-set/solution.py"}]}],"sources":["solutions"]},"lc-2352":{"key":"lc-2352","number":2352,"title":"Equal Row and Column Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int equalPairs(vector<vector<int>>& grid) {\n    const int n = grid.size();\n    int ans = 0;\n\n    for (int i = 0; i < n; ++i)\n      for (int j = 0; j < n; ++j) {\n        int k = 0;\n        for (; k < n; ++k)\n          if (grid[i][k] != grid[k][j])\n            break;\n        if (k == n)  // R[i] == C[j]\n          ++ans;\n      }\n\n    return ans;\n  }\n};","hash":"ba1772558455800f48f29e4ee19c9b12f1c974aea48bff6205d99575efc5a708","origins":[{"source":"solutions","path":"2352-Equal-Row-and-Column-Pairs/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int equalPairs(int[][] grid) {\n    final int n = grid.length;\n    int ans = 0;\n\n    for (int i = 0; i < n; ++i)\n      for (int j = 0; j < n; ++j) {\n        int k = 0;\n        for (; k < n; ++k)\n          if (grid[i][k] != grid[k][j])\n            break;\n        if (k == n) // R[i] == C[j]\n          ++ans;\n      }\n\n    return ans;\n  }\n}","hash":"a8f37f75eba3e98df73573a6aee6c1241932620cfdb4733e00c0cfc9a4e3356a","origins":[{"source":"solutions","path":"2352-Equal-Row-and-Column-Pairs/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def equalPairs(self, grid: List[List[int]]) -> int:\n    n = len(grid)\n    ans = 0\n\n    for i in range(n):\n      for j in range(n):\n        k = 0\n        while k < n:\n          if grid[i][k] != grid[k][j]:\n            break\n          k += 1\n        if k == n:  # R[i] == C[j]\n          ans += 1\n\n    return ans","hash":"daf9bfca130d3e6871cf6ae38137f66c674c539bdbf95387f230fea410dc6ee6","origins":[{"source":"solutions","path":"2352-Equal-Row-and-Column-Pairs/solution.py"}]}],"sources":["solutions"]},"lc-2359":{"key":"lc-2359","number":2359,"title":"Find Closest Node to Given Two Nodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"solution.py","code":"class Solution(object):\n    def closestMeetingNode(self, edges, node1, node2):\n        n = len(edges)\n        \n        def getDist(start, n):\n            queue = [start]\n            d = [float('inf') for i in range(n)]\n            d[start] = 0\n            while queue:\n                node = queue.pop(0)\n                x = edges[node]\n                if x == -1:\n                    continue\n                if (d[node]+1 < d[x]):\n                    d[x] = d[node]+1\n                    queue.append(x)\n            return d\n        \n        d1 = getDist(node1, n)\n        d2 = getDist(node2, n)\n        ans = -1\n        index = -1\n        for i in range(n):\n            if d1[i] == float('inf') or d2[i] == float('inf'):\n                continue\n            dist = max(d1[i], d2[i])\n            if ans == -1 or dist < ans:\n                ans = dist\n                index = i\n        return index","hash":"97c8a7030aa430ff5fed58d7dc52c4b9becd7924f3e73a3a85b8d65b3f4abb13","origins":[{"source":"solutions","path":"2359-Find Closest Node to Given Two Nodes/solution.py"}]},{"language":"python","name":"Find Closest Node to Given Two Nodes.py","code":"class Solution:\n    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:\n        n = len(edges)\n        def bfs(startNode):\n            queue = deque([startNode])\n            visited = set()\n            distance = [float('inf')] * n\n            distance[startNode] = 0\n            while queue:\n                node = queue.popleft()\n                if node in visited:\n                    continue\n                visited.add(node)\n                neighbour = edges[node]\n                if neighbour != -1 and neighbour not in visited:\n                    distance[neighbour] = 1 + distance[node]\n                    queue.append(neighbour)\n            return distance\n        dist1 = bfs(node1)\n        dist2 = bfs(node2)\n        minimumDistanceNode, minimumDistanceTillNow = -1, float('inf')\n        for cuurentNode in range(n):\n            if minimumDistanceTillNow > max(dist1[cuurentNode], dist2[cuurentNode]):\n                minimumDistanceNode = cuurentNode\n                minimumDistanceTillNow = max(dist1[cuurentNode], dist2[cuurentNode])\n        return minimumDistanceNode","hash":"adaa0b6f0d3a9d46d5674354eccf93aae5df8d6184d79bd5228ef0a85e6834d5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Find Closest Node to Given Two Nodes.py"}]}],"sources":["solutions"]},"lc-2366":{"key":"lc-2366","number":2366,"title":"Minimum Replacements to Sort the Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long minimumReplacement(vector<int>& nums) {\n    long long ans = 0;\n\n    int max = nums.back();\n    for (int i = nums.size() - 2; i >= 0; --i) {\n      const int ops = (nums[i] - 1) / max;\n      ans += ops;\n      max = nums[i] / (ops + 1);\n    }\n\n    return ans;\n  }\n};","hash":"d33955c8888e225b4691f26f091d0f2cd5985b227170eed8daf46f7ce231545a","origins":[{"source":"solutions","path":"2366-Minimum Replacements to Sort the Array/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long minimumReplacement(int[] nums) {\n    long ans = 0;\n\n    int max = nums[nums.length - 1];\n    for (int i = nums.length - 2; i >= 0; --i) {\n      final int ops = (nums[i] - 1) / max;\n      ans += ops;\n      max = nums[i] / (ops + 1);\n    }\n\n    return ans;\n  }\n}","hash":"1054dcf083d5d8ea23d024267530b7ee4f194f486b429095080e7c7e68fc0997","origins":[{"source":"solutions","path":"2366-Minimum Replacements to Sort the Array/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def minimumReplacement(self, nums: List[int]) -> int:\n    ans = 0\n\n    max = nums[-1]\n    for i in range(len(nums) - 2, -1, -1):\n      ops = (nums[i] - 1) // max\n      ans += ops\n      max = nums[i] // (ops + 1)\n\n    return ans","hash":"fdf6e6ccd67fdcf55a3a849cfdc70ac31b8177cf42a68874414b1f9d9381a67d","origins":[{"source":"solutions","path":"2366-Minimum Replacements to Sort the Array/solution.py"}]}],"sources":["solutions"]},"lc-2369":{"key":"lc-2369","number":2369,"title":"check if there is valid partition","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\npublic:\n    bool validPartition(std::vector<int>& nums) {\n        int n = nums.size();\n        \n        // If the array has only one element, then it's not possible to partition it into valid subarrays\n        if (n == 1) {\n            return false;\n        }\n        \n        // Initialization for the first three values\n        bool dp_3 = true, dp_2 = false, dp_1 = (n > 1 && nums[0] == nums[1]);\n        \n        for (int i = 2; i < n; i++) {\n            bool dp = false;\n            \n            // Check for 2 equal elements\n            if (nums[i] == nums[i-1] && dp_2) {\n                dp = true;\n            }\n            // Check for 3 equal elements\n            else if (i-2 >= 0 && nums[i] == nums[i-1] && nums[i] == nums[i-2] && dp_3) {\n                dp = true;\n            }\n            // Check for 3 consecutive increasing elements\n            else if (i-2 >= 0 && nums[i] - nums[i-1] == 1 && nums[i-1] - nums[i-2] == 1 && dp_3) {\n                dp = true;\n            }\n\n            // Move the window forward\n            dp_3 = dp_2;\n            dp_2 = dp_1;\n            dp_1 = dp;\n        }\n\n        return dp_1;\n    }\n};","hash":"bb0b7942691f29f26fbb926d303fcf9a221cf2b1418fa1413a0c33a71658c914","origins":[{"source":"solutions","path":"2369-check-if-there-is--valid-partition/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public boolean validPartition(int[] nums) {\n    final int n = nums.length;\n    // dp[i] := true if there's a valid partition for first i elements\n    boolean[] dp = new boolean[n + 1];\n    dp[0] = true;\n    dp[2] = nums[0] == nums[1];\n\n    for (int i = 3; i <= n; ++i)\n      dp[i] = (dp[i - 2] && nums[i - 2] == nums[i - 1]) ||\n              (dp[i - 3] && ((nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) ||\n                             (nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1])));\n\n    return dp[n];\n  }\n}","hash":"638432d5a2c5533711292f7ca5611c5946434ade176fa461ee5a82c2635f6bd9","origins":[{"source":"solutions","path":"2369-check-if-there-is--valid-partition/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution {\n  public boolean validPartition(int[] nums) {\n    final int n = nums.length;\n    // dp[i] := true if there's a valid partition for first i elements\n    boolean[] dp = new boolean[n + 1];\n    dp[0] = true;\n    dp[2] = nums[0] == nums[1];\n\n    for (int i = 3; i <= n; ++i)\n      dp[i] = (dp[i - 2] && nums[i - 2] == nums[i - 1]) ||\n              (dp[i - 3] && ((nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) ||\n                             (nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1])));\n\n    return dp[n];\n  }\n}","hash":"e9e7364b58f791379672478c8ee7001ac4cf1f5762568b68b532f7609724a747","origins":[{"source":"solutions","path":"2369-check-if-there-is--valid-partition/solution.py"}]}],"sources":["solutions"]},"lc-2444":{"key":"lc-2444","number":2444,"title":"count subarrays with fixed bounds","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long countSubarrays(vector<int>& nums, int minK, int maxK) {\n    long long ans = 0;\n    int j = -1;\n    int prevMinKIndex = -1;\n    int prevMaxKIndex = -1;\n\n    for (int i = 0; i < nums.size(); ++i) {\n      if (nums[i] < minK || nums[i] > maxK)\n        j = i;\n      if (nums[i] == minK)\n        prevMinKIndex = i;\n      if (nums[i] == maxK)\n        prevMaxKIndex = i;\n      // any index k in [j + 1, min(prevMinKIndex, prevMaxKIndex)] can be the\n      // start of the subarray s.t. nums[k..i] satisfies the conditions\n      ans += max(0, min(prevMinKIndex, prevMaxKIndex) - j);\n    }\n\n    return ans;\n  }\n};","hash":"45f07238ae88dd82800b3550bcc6f20de1f1f7afcfab0e6dbf76ec9adadbfc20","origins":[{"source":"solutions","path":"2444-count-subarrays-with-fixed-bounds/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long countSubarrays(int[] nums, int minK, int maxK) {\n    long ans = 0;\n    int j = -1;\n    int prevMinKIndex = -1;\n    int prevMaxKIndex = -1;\n\n    for (int i = 0; i < nums.length; ++i) {\n      if (nums[i] < minK || nums[i] > maxK)\n        j = i;\n      if (nums[i] == minK)\n        prevMinKIndex = i;\n      if (nums[i] == maxK)\n        prevMaxKIndex = i;\n      // any index k in [j + 1, min(prevMinKIndex, prevMaxKIndex)] can be the\n      // start of the subarray s.t. nums[k..i] satisfies the conditions\n      ans += Math.max(0, Math.min(prevMinKIndex, prevMaxKIndex) - j);\n    }\n\n    return ans;\n  }\n}","hash":"3a70ca9d0c0cb0ea7f37164e3124570a081741cf5d6baee70a1beb174b1d2cb1","origins":[{"source":"solutions","path":"2444-count-subarrays-with-fixed-bounds/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def countSubarrays(self, nums: List[int], minK: int, maxK: int) -> int:\n    ans = 0\n    j = -1\n    prevMinKIndex = -1\n    prevMaxKIndex = -1\n\n    for i, num in enumerate(nums):\n      if num < minK or num > maxK:\n        j = i\n      if num == minK:\n        prevMinKIndex = i\n      if num == maxK:\n        prevMaxKIndex = i\n      # any index k in [j + 1, min(prevMinKIndex, prevMaxKIndex)] can be the\n      # start of the subarray s.t. nums[k..i] satisfies the conditions\n      ans += max(0, min(prevMinKIndex, prevMaxKIndex) - j)\n\n    return ans","hash":"faae5447a92db93bad864f20cddf3e6c495bec0856764fd4393e8e05e409b6bd","origins":[{"source":"solutions","path":"2444-count-subarrays-with-fixed-bounds/solution.py"}]},{"language":"python","name":"Count Subarrays With Fixed Bounds.py","code":"class Solution:\n    def countSubarrays(self, nums: List[int], minK: int, maxK: int) -> int:\n        # min_position, max_position: the MOST RECENT positions of minK and maxK.\n        # left_bound: the MOST RECENT value outside the range [minK, maxK].\n        result, minPosition, maxPosition, leftBound = 0, -1, -1, -1\n        # Iterate over nums, for each number at index i:\n        for i, number in enumerate(nums):\n            # If the number is outside the range [minK, maxK], update the most recent left_bound.\n            if number < minK or number > maxK:\n                leftBound = i\n            # If the number is minK or maxK, update the most recent position.\n            if number == minK:\n                minPosition = i\n            if number == maxK:\n                maxPosition = i\n            # The number of valid subarrays equals the number of elements between left_bound and \n            # the smaller of the two most recent positions.\n            result += max(0, min(minPosition, maxPosition) - leftBound)\n        return result","hash":"e2fc0e51ceeea36f42fdf166a7bc5a0b9fd461ade890c964349de9fce393f349","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Count Subarrays With Fixed Bounds.py"}]}],"sources":["solutions"]},"lc-2448":{"key":"lc-2448","number":2448,"title":"minimum cost to make array equal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long minCost(vector<int>& nums, vector<int>& cost) {\n    long long ans = 0;\n    int l = *min_element(nums.begin(), nums.end());\n    int r = *max_element(nums.begin(), nums.end());\n\n    while (l < r) {\n      const int m = (l + r) / 2;\n      const long long cost1 = getCost(nums, cost, m);\n      const long long cost2 = getCost(nums, cost, m + 1);\n      ans = min(cost1, cost2);\n      if (cost1 < cost2)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return ans;\n  }\n\n private:\n  long long getCost(const vector<int>& nums, const vector<int>& cost,\n                    int target) {\n    long long res = 0;\n    for (int i = 0; i < nums.size(); ++i)\n      res += abs(nums[i] - target) * static_cast<long long>(cost[i]);\n    return res;\n  }\n};","hash":"414e44f52e462c21fb31195fa322291f77adafe5f217990cd66f504bea2045b8","origins":[{"source":"solutions","path":"2448-minimum-cost-to-make-array-equal/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long minCost(int[] nums, int[] cost) {\n    long ans = 0;\n    int l = Arrays.stream(nums).min().getAsInt();\n    int r = Arrays.stream(nums).max().getAsInt();\n\n    while (l < r) {\n      final int m = (l + r) / 2;\n      final long cost1 = getCost(nums, cost, m);\n      final long cost2 = getCost(nums, cost, m + 1);\n      ans = Math.min(cost1, cost2);\n      if (cost1 < cost2)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return ans;\n  }\n\n  private long getCost(int[] nums, int[] cost, int target) {\n    long res = 0;\n    for (int i = 0; i < nums.length; ++i)\n      res += Math.abs(nums[i] - target) * (long) cost[i];\n    return res;\n  }\n}","hash":"80bc977b16891d80588519895ac715575173324f16404fc1d2207ddf2a3e697a","origins":[{"source":"solutions","path":"2448-minimum-cost-to-make-array-equal/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def minCost(self, nums: List[int], cost: List[int]) -> int:\n    ans = 0\n    l = min(nums)\n    r = max(nums)\n\n    def getCost(target: int) -> int:\n      return sum(abs(num - target) * c for num, c in zip(nums, cost))\n\n    while l < r:\n      m = (l + r) // 2\n      cost1 = getCost(m)\n      cost2 = getCost(m + 1)\n      ans = min(cost1, cost2)\n      if cost1 < cost2:\n        r = m\n      else:\n        l = m + 1\n\n    return ans","hash":"c3813aa900ad7273f770653ea0dc2c13237d494e1418cbedb483091245b68f58","origins":[{"source":"solutions","path":"2448-minimum-cost-to-make-array-equal/solution.py"}]}],"sources":["solutions"]},"lc-2462":{"key":"lc-2462","number":2462,"title":"Total Cost to Hire K Workers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long totalCost(vector<int>& costs, int k, int candidates) {\n    long long ans = 0;\n    int i = 0;\n    int j = costs.size() - 1;\n    priority_queue<int, vector<int>, greater<>> minHeapL;\n    priority_queue<int, vector<int>, greater<>> minHeapR;\n\n    for (int hired = 0; hired < k; ++hired) {\n      while (minHeapL.size() < candidates && i <= j)\n        minHeapL.push(costs[i++]);\n      while (minHeapR.size() < candidates && i <= j)\n        minHeapR.push(costs[j--]);\n      if (minHeapL.empty())\n        ans += minHeapR.top(), minHeapR.pop();\n      else if (minHeapR.empty())\n        ans += minHeapL.top(), minHeapL.pop();\n      // Both `minHeapL` and `minHeapR` are not empty.\n      else if (minHeapL.top() <= minHeapR.top())\n        ans += minHeapL.top(), minHeapL.pop();\n      else\n        ans += minHeapR.top(), minHeapR.pop();\n    }\n\n    return ans;\n  }\n};","hash":"ec96cd7b38fc1563ac2889f1e573ee21bb98d9c2df00b536fdd6c1c616dd4aee","origins":[{"source":"solutions","path":"2462-Total Cost to Hire K Workers/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long totalCost(int[] costs, int k, int candidates) {\n    long ans = 0;\n    int i = 0;\n    int j = costs.length - 1;\n    Queue<Integer> minHeapL = new PriorityQueue<>();\n    Queue<Integer> minHeapR = new PriorityQueue<>();\n\n    for (int hired = 0; hired < k; ++hired) {\n      while (minHeapL.size() < candidates && i <= j)\n        minHeapL.offer(costs[i++]);\n      while (minHeapR.size() < candidates && i <= j)\n        minHeapR.offer(costs[j--]);\n      if (minHeapL.isEmpty())\n        ans += minHeapR.poll();\n      else if (minHeapR.isEmpty())\n        ans += minHeapL.poll();\n      // Both `minHeapL` and `minHeapR` are not empty.\n      else if (minHeapL.peek() <= minHeapR.peek())\n        ans += minHeapL.poll();\n      else\n        ans += minHeapR.poll();\n    }\n\n    return ans;\n  }\n}","hash":"1695d4a5f2f32d41a19ffd82041d39eb7e8516bc2ce602b266d2015cc3d3f9ef","origins":[{"source":"solutions","path":"2462-Total Cost to Hire K Workers/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def totalCost(self, costs: List[int], k: int, candidates: int) -> int:\n    ans = 0\n    i = 0\n    j = len(costs) - 1\n    minHeapL = []  # First half\n    minHeapR = []  # Second half\n\n    for _ in range(k):\n      while len(minHeapL) < candidates and i <= j:\n        heapq.heappush(minHeapL, costs[i])\n        i += 1\n      while len(minHeapR) < candidates and i <= j:\n        heapq.heappush(minHeapR, costs[j])\n        j -= 1\n      if not minHeapL:\n        ans += heapq.heappop(minHeapR)\n      elif not minHeapR:\n        ans += heapq.heappop(minHeapL)\n      # Both `minHeapL` and `minHeapR` are not empty.\n      elif minHeapL[0] <= minHeapR[0]:\n        ans += heapq.heappop(minHeapL)\n      else:\n        ans += heapq.heappop(minHeapR)\n\n    return ans","hash":"ebb677facbc84fff4f4ec115c0114ca68d85056908d2d763f64287d92149b9c2","origins":[{"source":"solutions","path":"2462-Total Cost to Hire K Workers/solution.py"}]}],"sources":["solutions"]},"lc-2466":{"key":"lc-2466","number":2466,"title":"count ways to build good strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int countGoodStrings(int low, int high, int zero, int one) {\n    constexpr int kMod = 1'000'000'007;\n    int ans = 0;\n    // dp[i] := # of good strings with length i\n    vector<int> dp(high + 1);\n    dp[0] = 1;\n\n    for (int i = 1; i <= high; ++i) {\n      if (i >= zero)\n        dp[i] = (dp[i] + dp[i - zero]) % kMod;\n      if (i >= one)\n        dp[i] = (dp[i] + dp[i - one]) % kMod;\n      if (i >= low)\n        ans = (ans + dp[i]) % kMod;\n    }\n\n    return ans;\n  }\n};","hash":"6c380d954fe63c43c7a27405b28ee612f5585fc1650043e4a8b17fad6fbfce5d","origins":[{"source":"solutions","path":"2466-count-ways-to-build-good-strings/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int countGoodStrings(int low, int high, int zero, int one) {\n    final int kMod = 1_000_000_007;\n    int ans = 0;\n    // dp[i] := # of good strings with length i\n    int[] dp = new int[high + 1];\n    dp[0] = 1;\n\n    for (int i = 1; i <= high; ++i) {\n      if (i >= zero)\n        dp[i] = (dp[i] + dp[i - zero]) % kMod;\n      if (i >= one)\n        dp[i] = (dp[i] + dp[i - one]) % kMod;\n      if (i >= low)\n        ans = (ans + dp[i]) % kMod;\n    }\n\n    return ans;\n  }\n}","hash":"4e2a828cedf25d3022a925b2a4a5eb2da227ca65acad7eea53485d31b2775e00","origins":[{"source":"solutions","path":"2466-count-ways-to-build-good-strings/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def countGoodStrings(self, low: int, high: int, zero: int, one: int) -> int:\n    kMod = 1_000_000_007\n    ans = 0\n    # dp[i] := # of good strings with length i\n    dp = [1] + [0] * high\n\n    for i in range(1, high + 1):\n      if i >= zero:\n        dp[i] = (dp[i] + dp[i - zero]) % kMod\n      if i >= one:\n        dp[i] = (dp[i] + dp[i - one]) % kMod\n      if i >= low:\n        ans = (ans + dp[i]) % kMod\n\n    return ans","hash":"4e6e751b2687ca772ca5b07cab347d6a9e29ce35b6ca86cb2710d52daf1f9f1d","origins":[{"source":"solutions","path":"2466-count-ways-to-build-good-strings/solution.py"}]}],"sources":["solutions"]},"lc-2483":{"key":"lc-2483","number":2483,"title":"minimum penalty for a shop","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int bestClosingTime(string customers) {\n    // Instead of computing the minimum penalty, we can compute the max profit.\n    int ans = 0;\n    int profit = 0;\n    int maxProfit = 0;\n\n    for (int i = 0; i < customers.length(); ++i) {\n      profit += customers[i] == 'Y' ? 1 : -1;\n      if (profit > maxProfit) {\n        maxProfit = profit;\n        ans = i + 1;\n      }\n    }\n\n    return ans;\n  }\n};","hash":"55534a186e89d896a852637234d5807da09abab5f2d7ad3ea854c9924160aefb","origins":[{"source":"solutions","path":"2483-minimum-penalty-for-a-shop/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int bestClosingTime(String customers) {\n    // Instead of computing the minimum penalty, we can compute the max profit.\n    int ans = 0;\n    int profit = 0;\n    int maxProfit = 0;\n\n    for (int i = 0; i < customers.length(); ++i) {\n      profit += customers.charAt(i) == 'Y' ? 1 : -1;\n      if (profit > maxProfit) {\n        maxProfit = profit;\n        ans = i + 1;\n      }\n    }\n\n    return ans;\n  }\n}","hash":"dad20cd508ba353b2be572c845e3d7b56fe09999a787d58c50816f44234cd8cf","origins":[{"source":"solutions","path":"2483-minimum-penalty-for-a-shop/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def bestClosingTime(self, customers: str) -> int:\n    # Instead of computing the minimum penalty, we can compute the max profit.\n    ans = 0\n    profit = 0\n    maxProfit = 0\n\n    for i, customer in enumerate(customers):\n      profit += 1 if customer == 'Y' else -1\n      if profit > maxProfit:\n        maxProfit = profit\n        ans = i + 1\n\n    return ans","hash":"47ab86dcd54406c8ba040d6cd11710e7ef6973aa56706e945cb3974602285e05","origins":[{"source":"solutions","path":"2483-minimum-penalty-for-a-shop/solution.py"}]}],"sources":["solutions"]},"lc-2542":{"key":"lc-2542","number":2542,"title":"Maximum Subsequence Score","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  \n  long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {\n    long long ans = 0;\n    long long sum = 0;\n    \n    vector<pair<int, int>> A;\n    priority_queue<int, vector<int>, greater<>> minHeap;\n\n    for (int i = 0; i < nums1.size(); ++i)\n      A.emplace_back(nums2[i], nums1[i]);\n\n    sort(begin(A), end(A), greater<>());\n\n    for (const auto& [num2, num1] : A) {\n      minHeap.push(num1);\n      sum += num1;\n      if (minHeap.size() > k)\n        sum -= minHeap.top(), minHeap.pop();\n      if (minHeap.size() == k)\n        ans = max(ans, sum * num2);\n    }\n\n    return ans;\n  }\n};","hash":"ccb8a92728fb67fc54c03bd68ca5dc2b3a4277dc20311c91501feb930240f4d9","origins":[{"source":"solutions","path":"2542-Maximum-Subsequence-Score/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  \n  public long maxScore(int[] nums1, int[] nums2, int k) {\n    long ans = 0;\n    long sum = 0;\n    \n    Pair<Integer, Integer>[] A = new Pair[nums1.length];\n    Queue<Integer> minHeap = new PriorityQueue<>();\n\n    for (int i = 0; i < nums1.length; ++i)\n      A[i] = new Pair<>(nums2[i], nums1[i]);\n\n    Arrays.sort(A, (a, b) -> Integer.compare(b.getKey(), a.getKey()));\n\n    for (Pair<Integer, Integer> a : A) {\n      final int num2 = a.getKey();\n      final int num1 = a.getValue();\n      minHeap.offer(num1);\n      sum += num1;\n      if (minHeap.size() > k)\n        sum -= minHeap.poll();\n      if (minHeap.size() == k)\n        ans = Math.max(ans, sum * num2);\n    }\n\n    return ans;\n  }\n}","hash":"d95cb11121c73649301c425851e31c3d00edfabb515ff445cd7bae238f415c11","origins":[{"source":"solutions","path":"2542-Maximum-Subsequence-Score/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  \n  def maxScore(self, nums1: List[int], nums2: List[int], k: int) -> int:\n    ans = 0\n    summ = 0\n    \n    A = sorted([(num2, num1)\n               for num1, num2 in zip(nums1, nums2)], reverse=True)\n    minHeap = []\n\n    for num2, num1 in A:\n      heapq.heappush(minHeap, num1)\n      summ += num1\n      if len(minHeap) > k:\n        summ -= heapq.heappop(minHeap)\n      if len(minHeap) == k:\n        ans = max(ans, summ * num2)\n\n    return ans","hash":"754b97131c386126369e23e5ec935a92b5d8e88932fc409a53133382f0674a21","origins":[{"source":"solutions","path":"2542-Maximum-Subsequence-Score/solution.py"}]}],"sources":["solutions"]},"lc-2551":{"key":"lc-2551","number":2551,"title":"Put Marbles in Bags","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  long long putMarbles(vector<int>& weights, int k) {\n    // To distribute marbles into k bags, there will be k - 1 cuts. If there's a\n    // cut after weights[i], then weights[i] and weights[i + 1] will be added to\n    // the cost. Also, no matter how we cut, weights[0] and weights[n - 1] will\n    // be counted. So, the goal is to find the max/min k - 1 weights[i] +\n    // weights[i + 1].\n    vector<int> A;  // weights[i] + weights[i + 1]\n    long long min = 0;\n    long long max = 0;\n\n    for (int i = 0; i + 1 < weights.size(); ++i)\n      A.push_back(weights[i] + weights[i + 1]);\n\n    sort(A.begin(), A.end());\n\n    for (int i = 0; i < k - 1; ++i) {\n      min += A[i];\n      max += A[A.size() - 1 - i];\n    }\n\n    return max - min;\n  }\n};","hash":"efc15b34dfed422099111ce14f02d4d2ed803963e919a9f88e43b7aa0329f1d9","origins":[{"source":"solutions","path":"2551-Put Marbles in Bags/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public long putMarbles(int[] weights, int k) {\n    // To distribute marbles into k bags, there will be k - 1 cuts. If there's a\n    // cut after weights[i], then weights[i] and weights[i + 1] will be added to\n    // the cost. Also, no matter how we cut, weights[0] and weights[n - 1] will\n    // be counted. So, the goal is to find the max/min k - 1 weights[i] +\n    // weights[i + 1].\n    int[] A = new int[weights.length - 1]; // weights[i] + weights[i + 1]\n    long min = 0;\n    long max = 0;\n\n    for (int i = 0; i < A.length; ++i)\n      A[i] = weights[i] + weights[i + 1];\n\n    Arrays.sort(A);\n\n    for (int i = 0; i < k - 1; ++i) {\n      min += A[i];\n      max += A[A.length - 1 - i];\n    }\n\n    return max - min;\n  }\n}","hash":"c355505e5c7dcee37c0a5e9aa602be7dab086376226c4761c33d95119b2fb240","origins":[{"source":"solutions","path":"2551-Put Marbles in Bags/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def putMarbles(self, weights: List[int], k: int) -> int:\n    # To distribute marbles into k bags, there will be k - 1 cuts. If there's a\n    # cut after weights[i], then weights[i] and weights[i + 1] will be added to\n    # the cost. Also, no matter how we cut, weights[0] and weights[n - 1] will\n    # be counted. So, the goal is to find the max//min k - 1 weights[i] +\n    # weights[i + 1].\n\n    # weights[i] + weights[i + 1]\n    A = [a + b for a, b in itertools.pairwise(weights)]\n    return sum(heapq.nlargest(k - 1, A)) - sum(heapq.nsmallest(k - 1, A))","hash":"942907e752687efa7afc8585b309c3b264a91b669f7ef59f7baf5a534fecff1e","origins":[{"source":"solutions","path":"2551-Put Marbles in Bags/solution.py"}]}],"sources":["solutions"]},"lc-2616":{"key":"lc-2616","number":2616,"title":"Minimize the Maximum Difference of Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"cpp","name":"solution.cpp","code":"class Solution {\n public:\n  int minimizeMax(vector<int>& nums, int p) {\n    sort(nums.begin(), nums.end());\n\n    int l = 0;\n    int r = nums.back() - nums.front();\n\n    while (l < r) {\n      const int m = (l + r) / 2;\n      if (numPairs(nums, m) >= p)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return l;\n  }\n\n private:\n  // Returns the # of pairs that can be obtained if the difference between each\n  // pair <= `maxDiff`.\n  int numPairs(const vector<int>& nums, int maxDiff) {\n    int pairs = 0;\n    for (int i = 1; i < nums.size(); ++i)\n      // Greedily pair nums[i] with nums[i - 1].\n      if (nums[i] - nums[i - 1] <= maxDiff) {\n        ++pairs;\n        ++i;\n      }\n    return pairs;\n  }\n};","hash":"3b95547711b16dea1881931696baae84e38f817e88c0751a8af8b8ee21585271","origins":[{"source":"solutions","path":"2616-Minimize the Maximum Difference of Pairs/solution.cpp"}]},{"language":"java","name":"solution.java","code":"class Solution {\n  public int minimizeMax(int[] nums, int p) {\n    Arrays.sort(nums);\n\n    int l = 0;\n    int r = nums[nums.length - 1] - nums[0];\n\n    while (l < r) {\n      final int m = (l + r) / 2;\n      if (numPairs(nums, m) >= p)\n        r = m;\n      else\n        l = m + 1;\n    }\n\n    return l;\n  }\n\n  // Returns the # of pairs that can be obtained if the difference between each\n  // pair <= `maxDiff`.\n  private int numPairs(int[] nums, int maxDiff) {\n    int pairs = 0;\n    for (int i = 1; i < nums.length; ++i)\n      // Greedily pair nums[i] with nums[i - 1].\n      if (nums[i] - nums[i - 1] <= maxDiff) {\n        ++pairs;\n        ++i;\n      }\n    return pairs;\n  }\n}","hash":"212049747735be86c9bcc6f47fca24172f4b0718fadafee28a701c222fc4ebd8","origins":[{"source":"solutions","path":"2616-Minimize the Maximum Difference of Pairs/solution.java"}]},{"language":"python","name":"solution.py","code":"class Solution:\n  def minimizeMax(self, nums: List[int], p: int) -> int:\n    nums.sort()\n\n    # Returns the # of pairs that can be obtained if the difference between each\n    # pair <= `maxDiff`.\n    def numPairs(maxDiff: int) -> int:\n      pairs = 0\n      i = 1\n      while i < len(nums):\n        # Greedily pair nums[i] with nums[i - 1].\n        if nums[i] - nums[i - 1] <= maxDiff:\n          pairs += 1\n          i += 2\n        else:\n          i += 1\n      return pairs\n\n    return bisect.bisect_left(\n        range(0, nums[-1] - nums[0]), p,\n        key=lambda m: numPairs(m))","hash":"a0808a1927cdd937aa34b377d315a10e08603bccf0cb913dfd9bd602ced841df","origins":[{"source":"solutions","path":"2616-Minimize the Maximum Difference of Pairs/solution.py"}]}],"sources":["solutions"]},"topic-01aug77combinations":{"key":"topic-01aug77combinations","number":null,"title":"01 AUG 77 Combinations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-AUG 77 Combinations.py","code":"class Solution:\n    def combine(self, n: int, k: int) -> List[List[int]]:\n        result = []\n        def backtrack(startIndex, currentCombination):\n            if len(currentCombination) == k:\n                result.append(list(currentCombination))\n                return\n            for i in range(startIndex, n + 1):\n                currentCombination.append(i)\n                backtrack(i + 1, currentCombination)\n                currentCombination.pop()\n        backtrack(1, [])\n        return result","hash":"acb281eb9ac13ed31aaaa09eaf34d1bb8aefec68e7df2cd1ea853318d73bae1c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/01-AUG 77 Combinations.py"}]}],"sources":["solutions"]},"topic-01jan455assigncookies":{"key":"topic-01jan455assigncookies","number":null,"title":"01 JAN 455 Assign Cookies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-JAN 455 Assign Cookies.py","code":"class Solution:\n    def findContentChildren(self, g: List[int], s: List[int]) -> int:\n        g.sort()\n        s.sort()\n        satisfiedChildren, childIndex, cookieIndex = 0, 0, 0\n        while childIndex < len(g) and cookieIndex < len(s):\n            if s[cookieIndex] >= g[childIndex]:\n                satisfiedChildren += 1\n                childIndex += 1\n            cookieIndex += 1\n        return satisfiedChildren","hash":"7a68f1bf1c7e09da8f43d7d42314dec54d5385a1222a0cf0bc81ebd272ee6b89","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/01-JAN 455 Assign Cookies.py"}]}],"sources":["solutions"]},"topic-01jul2305fairdistributionofcookies":{"key":"topic-01jul2305fairdistributionofcookies","number":null,"title":"01 JUL 2305 Fair Distribution of Cookies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-JUL 2305 Fair Distribution of Cookies.py","code":"class Solution:\n    def distributeCookies(self, cookies: List[int], k: int) -> int:\n        cur = [0] * k\n        n = len(cookies)\n\n        def dfs(i, zero_count):\n            # If there are not enough cookies remaining, return `float('inf')` \n            # as it leads to an invalid distribution.\n            if n - i < zero_count:\n                return float('inf')\n            \n            # After distributing all cookies, return the unfairness of this\n            # distribution.\n            if i == n:\n                return max(cur)\n            \n            # Try to distribute the i-th cookie to each child, and update answer\n            # as the minimum unfairness in these distributions.\n            answer = float('inf')\n            for j in range(k):\n                zero_count -= int(cur[j] == 0)\n                cur[j] += cookies[i]\n                \n                # Recursively distribute the next cookie.\n                answer = min(answer, dfs(i + 1, zero_count))\n                \n                cur[j] -= cookies[i]\n                zero_count += int(cur[j] == 0)\n            \n            return answer\n        \n        return dfs(0, k)","hash":"828804bafca5206d832272397ada5e9bbd71b9b9537fbcbb60c2db93247a1cac","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/01-JUL 2305 Fair Distribution of Cookies.py"}]}],"sources":["solutions"]},"topic-01jun1091shortestpathinbinarymatrix":{"key":"topic-01jun1091shortestpathinbinarymatrix","number":null,"title":"01 JUN 1091 Shortest Path in Binary Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-JUN 1091 Shortest Path in Binary Matrix.py","code":"class Solution:\n    def shortestPathBinaryMatrix(self, grid: List[List[int]]) -> int:\n        if grid[0][0] == 1 or grid[-1][-1] == 1:\n            return -1\n        queue, visited, N = deque([(0, 0, 1)]), set((0, 0)), len(grid)\n        while queue:\n            r, c, d = queue.popleft()\n            if r == N - 1 and c == N - 1:\n                return d\n            for row, col in [(r + 1, c), (r + 1, c + 1), (r, c + 1), (r - 1, c + 1), (r - 1, c), (r - 1, c - 1), (r, c - 1), (r + 1, c - 1)]:\n                if 0 <= row < N and 0 <= col < N and grid[row][col] == 0 and (row, col) not in visited:\n                    queue.append((row, col, d + 1))\n                    visited.add((row, col))\n        return -1","hash":"5bcee891c3db420d385972f264c44b1f532ac5176aec85123959077139483970","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/01-JUN 1091 Shortest Path in Binary Matrix.py"}]}],"sources":["solutions"]},"topic-01matrix":{"key":"topic-01matrix","number":null,"title":"01 Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01 Matrix.py","code":"class Solution:\n    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:\n        rows, cols = len(mat), len(mat[0])\n        dist = [[float('inf')] * cols for _ in range(rows)]\n        for i in range(rows):\n            for j in range(cols):\n                if mat[i][j] == 0:\n                    dist[i][j] = 0\n                else:\n                    if i > 0:\n                        dist[i][j] = min(dist[i][j], dist[i - 1][j] + 1)\n                    if j > 0:\n                        dist[i][j] = min(dist[i][j], dist[i][j - 1] + 1)\n        for i in range(rows - 1, -1, -1):\n            for j in range(cols - 1, -1, -1):\n                if i < rows - 1:\n                    dist[i][j] = min(dist[i][j], dist[i + 1][j] + 1)\n                if j < cols - 1:\n                    dist[i][j] = min(dist[i][j], dist[i][j + 1] + 1)\n        return dist","hash":"d2f73890653d293a4276fa308ff8c9aa1a3b53b948fd648094b16ab4f180ba1b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/01 Matrix.py"}]}],"sources":["solutions"]},"topic-01may1491averagesalaryexcludingtheminimumandmaximumsalary":{"key":"topic-01may1491averagesalaryexcludingtheminimumandmaximumsalary","number":null,"title":"01 MAY 1491 Average Salary Excluding the Minimum and Maximum Salary","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-MAY 1491 Average Salary Excluding the Minimum and Maximum Salary.py","code":"class Solution:\n    def average(self, salary: List[int]) -> float:\n        minSalary, maxSalary, sumSalary = float('inf'), float('-inf'), 0\n        for s in salary:\n            sumSalary += s\n            minSalary = min(minSalary, s)\n            maxSalary = max(maxSalary, s)\n        sumSalary -= (minSalary + maxSalary)\n        return sumSalary / (len(salary) - 2)","hash":"c00ca703da9816615d6e9588def1bbabe38f4900a6fb55153febb78d98e6cce4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/01-MAY 1491 Average Salary Excluding the Minimum and Maximum Salary.py"}]}],"sources":["solutions"]},"topic-01nov501findmodeinbinarysearchtree":{"key":"topic-01nov501findmodeinbinarysearchtree","number":null,"title":"01 NOV 501 Find Mode in Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-NOV 501 Find Mode in Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def findMode(self, root: Optional[TreeNode]) -> List[int]:\n        freq = defaultdict(int)\n        def inorder(node: Optional[TreeNode]):\n            if node:\n                inorder(node.left)\n                freq[node.val] += 1\n                inorder(node.right)\n        inorder(root)\n        maxFreq = max(freq.values())\n        return [x[0] for x in freq.items() if x[1] == maxFreq]","hash":"f7eaadb4b82f04431fd5f98c7f06a88fb43105557740c3805bfee8eb4bf739cf","origins":[{"source":"solutions","path":"November 2023 Leetcoding Challenge/01-NOV 501 Find Mode in Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-01oct557reversewordsinastringiii":{"key":"topic-01oct557reversewordsinastringiii","number":null,"title":"01 OCT 557 Reverse Words in a String III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-OCT 557 Reverse Words in a String III.py","code":"class Solution:\n    def reverseWords(self, s: str) -> str:\n        wordList = s.split(' ')\n        for i in range(len(wordList)):\n            wordList[i] = wordList[i][::-1]\n        return ' '.join(wordList)","hash":"c217a6de02d26ddabbe47b24e3a139e08a2cc02162d5b5d1ee454433e1d46658","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/01-OCT 557 Reverse Words in a String III.py"}]}],"sources":["solutions"]},"topic-01sep338countingbits":{"key":"topic-01sep338countingbits","number":null,"title":"01 SEP 338 Counting Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"01-SEP 338 Counting Bits.py","code":"class Solution:\n    def countBits(self, num: int) -> List[int]:\n        result, i, b = [0] * (num + 1), 0, 1\n        while b <= num:\n            while i < b and i + b <= num:\n                result[i + b] = result[i] + 1\n                i += 1\n            i, b = 0, b << 1\n        return result","hash":"9002edba333f304619b1bb57894642caf018176b81a34ffd1cb871a61d5d282b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/01-SEP 338 Counting Bits.py"}]}],"sources":["solutions"]},"topic-02aug46permutations":{"key":"topic-02aug46permutations","number":null,"title":"02 AUG 46 Permutations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-AUG 46 Permutations.py","code":"class Solution:\n    def permute(self, nums: List[int]) -> List[List[int]]:\n        numsCapacity, result = len(nums), []\n        def backtrack(startIndex = 0):\n            if startIndex == numsCapacity:\n                result.append(list(nums))\n            for i in range(startIndex, numsCapacity):\n                nums[startIndex], nums[i] = nums[i], nums[startIndex]\n                backtrack(startIndex + 1)\n                nums[startIndex], nums[i] = nums[i], nums[startIndex]\n        backtrack()\n        return result","hash":"45bb2fc6b59500fcd242342b5622b5470093c5ea3b819ffcc210aebaa16f954f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/02-AUG 46 Permutations.py"}]}],"sources":["solutions"]},"topic-02jan2610convertanarrayintoa2darraywithconditions":{"key":"topic-02jan2610convertanarrayintoa2darraywithconditions","number":null,"title":"02 JAN 2610 Convert an Array Into a 2D Array With Conditions","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-JAN 2610 Convert an Array Into a 2D Array With Conditions.py","code":"class Solution:\n    def findMatrix(self, nums: List[int]) -> List[List[int]]:\n        freqMap = Counter(nums)\n        result = []\n        keySet = set(freqMap)\n        while len(keySet) > 0:\n            temp = []\n            for key in keySet:\n                temp.append(key)\n                freqMap[key] -= 1\n                if freqMap[key] == 0:\n                    del freqMap[key]\n            result.append(temp)\n            keySet = set(freqMap)\n        return result","hash":"9b33904b9cf0b7ea4987e5ad8b60ef3301438e78fe088bd9ef1f63f0f73bd65e","origins":[{"source":"solutions","path":"January 2024 Leetcoding Challenge/02-JAN 2610 Convert an Array Into a 2D Array With Conditions.py"}]}],"sources":["solutions"]},"topic-02jul1601maximumnumberofachievabletransferrequests":{"key":"topic-02jul1601maximumnumberofachievabletransferrequests","number":null,"title":"02 JUL 1601 Maximum Number of Achievable Transfer Requests","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-JUL 1601 Maximum Number of Achievable Transfer Requests.py","code":"class Solution:\n    def maximumRequests(self, n: int, requests: List[List[int]]) -> int:\n        indegrees, numberOfRequests = defaultdict(int), len(requests)\n        def backtrack(currentIndex):\n            if currentIndex == numberOfRequests:\n                for key, val in indegrees.items():\n                    if val != 0:\n                        return float('-inf')\n                return 0\n            source, destination = requests[currentIndex]\n            indegrees[source] -= 1\n            indegrees[destination] += 1\n            result = 1 + backtrack(currentIndex + 1)\n            indegrees[source] += 1\n            indegrees[destination] -= 1\n            return max(result, backtrack(currentIndex + 1))\n        return backtrack(0)","hash":"89257d668733b9a7aa6bdc3dbfcff8e91129e4ceac6b7988329cc5164cffb215","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/02-JUL 1601 Maximum Number of Achievable Transfer Requests.py"}]}],"sources":["solutions"]},"topic-02jun2101detonatethemaximumbombs":{"key":"topic-02jun2101detonatethemaximumbombs","number":null,"title":"02 JUN 2101 Detonate the Maximum Bombs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"02-JUN 2101 Detonate the Maximum Bombs.py","code":"class Solution:\n    def maximumDetonation(self, bombs: List[List[int]]) -> int:\n        graph = defaultdict(list)\n        n = len(bombs)\n        # Build the graph\n        for i in range(n):\n            for j in range(n):\n                if i == j:\n                    continue\n                xi, yi, ri = bombs[i]\n                xj, yj, _ = bombs[j]\n\n                # Create a path from node i to node j, if bomb i denotes bomb j\n                if ri ** 2 >= (xi - xj) ** 2 + (yi - yj) ** 2:\n                    graph[i].append(j)\n        \n        # DFS to get the number of nodes reachable from a given node curr\n        def dfs(curr, visited):\n            visited.add(curr)\n            for neighbour in graph[curr]:\n                if neighbour not in visited:\n                    dfs(neighbour, visited)\n            return len(visited)\n        \n        result = 0\n        for i in range(n):\n            visited = set()\n            result = max(result, dfs(i, visited))\n        return result","hash":"d2a755c366decc85e598a3e673c976a5494f0bcfbe524de8ed9fdbc16080c302","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/02-JUN 2101 Detonate the Maximum Bombs.py"}]}],"sources":["solutions"]}});
